    ('8561efa6-7303-530e-a51d-a4b84b1ef822'::uuid, 'sport', 'Tle', 'Le bac d’EPS : épreuves, AFL et barème', 13, 'L’évaluation au baccalauréat')
  ) AS v(id, slug, level, title, position, theme)
