-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('b6bc0daa-9f12-5c93-9d08-14709784333d'::uuid, '11c0d2a1-156e-50dc-9293-25c2ccca1b66'::uuid, 'Quelle œuvre d’Hésiode raconte la naissance des dieux ?', 'mcq', '["L’Odyssée","La Théogonie","Le Timée","Les Argonautiques"]'::jsonb, 1, 'Theogonia signifie « naissance des dieux » ; elle date d’environ 700 av. J.-C.', 1),
    ('83aae31d-5196-5503-bb71-323145c522b7'::uuid, '11c0d2a1-156e-50dc-9293-25c2ccca1b66'::uuid, 'Chez Hésiode, que désigne d’abord Chaos ?', 'mcq', '["La béance, le vide ouvert","Le désordre et la guerre","Le dieu de la mer","Le feu primitif"]'::jsonb, 0, 'Le mot se rattache à un verbe qui signifie « bâiller » : Chaos est l’ouverture initiale.', 2),
    ('c036a007-9d3c-5a7c-bc6d-54c3d46d7dc9'::uuid, '11c0d2a1-156e-50dc-9293-25c2ccca1b66'::uuid, 'Quel Titan dévore ses propres enfants ?', 'mcq', '["Prométhée","Ouranos","Atlas","Cronos"]'::jsonb, 3, 'Cronos craint d’être détrôné ; Rhéa sauve Zeus en lui donnant une pierre à avaler.', 3),
    ('a98d9f28-d02c-5f32-9416-708ccdaee047'::uuid, '11c0d2a1-156e-50dc-9293-25c2ccca1b66'::uuid, 'Que reste-t-il au fond de la jarre de Pandore ?', 'mcq', '["La mort","La maladie","L’Espérance","Le feu"]'::jsonb, 2, 'Tous les maux s’échappent ; seule l’Espérance reste dans la jarre.', 4),
    ('869a367a-18b5-57c9-94ca-27f2a6e9d3f8'::uuid, '11c0d2a1-156e-50dc-9293-25c2ccca1b66'::uuid, 'Le mot kosmos signifie à la fois l’ordre et la parure.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'D’où « cosmos » et « cosmétique » : le monde est beau parce qu’il est ordonné.', 5),
    ('9344658e-9843-55ec-8d65-699d67e88ed7'::uuid, '11c0d2a1-156e-50dc-9293-25c2ccca1b66'::uuid, 'Qui, chez Platon, façonne le monde d’après un modèle parfait ?', 'mcq', '["Le démiurge","Éros","Atropos","Gaïa"]'::jsonb, 0, 'Dans le Timée, le démiurge, l’artisan divin, fabrique le monde.', 6),
    ('7d081955-ebb9-5d02-8bc2-bc29ab7716d7'::uuid, '11c0d2a1-156e-50dc-9293-25c2ccca1b66'::uuid, 'Quelle Moire coupe le fil de la vie ?', 'mcq', '["Clotho","Lachésis","Atropos","Anankè"]'::jsonb, 2, 'Atropos, « l’inflexible », coupe le fil que Clotho a filé.', 7),
    ('8258b84c-ba1c-5af7-a4d8-983859f4d371'::uuid, '11c0d2a1-156e-50dc-9293-25c2ccca1b66'::uuid, 'Que signifie d’abord le mot moira ?', 'mcq', '["La mort","La part, le lot","La colère","Le fil"]'::jsonb, 1, 'Le destin est la part de vie qui revient à chacun.', 8),
    ('fed66b80-c30d-5531-bb76-82e67da568cb'::uuid, '11c0d2a1-156e-50dc-9293-25c2ccca1b66'::uuid, 'Quelle est la race humaine actuelle selon Hésiode ?', 'mcq', '["La race d’or","La race des héros","La race de bronze","La race de fer"]'::jsonb, 3, 'Hésiode vit dans la race de fer, vouée au travail et à la peine.', 9),
    ('73d831a4-5fbf-5c89-9370-58698ffe3266'::uuid, '11c0d2a1-156e-50dc-9293-25c2ccca1b66'::uuid, 'Dans Χάος γένετ᾽, γένετ᾽ est un aoriste de γίγνομαι.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’aoriste raconte un événement unique : « Chaos naquit ».', 10),
    ('cbd00781-491b-51a4-96bc-599aa6f6c162'::uuid, '11c0d2a1-156e-50dc-9293-25c2ccca1b66'::uuid, 'Que vole Prométhée pour les hommes ?', 'mcq', '["Le feu","L’ambroisie","La foudre","L’écriture"]'::jsonb, 0, 'Zeus s’en venge en envoyant Pandore aux hommes.', 11),
    ('a3548b64-ce3d-5b7c-a0cc-ef690d1f0071'::uuid, '11c0d2a1-156e-50dc-9293-25c2ccca1b66'::uuid, 'Que désigne Anankè ?', 'mcq', '["L’Amour","La Nécessité","La Justice","La Nuit"]'::jsonb, 1, 'Anankè, la Nécessité, s’impose même aux dieux.', 12),
    ('32c54b99-3ec6-55ea-a651-e42e6dfe8188'::uuid, '7866145d-3138-504e-9ac6-55c241b312d9'::uuid, 'Quel dieu parle par la bouche de la Pythie ?', 'mcq', '["Zeus","Apollon","Hermès","Dionysos"]'::jsonb, 1, 'Delphes est le sanctuaire d’Apollon Pythien.', 1),
    ('69c434e8-6e30-5a3f-84d9-cad9dac65d93'::uuid, '7866145d-3138-504e-9ac6-55c241b312d9'::uuid, 'Que marquait l’omphalos de Delphes ?', 'mcq', '["Le tombeau d’un héros","Le trésor d’Athènes","Le centre, le nombril du monde","L’entrée des Enfers"]'::jsonb, 2, 'Omphalos signifie « nombril » : Delphes passait pour le centre de la Terre.', 2),
    ('7a06b893-4411-5dc9-a50d-ae90add48b74'::uuid, '7866145d-3138-504e-9ac6-55c241b312d9'::uuid, 'Que signifie Μηδὲν ἄγαν ?', 'mcq', '["Rien de trop","Rien n’est vrai","Connais-toi toi-même","Tout passe"]'::jsonb, 0, 'La maxime rappelle la mesure grecque, contraire de l’hybris.', 3),
    ('1c59001b-3276-5868-b146-881732ddec30'::uuid, '7866145d-3138-504e-9ac6-55c241b312d9'::uuid, 'Que détruit Crésus en attaquant les Perses ?', 'mcq', '["Babylone","Athènes","L’empire perse","Son propre empire"]'::jsonb, 3, 'L’oracle disait vrai : un grand empire fut détruit, celui de Crésus.', 4),
    ('e7e71ac2-4d54-50db-8862-1f88b10f0784'::uuid, '7866145d-3138-504e-9ac6-55c241b312d9'::uuid, 'Comment Thémistocle interprète-t-il le « rempart de bois » ?', 'mcq', '["Comme la flotte athénienne","Comme les murs de l’Acropole","Comme une forêt sacrée","Comme le cheval de Troie"]'::jsonb, 0, 'Il y voit les navires : la victoire de Salamine en 480 lui donne raison.', 5),
    ('82a157b7-d7df-5fe1-8ae2-cf79b6068143'::uuid, '7866145d-3138-504e-9ac6-55c241b312d9'::uuid, 'Pourquoi Socrate est-il le plus sage selon l’oracle ?', 'mcq', '["Parce qu’il sait tout","Parce qu’il sait qu’il ne sait pas","Parce qu’il est prêtre","Parce qu’il a voyagé"]'::jsonb, 1, 'Sa sagesse est de connaître les limites de son savoir.', 6),
    ('8df23126-4cc4-52df-9942-38d9ea32b7db'::uuid, '7866145d-3138-504e-9ac6-55c241b312d9'::uuid, 'Quel surnom porte Apollon, dont les oracles sont ambigus ?', 'mcq', '["Phébus","Loxias, l’Oblique","Musagète","Sauroctone"]'::jsonb, 1, 'Loxias signifie « l’Oblique » : ses réponses tournent autour de la vérité.', 7),
    ('787e977e-dbe8-5bed-b807-39675974b763'::uuid, '7866145d-3138-504e-9ac6-55c241b312d9'::uuid, 'À Dodone, on interprétait le bruissement d’un chêne sacré de Zeus.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Dodone, en Épire, est le plus ancien oracle de Zeus.', 8),
    ('f24158d1-041f-5150-b323-f5d6770b0e1b'::uuid, '7866145d-3138-504e-9ac6-55c241b312d9'::uuid, 'De quoi Cassandre est-elle punie par Apollon ?', 'mcq', '["De ne plus voir","De ne jamais être crue","De perdre la parole","De devenir folle"]'::jsonb, 1, 'Elle prédit la chute de Troie sans que personne ne la croie.', 9),
    ('e0543647-0996-52e9-a0a5-5061d769384a'::uuid, '7866145d-3138-504e-9ac6-55c241b312d9'::uuid, 'Par quelle porte passent les songes vrais selon Pénélope ?', 'mcq', '["La porte d’ivoire","La porte d’or","La porte de bronze","La porte de corne"]'::jsonb, 3, 'Dans l’Odyssée, la corne laisse passer les songes vrais, l’ivoire les trompeurs.', 10),
    ('ec0342af-6f69-520a-be60-1e1e0bd38b40'::uuid, '7866145d-3138-504e-9ac6-55c241b312d9'::uuid, 'Quel mot français vient de ὄνειρος, le rêve ?', 'mcq', '["Onéreux","Onirique","Honneur","Oracle"]'::jsonb, 1, 'Onirique qualifie ce qui relève du rêve.', 11),
    ('959fca64-96b8-5f51-b410-3880fb0485b4'::uuid, '7866145d-3138-504e-9ac6-55c241b312d9'::uuid, 'Dans Γνῶθι σεαυτόν, σεαυτόν est un pronom réfléchi.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est le réfléchi de la 2e personne à l’accusatif : « toi-même ».', 12),
    ('3ddbcb95-b7e3-52d3-a144-689ac58c5717'::uuid, 'd3b4c661-33b6-5fd2-9ce2-a2243f9e9299'::uuid, 'Qui sacrifie Iphigénie à Aulis ?', 'mcq', '["Ménélas","Agamemnon","Achille","Atrée"]'::jsonb, 1, 'Agamemnon sacrifie sa fille pour obtenir des vents favorables vers Troie.', 1),
    ('7f276f8d-1917-5101-89e5-132a018b4a7d'::uuid, 'd3b4c661-33b6-5fd2-9ce2-a2243f9e9299'::uuid, 'Quelle est la seule trilogie tragique grecque conservée ?', 'mcq', '["L’Orestie d’Eschyle","La trilogie thébaine de Sophocle","Les Troyennes d’Euripide","Les Perses"]'::jsonb, 0, 'L’Orestie (458 av. J.-C.) comprend Agamemnon, Les Choéphores et Les Euménides.', 2),
    ('f2efe424-43c5-5ef7-98ff-554c08395405'::uuid, 'd3b4c661-33b6-5fd2-9ce2-a2243f9e9299'::uuid, 'Quel tribunal acquitte Oreste dans Les Euménides ?', 'mcq', '["L’Héliée","La Boulè","L’Ecclésia","L’Aréopage"]'::jsonb, 3, 'Athéna préside l’Aréopage : la justice de la cité remplace la vengeance.', 3),
    ('97808912-fa2d-544f-a199-0409966656af'::uuid, 'd3b4c661-33b6-5fd2-9ce2-a2243f9e9299'::uuid, 'Qui Œdipe tue-t-il à un carrefour sans le savoir ?', 'mcq', '["Créon","Laïos, son père","Tirésias","Polynice"]'::jsonb, 1, 'L’oracle s’accomplit : Œdipe tue son père sans le reconnaître.', 4),
    ('bd9136bd-274f-5e21-86a6-3a34d66f5268'::uuid, 'd3b4c661-33b6-5fd2-9ce2-a2243f9e9299'::uuid, 'Pourquoi Antigone désobéit-elle à Créon ?', 'mcq', '["Pour prendre le trône","Pour sauver Œdipe","Pour enterrer son frère Polynice","Pour épouser Hémon"]'::jsonb, 2, 'Elle place la loi des dieux, qui ordonne d’ensevelir les morts, au-dessus de l’édit du roi.', 5),
    ('9d874b11-82b9-51d2-8c1e-58ce31ddc562'::uuid, 'd3b4c661-33b6-5fd2-9ce2-a2243f9e9299'::uuid, 'Que désigne l’hamartia selon Aristote ?', 'mcq', '["L’erreur qui fait tomber le héros","Le chœur","La souillure","Le décor"]'::jsonb, 0, 'Le héros tragique ne tombe pas par méchanceté, mais par une erreur.', 6),
    ('a34ce6e4-30e0-5209-a35e-74a919cc87df'::uuid, 'd3b4c661-33b6-5fd2-9ce2-a2243f9e9299'::uuid, 'Que désigne le mot miasma ?', 'mcq', '["Le retournement","La démesure","La reconnaissance","La souillure"]'::jsonb, 3, 'Le meurtre de Laïos souille Thèbes : c’est la cause de la peste au début d’Œdipe roi.', 7),
    ('8894df66-93a5-5c1d-9a96-17ba5a0c6349'::uuid, 'd3b4c661-33b6-5fd2-9ce2-a2243f9e9299'::uuid, 'Œdipe mène lui-même l’enquête qui le perd.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Plus il cherche le coupable, plus il se découvre lui-même.', 8),
    ('86a2b5c3-e769-5431-9508-75da51fa14c3'::uuid, 'd3b4c661-33b6-5fd2-9ce2-a2243f9e9299'::uuid, 'Quelle pièce de Jean Anouilh, jouée en 1944, reprend un mythe des Labdacides ?', 'mcq', '["Électre","Antigone","Les Mouches","Médée"]'::jsonb, 1, 'Sous l’Occupation, Antigone oppose le refus d’une jeune fille à la raison d’État.', 9),
    ('198dbf4c-7666-501d-a6aa-be8876dde23c'::uuid, 'd3b4c661-33b6-5fd2-9ce2-a2243f9e9299'::uuid, 'Dans Les Mouches de Sartre, qui revendique son acte au nom de la liberté ?', 'mcq', '["Agamemnon","Égisthe","Électre","Oreste"]'::jsonb, 3, 'L’Oreste de Sartre assume son meurtre : l’homme est libre face aux dieux.', 10),
    ('96088550-de60-54e7-9e2b-5319f8149966'::uuid, 'd3b4c661-33b6-5fd2-9ce2-a2243f9e9299'::uuid, 'Que désigne l’anagnorisis ?', 'mcq', '["Le chant du chœur","La reconnaissance de la vérité par le héros","Le sacrifice","L’exil"]'::jsonb, 1, 'C’est le moment où le héros découvre qui il est ou ce qu’il a fait.', 11),
    ('58f78450-396d-5194-8ae0-b4693953eed4'::uuid, 'd3b4c661-33b6-5fd2-9ce2-a2243f9e9299'::uuid, 'Atrée et Thyeste sont les fils de Laïos.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ce sont les fils de Pélops ; Laïos appartient aux Labdacides, à Thèbes.', 12),
    ('c2448694-4d2e-5212-b173-7bc1417b231c'::uuid, '56b41f6d-2042-56d2-84e5-ea98444829b1'::uuid, 'Quelle est la « seule chose vraie » que Lucien annonce dans son prologue ?', 'mcq', '["Qu’il a vu la Lune","Qu’il ment","Qu’Homère a menti","Qu’il est Syrien"]'::jsonb, 1, '« Ἓν τοῦτο ἀληθεύσω λέγων ὅτι ψεύδομαι » : la seule vérité est l’aveu du mensonge.', 1),
    ('7c170e4b-d905-57c8-a2d8-5e17384a224c'::uuid, '56b41f6d-2042-56d2-84e5-ea98444829b1'::uuid, 'De quelle ville Lucien est-il originaire ?', 'mcq', '["Athènes","Alexandrie","Samosate","Syracuse"]'::jsonb, 2, 'Samosate, sur l’Euphrate, en Syrie romaine (actuelle Turquie).', 2),
    ('5042db2e-8799-5023-bc8a-b3c69c3c8bd7'::uuid, '56b41f6d-2042-56d2-84e5-ea98444829b1'::uuid, 'À quelle époque littéraire Lucien appartient-il ?', 'mcq', '["La Seconde Sophistique","L’époque archaïque","Le siècle de Périclès","L’époque byzantine"]'::jsonb, 0, 'Au IIe siècle ap. J.-C., les orateurs grecs donnent des conférences de ville en ville.', 3),
    ('2d8714c9-e5f9-5974-99ac-c2c3a43ef94b'::uuid, '56b41f6d-2042-56d2-84e5-ea98444829b1'::uuid, 'D’où part le voyage des Histoires vraies ?', 'mcq', '["Du Pirée","De Troie","De Samosate","Des Colonnes d’Héraclès"]'::jsonb, 3, 'Le narrateur franchit Gibraltar pour explorer l’Océan inconnu.', 4),
    ('97f2f1ba-cdef-5faf-9eb7-54e4ab420c18'::uuid, '56b41f6d-2042-56d2-84e5-ea98444829b1'::uuid, 'Qui sont les rois en guerre dans l’épisode lunaire ?', 'mcq', '["Zeus et Cronos","Endymion et Phaéthon","Apollon et Artémis","Hélios et Poséidon"]'::jsonb, 1, 'Endymion, roi de la Lune, affronte Phaéthon, roi du Soleil, pour l’étoile du Matin.', 5),
    ('4f1828be-b1be-59e1-852b-06e5e5212160'::uuid, '56b41f6d-2042-56d2-84e5-ea98444829b1'::uuid, 'Où l’équipage vit-il plus d’un an et demi ?', 'mcq', '["Dans le ventre d’une baleine","Sur la Lune","Dans une grotte","Sur l’Île des Bienheureux"]'::jsonb, 0, 'Le navire est avalé par une baleine longue de 1 500 stades.', 6),
    ('dc286efc-a917-504a-a8eb-bdb4e4765a88'::uuid, '56b41f6d-2042-56d2-84e5-ea98444829b1'::uuid, 'Selon Homère rencontré sur l’Île des Bienheureux, quelle est sa vraie origine ?', 'mcq', '["Il est athénien","Il est crétois","Il est égyptien","Il est babylonien"]'::jsonb, 3, 'Homère affirme s’appeler Tigrane et être babylonien : Lucien se moque des querelles savantes.', 7),
    ('7ca292b9-70fb-577f-acbb-0048de40649e'::uuid, '56b41f6d-2042-56d2-84e5-ea98444829b1'::uuid, 'Les Histoires vraies sont une parodie des récits de voyage merveilleux.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Lucien vise Ctésias, Iambule et l’Ulysse d’Homère.', 8),
    ('0b6b6c41-546e-5dee-9439-60c20f4113ac'::uuid, '56b41f6d-2042-56d2-84e5-ea98444829b1'::uuid, 'Quel mot grec signifie « le mensonge » ?', 'mcq', '["Ἀλήθεια","Θαῦμα","Ψεῦδος","Διήγημα"]'::jsonb, 2, 'Ψεῦδος a donné pseudonyme, faux nom.', 9),
    ('2cb89f01-02aa-5d29-a671-a4700b13861f'::uuid, '56b41f6d-2042-56d2-84e5-ea98444829b1'::uuid, 'Dans quel sous-ensemble du programme l’œuvre s’inscrit-elle ?', 'mcq', '["Magie et pratiques magiques","Le grand théâtre du monde : vérité et illusion","Maîtres et disciples","Genèse et cosmogonies"]'::jsonb, 1, 'Le programme limitatif la place dans « L’homme, le monde, le destin ».', 10),
    ('b57e5a7a-6cd7-5714-a9c1-b1bfbf9f1b96'::uuid, '56b41f6d-2042-56d2-84e5-ea98444829b1'::uuid, 'Que signifie littéralement ἀλήθεια ?', 'mcq', '["Le non-oubli, ce qui n’est pas caché","La lumière","L’exactitude","La parole"]'::jsonb, 0, 'A- privatif + λήθη, l’oubli : la vérité est ce qui sort de l’ombre.', 11),
    ('948e1191-5bce-5009-a676-d3bfc1f1f05e'::uuid, '56b41f6d-2042-56d2-84e5-ea98444829b1'::uuid, 'Le récit de Lucien s’achève sur une suite réellement écrite.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il promet une suite qui n’a jamais existé : c’est un dernier mensonge.', 12),
    ('da3dc1ad-4c53-5053-a45e-d2ae0e7c336d'::uuid, 'd0edfa02-dbc1-5350-a281-2801fe000c4d'::uuid, 'Quelle œuvre moderne accompagne Lucien au programme limitatif ?', 'mcq', '["Le Petit Prince","Le Baron perché","Les Villes invisibles","Vingt mille lieues sous les mers"]'::jsonb, 1, 'Le programme 2026-2028 associe Lucien et Italo Calvino, Le Baron perché.', 1),
    ('d7c5f1d2-8010-5a64-b481-f7bad2131ed3'::uuid, 'd0edfa02-dbc1-5350-a281-2801fe000c4d'::uuid, 'Pourquoi Côme monte-t-il dans l’arbre ?', 'mcq', '["Pour fuir un incendie","Pour attraper un oiseau","Il refuse un plat d’escargots","Il est puni par son père"]'::jsonb, 2, 'Le 15 juin 1767, il refuse les escargots et jure de ne plus redescendre.', 2),
    ('6a1b8e74-c9a5-59e0-a4e2-f654513af037'::uuid, 'd0edfa02-dbc1-5350-a281-2801fe000c4d'::uuid, 'Qui raconte l’histoire de Côme ?', 'mcq', '["Côme lui-même","Viola","Napoléon","Son frère Biagio"]'::jsonb, 3, 'Biagio, resté à terre, est le narrateur.', 3),
    ('083a5ad6-cd63-548a-84a6-fa0e3309c648'::uuid, 'd0edfa02-dbc1-5350-a281-2801fe000c4d'::uuid, 'Quand Italo Calvino publie-t-il Le Baron perché ?', 'mcq', '["En 1957","En 1767","En 1923","En 1985"]'::jsonb, 0, 'Le livre paraît en 1957 ; il forme avec deux autres romans la trilogie Nos ancêtres.', 4),
    ('97385cc7-9438-5746-9926-f61ce1486dc4'::uuid, 'd0edfa02-dbc1-5350-a281-2801fe000c4d'::uuid, 'Côme redescend sur terre à la fin de sa vie.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il ne touche jamais le sol : il disparaît accroché à l’ancre d’une montgolfière.', 5),
    ('288b7036-5927-51ec-a207-ba1f48c2026a'::uuid, 'd0edfa02-dbc1-5350-a281-2801fe000c4d'::uuid, 'Que dit l’épitaphe de Côme ?', 'mcq', '["Vécut dans les arbres. Aima toujours la terre. Monta au ciel.","Ici repose un baron","Il ne descendit jamais","Il aima la liberté"]'::jsonb, 0, 'Trois phrases qui résument le paradoxe : loin de la terre, mais attaché à elle.', 6),
    ('3d5dfc02-cd5d-5297-9fdb-7e1a8130562e'::uuid, 'd0edfa02-dbc1-5350-a281-2801fe000c4d'::uuid, 'Dans Icaroménippe de Lucien, à quoi ressemblent les hommes vus d’en haut ?', 'mcq', '["À des géants","À des dieux","À des fourmis","À des oiseaux"]'::jsonb, 2, 'Vus du ciel, leurs agitations paraissent dérisoires.', 7),
    ('93c94e72-d073-5391-906a-857b4b6ef908'::uuid, 'd0edfa02-dbc1-5350-a281-2801fe000c4d'::uuid, 'Quel mouvement commun rapproche les deux œuvres ?', 'mcq', '["S’écarter pour voir juste","Fuir la guerre","Chercher un trésor","Retrouver sa famille"]'::jsonb, 0, 'La distance permet de regarder le monde autrement, sans cesser d’y prendre part.', 8),
    ('3a957aa8-4924-5385-bdc5-19121f93b765'::uuid, 'd0edfa02-dbc1-5350-a281-2801fe000c4d'::uuid, 'Quel personnage historique Côme rencontre-t-il ?', 'mcq', '["Louis XIV","César","Voltaire","Napoléon"]'::jsonb, 3, 'Calvino imagine une rencontre avec Napoléon, qui envie la liberté du baron.', 9),
    ('6e251498-9a0d-53d4-ac8c-09865269e9c8'::uuid, 'd0edfa02-dbc1-5350-a281-2801fe000c4d'::uuid, 'Côme reste engagé dans les affaires de son temps malgré sa vie dans les arbres.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il aide, combat, lit et écrit : la hauteur n’est pas une fuite.', 10),
    ('45f04997-32e9-5574-9a71-12f925f9fc64'::uuid, 'd0edfa02-dbc1-5350-a281-2801fe000c4d'::uuid, 'Dans Charon de Lucien, qui contemple les vivants depuis une montagne ?', 'mcq', '["Hermès seul","Le passeur des morts","Ménippe","Zeus"]'::jsonb, 1, 'Charon, guidé par Hermès, découvre la vanité des ambitions humaines.', 11),
    ('6ace4359-2664-503c-bd4b-cddd43e4e014'::uuid, 'd0edfa02-dbc1-5350-a281-2801fe000c4d'::uuid, 'Dans quelle région se trouve Ombrosa, le domaine de Côme ?', 'mcq', '["En Toscane","En Sicile","En Ligurie","En Vénétie"]'::jsonb, 2, 'Ombrosa est une localité imaginaire de la côte ligure.', 12),
    ('9e926e4d-6d5d-52b5-904b-b0182aad92d6'::uuid, 'd7ee7682-cc6d-5659-9666-3e7f31d2ae45'::uuid, 'En quoi Circé change-t-elle les compagnons d’Ulysse ?', 'mcq', '["En loups","En porcs","En pierres","En oiseaux"]'::jsonb, 1, 'Au chant X de l’Odyssée, Circé les transforme en porcs.', 1),
    ('1a79ed3e-1bf9-5f77-9073-3e12316c3efc'::uuid, 'd7ee7682-cc6d-5659-9666-3e7f31d2ae45'::uuid, 'Quelle herbe protège Ulysse contre Circé ?', 'mcq', '["Le moly","L’ambroisie","Le lotus","La ciguë"]'::jsonb, 0, 'Hermès donne à Ulysse le moly, qui rend le charme de Circé inefficace.', 2),
    ('3deb5c79-595d-59c2-bfb6-d2295f0a6c47'::uuid, 'd7ee7682-cc6d-5659-9666-3e7f31d2ae45'::uuid, 'Qui est l’auteur de la tragédie Médée, jouée en 431 av. J.-C. ?', 'mcq', '["Eschyle","Sophocle","Aristophane","Euripide"]'::jsonb, 3, 'Euripide y montre Médée, trahie par Jason, qui tue ses enfants.', 3),
    ('95cca5d0-be00-5f37-9518-0e607d70a23c'::uuid, 'd7ee7682-cc6d-5659-9666-3e7f31d2ae45'::uuid, 'Que fait tourner Simaitha chez Théocrite ?', 'mcq', '["Un fuseau","Un iynx, une roue magique","Une toupie de plomb","Une meule"]'::jsonb, 1, 'L’iynx doit attirer l’amant infidèle vers sa maison.', 4),
    ('d9d7496e-fd87-5320-a841-dfa385b796bb'::uuid, 'd7ee7682-cc6d-5659-9666-3e7f31d2ae45'::uuid, 'Que signifie le mot grec καταδεσμός ?', 'mcq', '["Un lien, une ligature","Une prière","Une offrande","Un chant"]'::jsonb, 0, 'La tablette de défixion « lie » la personne visée.', 5),
    ('7ef47fbc-7dba-572e-b4f7-c58a73f478e2'::uuid, 'd7ee7682-cc6d-5659-9666-3e7f31d2ae45'::uuid, 'Quelle déesse est la patronne des magiciennes ?', 'mcq', '["Artémis","Athéna","Hécate","Déméter"]'::jsonb, 2, 'Hécate règne sur les carrefours, la nuit et les spectres.', 6),
    ('ea18019f-9db2-598c-857a-50ccb02a62ab'::uuid, 'd7ee7682-cc6d-5659-9666-3e7f31d2ae45'::uuid, 'Le mot pharmakon peut désigner à la fois un remède et un poison.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est aussi le charme magique : la même puissance peut sauver ou perdre.', 7),
    ('c5c2295f-c156-53cd-9da7-7449cb5065e0'::uuid, 'd7ee7682-cc6d-5659-9666-3e7f31d2ae45'::uuid, 'À quoi Platon applique-t-il le mot pharmakon dans le Phèdre ?', 'mcq', '["À la peinture","À la musique","Au vin","À l’écriture"]'::jsonb, 3, 'L’écriture est-elle un remède pour la mémoire ou un poison qui la détruit ?', 8),
    ('eea5b353-f6ee-5d1f-933c-ccacb0cdbeae'::uuid, 'd7ee7682-cc6d-5659-9666-3e7f31d2ae45'::uuid, 'Où les papyrus magiques grecs ont-ils été trouvés ?', 'mcq', '["En Grèce","En Égypte","En Sicile","En Gaule"]'::jsonb, 1, 'Le climat sec de l’Égypte a conservé ces recueils de formules.', 9),
    ('cb264e52-b984-5094-995b-1e4cf5c64abe'::uuid, 'd7ee7682-cc6d-5659-9666-3e7f31d2ae45'::uuid, 'Que soutient le traité hippocratique De la maladie sacrée ?', 'mcq', '["Que l’épilepsie est envoyée par les dieux","Que seuls les mages peuvent la guérir","Que l’épilepsie a une cause naturelle","Que la maladie est une punition"]'::jsonb, 2, 'Elle n’est pas plus divine que les autres maladies : le médecin cherche sa cause.', 10),
    ('79603524-8d63-5121-a7f0-a534c06bda37'::uuid, 'd7ee7682-cc6d-5659-9666-3e7f31d2ae45'::uuid, 'D’où vient le mot magie ?', 'mcq', '["Du grec μάγος, prêtre perse","Du latin magnus","De l’égyptien","Du nom de Médée"]'::jsonb, 0, 'Les mages étaient les prêtres des Perses.', 11),
    ('d0a483f3-47d0-5953-a8bf-72220428a70a'::uuid, 'd7ee7682-cc6d-5659-9666-3e7f31d2ae45'::uuid, 'La magie cherche à prier les dieux sans prétendre les contraindre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est l’inverse : la magie prétend contraindre par la formule exacte.', 12),
    ('3e352641-dad7-5b78-a68b-dc15e8ddf50e'::uuid, 'fd715292-328c-5d56-b110-33fd42da1945'::uuid, 'Que cherchent les présocratiques ?', 'mcq', '["La volonté des dieux","L’archè, le principe de toutes choses","La meilleure constitution","Le salut de l’âme"]'::jsonb, 1, 'Ils cherchent un principe naturel, à la fois origine et fondement du monde.', 1),
    ('d1edfa9e-afcf-538e-9346-09c8d41da27a'::uuid, 'fd715292-328c-5d56-b110-33fd42da1945'::uuid, 'Quel est le principe selon Thalès de Milet ?', 'mcq', '["L’eau","Le feu","Le nombre","L’air"]'::jsonb, 0, 'Thalès fait de l’eau le principe de toutes choses.', 2),
    ('5f41d6b0-10aa-51ef-ac26-aff38e62acb0'::uuid, 'fd715292-328c-5d56-b110-33fd42da1945'::uuid, 'Quel philosophe affirme qu’on ne se baigne jamais deux fois dans le même fleuve ?', 'mcq', '["Parménide","Démocrite","Héraclite","Thalès"]'::jsonb, 2, 'Pour Héraclite d’Éphèse, tout s’écoule et devient.', 3),
    ('79090f41-020c-5d89-940d-96d276d82a21'::uuid, 'fd715292-328c-5d56-b110-33fd42da1945'::uuid, 'Que signifie ἄτομος ?', 'mcq', '["Minuscule","Invisible","Éternel","Insécable"]'::jsonb, 3, 'A- privatif + τέμνω, couper : ce qu’on ne peut pas diviser.', 4),
    ('7c3ee410-65e3-53fd-91ab-37e5f2c5b1b9'::uuid, 'fd715292-328c-5d56-b110-33fd42da1945'::uuid, 'Quelles sont les quatre racines d’Empédocle ?', 'mcq', '["Eau, air, terre, feu","Sang, phlegme, bile jaune, bile noire","Nombre, forme, mouvement, repos","Être, non-être, vide, plein"]'::jsonb, 0, 'Elles sont unies par l’Amour et séparées par la Haine.', 5),
    ('11f471ef-54c6-55c8-8723-7f74722b38ee'::uuid, 'fd715292-328c-5d56-b110-33fd42da1945'::uuid, 'Selon Hippocrate, la santé dépend de l’équilibre des quatre humeurs.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Sang, phlegme, bile jaune et bile noire doivent rester en équilibre.', 6),
    ('bf64da45-887a-57d8-97e2-20429befd4a7'::uuid, 'fd715292-328c-5d56-b110-33fd42da1945'::uuid, 'Quel mot français vient de « bile noire » ?', 'mcq', '["Colère","Mélancolie","Flegme","Sanguin"]'::jsonb, 1, 'Μέλαινα χολή, la bile noire, a donné mélancolie.', 7),
    ('7c24f163-3c9c-5c23-bce1-df7dcc14c57e'::uuid, 'fd715292-328c-5d56-b110-33fd42da1945'::uuid, 'Que signifie le mot historiè chez Hérodote ?', 'mcq', '["Le récit merveilleux","La chronique royale","La mémoire","L’enquête"]'::jsonb, 3, 'L’histoire commence comme une enquête sur les causes des guerres médiques.', 8),
    ('5f38985f-bb2a-5000-af38-3ef16cf035c1'::uuid, 'fd715292-328c-5d56-b110-33fd42da1945'::uuid, 'Qui a mesuré la circonférence de la Terre ?', 'mcq', '["Euclide","Archimède","Ératosthène","Thalès"]'::jsonb, 2, 'Ératosthène compare l’ombre à Syène et à Alexandrie et trouve environ 252 000 stades.', 9),
    ('5931d3f8-f133-5b0a-a607-b6ba7b4cdcc7'::uuid, 'fd715292-328c-5d56-b110-33fd42da1945'::uuid, 'Quel savant a soutenu que la Terre tourne autour du Soleil ?', 'mcq', '["Aristarque de Samos","Pythagore","Anaximène","Hippocrate"]'::jsonb, 0, 'Au IIIe siècle av. J.-C., bien avant Copernic.', 10),
    ('09eb2362-0211-53b9-9ce2-e46038c3a3f3'::uuid, 'fd715292-328c-5d56-b110-33fd42da1945'::uuid, 'Xénophane critique la façon dont Homère représente les dieux.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Si les bœufs avaient des mains, ils peindraient des dieux-bœufs : les hommes font les dieux à leur image.', 11),
    ('c59ccf24-d4e3-53b3-999b-6676ea01e8c4'::uuid, 'fd715292-328c-5d56-b110-33fd42da1945'::uuid, 'Que veut écrire Thucydide ?', 'mcq', '["Un récit plaisant pour un concours","Une acquisition pour toujours","Un éloge d’Athènes","Un recueil d’oracles"]'::jsonb, 1, 'Κτῆμα ἐς αἰεί : une œuvre utile à tous ceux qui voudront comprendre.', 12),
    ('fd59e078-d7b2-5961-8c6c-38051c9fbd9e'::uuid, 'd167e3ad-72df-54d5-aa7f-88dc17acf059'::uuid, 'Quelle école Platon fonde-t-il vers 387 av. J.-C. ?', 'mcq', '["Le Lycée","Le Jardin","L’Académie","Le Portique"]'::jsonb, 2, 'L’Académie tire son nom du jardin du héros Akadémos.', 1),
    ('a305c4f2-eee8-5784-9e2b-079ef9294107'::uuid, 'd167e3ad-72df-54d5-aa7f-88dc17acf059'::uuid, 'De qui Aristote est-il le précepteur ?', 'mcq', '["Périclès","Alexandre le Grand","Alcibiade","Philippe de Macédoine"]'::jsonb, 1, 'À partir de 343, Aristote éduque le jeune Alexandre, fils de Philippe.', 2),
    ('0646d549-e58a-58cc-b722-efc1e8da7e6e'::uuid, 'd167e3ad-72df-54d5-aa7f-88dc17acf059'::uuid, 'Pourquoi appelle-t-on les disciples d’Aristote les péripatéticiens ?', 'mcq', '["Ils discutaient en marchant","Ils voyageaient sans cesse","Ils vivaient à la campagne","Ils étaient militaires"]'::jsonb, 0, 'Le verbe περιπατεῖν signifie se promener : on discutait en marchant au Lycée.', 3),
    ('8c5fb9c3-c434-5546-9eb7-3591e948fa49'::uuid, 'd167e3ad-72df-54d5-aa7f-88dc17acf059'::uuid, 'Qu’est-ce que la maïeutique ?', 'mcq', '["L’art de convaincre les foules","L’art de la mémoire","L’art de chanter","L’art d’accoucher les esprits"]'::jsonb, 3, 'Socrate aide son interlocuteur à trouver la vérité en lui-même.', 4),
    ('853e48b0-d3c6-5054-b463-87a0691fa607'::uuid, 'd167e3ad-72df-54d5-aa7f-88dc17acf059'::uuid, 'De quoi Socrate est-il accusé en 399 ?', 'mcq', '["De trahison","De vol","D’impiété et de corruption de la jeunesse","De tyrannie"]'::jsonb, 2, 'Condamné, il boit la ciguë et refuse de s’évader.', 5),
    ('a12991ef-fbdc-5216-93ab-d1242145397f'::uuid, 'd167e3ad-72df-54d5-aa7f-88dc17acf059'::uuid, 'Socrate a laissé de nombreux écrits.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il n’a rien écrit : on le connaît par Platon et Xénophon.', 6),
    ('dab9357f-012f-5ca5-9b7f-c071a3d27690'::uuid, 'd167e3ad-72df-54d5-aa7f-88dc17acf059'::uuid, 'Quelle formule résume la pensée de Protagoras ?', 'mcq', '["L’homme est la mesure de toutes choses","Connais-toi toi-même","Tout s’écoule","Je sais que je ne sais rien"]'::jsonb, 0, 'Pour ce sophiste, la vérité est relative à celui qui juge.', 7),
    ('4d307c7e-d5e5-5c8e-a28f-363a5d354c47'::uuid, 'd167e3ad-72df-54d5-aa7f-88dc17acf059'::uuid, 'Que faisait le pédagogue dans la Grèce ancienne ?', 'mcq', '["Il enseignait la philosophie","Il conduisait l’enfant chez ses maîtres","Il dirigeait l’école","Il enseignait la gymnastique"]'::jsonb, 1, 'Παῖς + ἄγω : l’esclave qui conduit l’enfant.', 8),
    ('84cb6d0e-62ca-532e-b574-c5b73ef46921'::uuid, 'd167e3ad-72df-54d5-aa7f-88dc17acf059'::uuid, 'Que signifiait σχολή, qui a donné « école » ?', 'mcq', '["Le travail","La salle","Le loisir","La discipline"]'::jsonb, 2, 'Étudier, c’était avoir du temps libre, loin du travail nécessaire.', 9),
    ('815ff999-334b-5e46-8e79-d6f25777da7c'::uuid, 'd167e3ad-72df-54d5-aa7f-88dc17acf059'::uuid, 'Dans le Ménon, que découvre le jeune esclave interrogé par Socrate ?', 'mcq', '["La valeur de pi","Le théorème de Thalès","La distance de la Lune","Comment doubler la surface d’un carré"]'::jsonb, 3, 'Par de simples questions, il trouve qu’il faut construire le carré sur la diagonale.', 10),
    ('5c67d147-54d3-59ce-b11e-4bfad2b3896d'::uuid, 'd167e3ad-72df-54d5-aa7f-88dc17acf059'::uuid, 'Aristote a critiqué certaines idées de son maître Platon.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'On lui prête le mot : « Ami de Platon, mais plus encore ami de la vérité. »', 11),
    ('c66bd34d-5a0e-59b0-957a-aa3f5806cbcc'::uuid, 'd167e3ad-72df-54d5-aa7f-88dc17acf059'::uuid, 'Quel mot français vient de μαθητής, celui qui apprend ?', 'mcq', '["Méthode","Mathématiques","Mythe","Marathon"]'::jsonb, 1, 'Les mathématiques sont, littéralement, ce qu’on apprend.', 12),
    ('9e674eb2-5bf0-5950-8556-df702be59514'::uuid, '7ccf773b-c7e4-5177-bbd0-54c9f2bddebb'::uuid, 'Quelles divinités honore-t-on aux mystères d’Éleusis ?', 'mcq', '["Apollon et Artémis","Déméter et Perséphone","Zeus et Héra","Dionysos et Ariane"]'::jsonb, 1, 'Les mystères d’Éleusis célèbrent la mère et la fille, et le retour de la vie.', 1),
    ('aee6c364-1f78-5a88-973e-38d286b0bce7'::uuid, '7ccf773b-c7e4-5177-bbd0-54c9f2bddebb'::uuid, 'Que signifie le mot grec μύσται ?', 'mcq', '["Les initiés","Les prêtres","Les devins","Les pèlerins"]'::jsonb, 0, 'Les mystes sont les initiés aux mystères ; d’où « mystère ».', 2),
    ('237811a9-2b7f-511d-a999-b7ae5e5cdc00'::uuid, '7ccf773b-c7e4-5177-bbd0-54c9f2bddebb'::uuid, 'Quelle accusation fut portée contre Socrate ?', 'mcq', '["L’hybris","L’ostracisme","La trahison","L’asébeia, l’impiété"]'::jsonb, 3, 'L’ἀσέβεια est le manque de respect envers les dieux de la cité.', 3),
    ('f341228b-60e2-5696-aad1-7234e6b2dfde'::uuid, '7ccf773b-c7e4-5177-bbd0-54c9f2bddebb'::uuid, 'Qu’est-ce que la Septante ?', 'mcq', '["Un concile","Le Nouveau Testament","La traduction grecque de la Bible hébraïque","Un recueil d’hymnes orphiques"]'::jsonb, 2, 'Réalisée à Alexandrie, elle permet aux Juifs de langue grecque de lire l’Écriture.', 4),
    ('6ebef1a1-b403-50c9-9312-83122d202a8d'::uuid, '7ccf773b-c7e4-5177-bbd0-54c9f2bddebb'::uuid, 'Dans quelle langue le Nouveau Testament a-t-il été écrit ?', 'mcq', '["En hébreu","En latin","En araméen","En grec"]'::jsonb, 3, 'Il est écrit en koinè, le grec commun de la Méditerranée orientale.', 5),
    ('9b54aeca-b2ca-5145-bbb2-313a5cc78ea3'::uuid, '7ccf773b-c7e4-5177-bbd0-54c9f2bddebb'::uuid, 'Que signifie Ἐν ἀρχῇ ἦν ὁ λόγος ?', 'mcq', '["Au commencement était le Verbe","Au début était la lumière","Le principe est la raison","La parole est éternelle"]'::jsonb, 0, 'C’est le début de l’Évangile de Jean.', 6),
    ('aca78c10-0a04-57ce-b2ca-76d9d24e7088'::uuid, '7ccf773b-c7e4-5177-bbd0-54c9f2bddebb'::uuid, 'À quel dieu est dédié l’autel dont parle Paul à Athènes ?', 'mcq', '["À Zeus","Au dieu inconnu","À Athéna","Au dieu des Juifs"]'::jsonb, 1, 'Paul s’appuie sur l’autel « au dieu inconnu » pour annoncer son Dieu.', 7),
    ('beccf1dd-0e78-5878-9851-3db4c15676ce'::uuid, '7ccf773b-c7e4-5177-bbd0-54c9f2bddebb'::uuid, 'Le mot ἐκκλησία désignait d’abord l’assemblée des citoyens.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’Ecclésia athénienne est devenue le nom de l’Église chrétienne.', 8),
    ('a49b6db5-ef15-50da-96a0-850ea14d19de'::uuid, '7ccf773b-c7e4-5177-bbd0-54c9f2bddebb'::uuid, 'Que signifie ἄγγελος ?', 'mcq', '["Le saint","Le prophète","Le messager","L’ailé"]'::jsonb, 2, 'L’ange est d’abord un messager.', 9),
    ('100d5e66-809f-52bb-a7f4-c0a2d9d1a8f6'::uuid, '7ccf773b-c7e4-5177-bbd0-54c9f2bddebb'::uuid, 'Quel empereur tente de restaurer les cultes païens au IVe siècle ?', 'mcq', '["Constantin","Théodose","Hadrien","Julien"]'::jsonb, 3, 'Julien, dit l’Apostat, règne de 361 à 363.', 10),
    ('98d14cd9-f72c-5378-b06a-303f788b69f1'::uuid, '7ccf773b-c7e4-5177-bbd0-54c9f2bddebb'::uuid, 'Que dessinaient les premiers chrétiens pour se reconnaître ?', 'mcq', '["Une colombe","Un poisson","Un agneau","Une croix de Malte"]'::jsonb, 1, 'ἰχθύς : initiales de « Jésus-Christ, Fils de Dieu, Sauveur ».', 11),
    ('875f3f8a-2207-56d8-a3a8-9ac56e1a6582'::uuid, '7ccf773b-c7e4-5177-bbd0-54c9f2bddebb'::uuid, 'La religion grecque traditionnelle repose sur un livre sacré unique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle n’a ni livre sacré ni dogme : ce sont des rites, des fêtes et des récits.', 12),
    ('5e8ffd20-946a-5381-a834-6c9cb3748483'::uuid, '6c0efe94-7794-597d-9696-950885fa2202'::uuid, 'Que signifie ἀταραξία, but de l’épicurisme ?', 'mcq', '["L’absence de trouble","L’absence de désir","La vertu","La gloire"]'::jsonb, 0, 'L’ataraxie est la tranquillité de l’âme.', 1),
    ('3d61b834-9cbc-5a11-a7ae-50ff615b430e'::uuid, '6c0efe94-7794-597d-9696-950885fa2202'::uuid, 'D’où vient le mot cynique ?', 'mcq', '["De κύων, le chien","De Cynthie","De κινεῖν, bouger","De κενός, vide"]'::jsonb, 0, 'Diogène vivait comme un chien, sans honte ni besoins.', 2),
    ('4ebebb2d-b430-5b67-acac-24cdc4584d29'::uuid, '6c0efe94-7794-597d-9696-950885fa2202'::uuid, 'Que répond Diogène à Alexandre qui lui demande ce qu’il désire ?', 'mcq', '["Une maison","Ta sagesse","Rien","Ôte-toi de mon soleil"]'::jsonb, 3, 'Le philosophe montre qu’il n’a besoin de rien, pas même d’un roi.', 3),
    ('e278b811-cb6d-5e3a-9136-6605fca4f320'::uuid, '6c0efe94-7794-597d-9696-950885fa2202'::uuid, 'Comment s’appelle l’école d’Épicure ?', 'mcq', '["Le Portique","Le Jardin","Le Lycée","L’Académie"]'::jsonb, 1, 'Épicure y accueille amis, femmes et esclaves.', 4),
    ('c398e16f-c6d1-53da-af19-111e20d235eb'::uuid, '6c0efe94-7794-597d-9696-950885fa2202'::uuid, 'Selon le quadruple remède, la mort n’est rien pour nous.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Quand elle est là, nous ne sommes plus : il n’y a rien à craindre.', 5),
    ('aa33552d-b8d4-5c4d-968d-85b8101fc263'::uuid, '6c0efe94-7794-597d-9696-950885fa2202'::uuid, 'Quel désir est naturel et nécessaire selon Épicure ?', 'mcq', '["La gloire","La richesse","Boire quand on a soif","Les mets raffinés"]'::jsonb, 2, 'Les désirs vains, comme la gloire et la richesse, sont à fuir.', 6),
    ('5ef70bda-c8e8-540a-a0a2-895ca55a51b0'::uuid, '6c0efe94-7794-597d-9696-950885fa2202'::uuid, 'Que distingue Épictète au début du Manuel ?', 'mcq', '["Le corps et l’âme","Ce qui dépend de nous et ce qui n’en dépend pas","Les dieux et les hommes","Le plaisir et la douleur"]'::jsonb, 1, 'Le malheur vient de vouloir ce qui ne dépend pas de nous.', 7),
    ('9fe1ea4f-21a3-5871-b2fc-68348000db8d'::uuid, '6c0efe94-7794-597d-9696-950885fa2202'::uuid, 'Quelle était la condition d’Épictète avant d’enseigner ?', 'mcq', '["Roi","Soldat","Prêtre","Esclave"]'::jsonb, 3, 'Esclave affranchi, il fait de la liberté intérieure le cœur de sa sagesse.', 8),
    ('6b96c454-d138-5186-ac3f-82a7c73c2306'::uuid, '6c0efe94-7794-597d-9696-950885fa2202'::uuid, 'Dans quelle langue Marc Aurèle a-t-il écrit ses Pensées ?', 'mcq', '["En latin","En grec","En araméen","En étrusque"]'::jsonb, 1, 'L’empereur romain philosophe écrit en grec, langue de la philosophie.', 9),
    ('7366ce34-1640-5984-a893-bb766c6a1e0f'::uuid, '6c0efe94-7794-597d-9696-950885fa2202'::uuid, 'Pour Épicure, le vrai plaisir consiste à accumuler les jouissances.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est un plaisir mesuré : du pain, de l’eau, des amis, l’esprit tranquille.', 10),
    ('3fa0d580-aebd-55b6-bdb7-04f380979271'::uuid, '6c0efe94-7794-597d-9696-950885fa2202'::uuid, 'Qui a fondé le stoïcisme ?', 'mcq', '["Épictète","Diogène","Zénon de Citium","Aristote"]'::jsonb, 2, 'Zénon enseignait sous le Portique peint, la Stoa, vers 300 av. J.-C.', 11),
    ('80cbdfc4-ebc9-52fe-9f05-e60848ce82ca'::uuid, '6c0efe94-7794-597d-9696-950885fa2202'::uuid, 'Que signifie le mot philosophie ?', 'mcq', '["La science de la nature","L’amour de la sagesse","L’art de parler","La connaissance de soi"]'::jsonb, 1, 'Φιλία, l’amour, et σοφία, la sagesse.', 12),
    ('245fcda9-29fd-5b8c-bccb-944d04c3e3c5'::uuid, 'd80d6af3-8a7b-5366-9487-0488b34dd278'::uuid, 'À quoi Platon comparait-il les Grecs installés autour de la Méditerranée ?', 'mcq', '["À des fourmis","À des grenouilles autour d’une mare","À des abeilles","À des oiseaux migrateurs"]'::jsonb, 1, 'L’image dit la dispersion des cités grecques sur les rivages.', 1),
    ('9525e64d-ceb2-5d1c-b056-7191a2320ded'::uuid, 'd80d6af3-8a7b-5366-9487-0488b34dd278'::uuid, 'Quelle ville française est une colonie grecque fondée par les Phocéens ?', 'mcq', '["Lyon","Nîmes","Marseille","Bordeaux"]'::jsonb, 2, 'Massalia est fondée vers 600 av. J.-C.', 2),
    ('afe5db8f-bec1-50c3-b115-8da31d41f0fb'::uuid, 'd80d6af3-8a7b-5366-9487-0488b34dd278'::uuid, 'Qui fonde Alexandrie en 331 av. J.-C. ?', 'mcq', '["Alexandre le Grand","Ptolémée Ier","Périclès","César"]'::jsonb, 0, 'La ville porte son nom ; les Ptolémées en font la capitale du savoir.', 3),
    ('c6c651ca-3381-53e4-93bb-719cd0174055'::uuid, 'd80d6af3-8a7b-5366-9487-0488b34dd278'::uuid, 'Que signifie Mouseion, d’où vient « musée » ?', 'mcq', '["Le trésor","La salle de lecture","Le lieu des Muses","La maison du roi"]'::jsonb, 2, 'Le Mouseion d’Alexandrie accueillait des savants nourris par le roi.', 4),
    ('1efe4a20-ef94-5e2e-9dd4-afe9f0489111'::uuid, 'd80d6af3-8a7b-5366-9487-0488b34dd278'::uuid, 'Quel matériau d’écriture porte le nom de Pergame ?', 'mcq', '["Le papyrus","Le parchemin","La tablette de cire","Le papier"]'::jsonb, 1, 'Pergamena : la « peau de Pergame ».', 5),
    ('f05e2433-9f45-55b2-8f14-cbba72f4bf9b'::uuid, 'd80d6af3-8a7b-5366-9487-0488b34dd278'::uuid, 'Où se trouve aujourd’hui le grand autel de Pergame ?', 'mcq', '["À Berlin","À Athènes","À Istanbul","À Londres"]'::jsonb, 0, 'Il a été transporté et remonté dans un musée berlinois.', 6),
    ('f2b3ff72-614a-5ba1-844c-551467983b47'::uuid, 'd80d6af3-8a7b-5366-9487-0488b34dd278'::uuid, 'Quand le Parthénon est-il construit ?', 'mcq', '["Vers 700 av. J.-C.","En 331 av. J.-C.","En 146 av. J.-C.","Entre 447 et 432 av. J.-C."]'::jsonb, 3, 'Sous Périclès, avec un décor sculpté dirigé par Phidias.', 7),
    ('452d0e45-b72f-5dc9-8100-24c7009c9da3'::uuid, 'd80d6af3-8a7b-5366-9487-0488b34dd278'::uuid, 'Le Phare d’Alexandrie était l’une des Sept Merveilles du monde.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Construit sur l’île de Pharos, il a donné son nom à tous les phares.', 8),
    ('117a6b39-9874-56a7-818d-3066d7689a57'::uuid, 'd80d6af3-8a7b-5366-9487-0488b34dd278'::uuid, 'Qu’invente le Doryphore de Polyclète ?', 'mcq', '["Le drapé mouillé","Le contrapposto","La perspective","Le portrait réaliste"]'::jsonb, 1, 'Le poids sur une jambe donne au corps un équilibre vivant.', 9),
    ('daf64f4f-3362-5f56-9bb1-7943285ee102'::uuid, 'd80d6af3-8a7b-5366-9487-0488b34dd278'::uuid, 'Où sont conservées la Victoire de Samothrace et la Vénus de Milo ?', 'mcq', '["Au British Museum","Au Vatican","Au musée d’Athènes","Au Louvre"]'::jsonb, 3, 'Ces deux chefs-d’œuvre hellénistiques sont au Louvre.', 10),
    ('89b30574-5ece-5490-a945-63708e21edc0'::uuid, 'd80d6af3-8a7b-5366-9487-0488b34dd278'::uuid, 'Knossos est un palais minoen de Crète.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Arthur Evans l’a fouillé à partir de 1900.', 11),
    ('28cfc8ba-7b10-53ca-8bea-bcc0371507e4'::uuid, 'd80d6af3-8a7b-5366-9487-0488b34dd278'::uuid, 'Quel ensemble de cités grecques porte le nom de Grande-Grèce ?', 'mcq', '["Les cités d’Asie Mineure","L’Italie du Sud et la Sicile","Les îles de l’Égée","L’Égypte grecque"]'::jsonb, 1, 'Paestum, Syracuse, Agrigente en sont les grands sites.', 12),
    ('2cfb41bd-6105-5311-afc6-ec3152a0104a'::uuid, '7dc29f22-7905-5f72-98bd-1f1753850f5c'::uuid, 'Quel est le génitif de πόλις ?', 'mcq', '["Πόλου","Πόλεως","Πόλει","Πόλιν"]'::jsonb, 1, 'Πόλις, πόλεως : thème en -ι de la 3e déclinaison.', 1),
    ('99f4713f-bec1-5e50-a644-762ead7291d5'::uuid, '7dc29f22-7905-5f72-98bd-1f1753850f5c'::uuid, 'Quel est le génitif de τὸ γένος ?', 'mcq', '["Τοῦ γένου","Τοῦ γενοῦ","Τοῦ γένους","Τῆς γένης"]'::jsonb, 2, 'C’est un neutre de la 3e déclinaison, génitif γένους.', 2),
    ('75d1d72f-42d6-5188-9364-bc705369469c'::uuid, '7dc29f22-7905-5f72-98bd-1f1753850f5c'::uuid, 'Quel superlatif correspond à ἀγαθός ?', 'mcq', '["Ἄριστος","Μέγιστος","Κάκιστος","Πλεῖστος"]'::jsonb, 0, 'D’ἄριστος vient l’aristocratie, le pouvoir des meilleurs.', 3),
    ('de9e1d84-69cc-553f-b934-7ab030359798'::uuid, '7dc29f22-7905-5f72-98bd-1f1753850f5c'::uuid, 'Que signifie ὁ αὐτὸς βασιλεύς ?', 'mcq', '["Le roi lui-même","Je le vois, le roi","Son roi","Le même roi"]'::jsonb, 3, 'Entre l’article et le nom, αὐτός signifie « le même ».', 4),
    ('f165ce55-3558-59e7-a2f5-08554a6dff96'::uuid, '7dc29f22-7905-5f72-98bd-1f1753850f5c'::uuid, 'Que signifie αὐτὸς ὁ βασιλεύς ?', 'mcq', '["Le roi lui-même","Le même roi","Un autre roi","Le roi le voit"]'::jsonb, 0, 'Hors du groupe article-nom, αὐτός a le sens intensif : « lui-même ».', 5),
    ('0ac67e1f-60c8-5fb6-847c-e0c3134bf9fc'::uuid, '7dc29f22-7905-5f72-98bd-1f1753850f5c'::uuid, 'Quel suffixe signale l’aoriste passif ?', 'mcq', '["-σα-","-θη-","-ου-","-κ-"]'::jsonb, 1, 'Ἐλύθην, λυθῆναι, λυθείς : le -θη- est la marque du passif.', 6),
    ('87f9da76-7911-5f69-b812-c2136a68e679'::uuid, '7dc29f22-7905-5f72-98bd-1f1753850f5c'::uuid, 'Le subjonctif grec se reconnaît à ses voyelles longues.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Λύωμεν, λύητε : l’allongement de la voyelle signale le subjonctif.', 7),
    ('283d92c5-12d3-5845-916d-4e8f693fecda'::uuid, '7dc29f22-7905-5f72-98bd-1f1753850f5c'::uuid, 'Quelle conjonction introduit le but ?', 'mcq', '["Ὥστε","Ἐπεί","Ἵνα","Ὅτι"]'::jsonb, 2, 'Ἵνα (ou ὅπως) + subjonctif exprime le but.', 8),
    ('0d029fac-5a61-51aa-a158-27cc2c62ebfd'::uuid, '7dc29f22-7905-5f72-98bd-1f1753850f5c'::uuid, 'Ὥστε + infinitif exprime…', 'mcq', '["Une conséquence réelle","Une cause","Un but","Une conséquence possible"]'::jsonb, 3, 'Avec l’indicatif, la conséquence est réelle ; avec l’infinitif, possible.', 9),
    ('0bcaf853-e00a-5206-828d-4f0126d052bc'::uuid, '7dc29f22-7905-5f72-98bd-1f1753850f5c'::uuid, 'Quelle négation nie une volonté ou une hypothèse ?', 'mcq', '["Οὐ","Μή","Οὐδέ","Οὐκέτι"]'::jsonb, 1, 'Οὐ nie un fait ; μή s’emploie avec le subjonctif, l’impératif, l’infinitif.', 10),
    ('edc3dfe6-86c8-59ae-90b6-824b343ed99c'::uuid, '7dc29f22-7905-5f72-98bd-1f1753850f5c'::uuid, 'Νυκτός signifie « de nuit » : c’est un génitif d’époque.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le génitif situe l’action dans une période : de nuit.', 11),
    ('219fa4fb-3b1e-5c42-b3f8-dfcfd99d08f7'::uuid, '7dc29f22-7905-5f72-98bd-1f1753850f5c'::uuid, 'Qu’exprime avant tout l’aoriste, par opposition au présent ?', 'mcq', '["Le passé lointain","L’action vue comme un point","L’action répétée","Le futur proche"]'::jsonb, 1, 'C’est l’aspect : l’aoriste voit l’action globalement, le présent dans sa durée.', 12),
    ('0632ab17-3ff2-580a-85c9-ab24603e7779'::uuid, '395a13d3-603b-5013-b1af-9c1b58168882'::uuid, 'Quelle voyelle caractérise l’optatif ?', 'mcq', '["Un -η-","Un -ω- long","Un -ι-","Un -ε- bref"]'::jsonb, 2, 'Λύοιμι, λύσαιμι : le -ι- entre radical et terminaison signale l’optatif.', 1),
    ('3220356b-60ac-5d6d-82ac-f1967b2cae48'::uuid, '395a13d3-603b-5013-b1af-9c1b58168882'::uuid, 'Quelle est la 1re personne de l’optatif aoriste sigmatique de λύω ?', 'mcq', '["Λύσαιμι","Λύοιμι","Ἔλυσα","Λύσω"]'::jsonb, 0, 'Le -αι- est la marque de l’optatif aoriste sigmatique.', 2),
    ('ab335958-332d-57e0-b39e-d8e8abbe4d77'::uuid, '395a13d3-603b-5013-b1af-9c1b58168882'::uuid, 'Que marque l’optatif accompagné de ἄν ?', 'mcq', '["Le souhait","L’éventuel","Le passé","Le potentiel"]'::jsonb, 3, 'Ἡδέως ἂν ἀκούσαιμι : « j’écouterais volontiers ».', 3),
    ('635b350c-b8e0-57f3-9429-39e3574de8f9'::uuid, '395a13d3-603b-5013-b1af-9c1b58168882'::uuid, 'Que signifie ὦ παῖ, γένοιο πατρὸς εὐτυχέστερος ?', 'mcq', '["Mon enfant, tu seras plus heureux que ton père","Mon enfant, puisses-tu être plus heureux que ton père","Mon enfant, ton père était heureux","Mon enfant, sois digne de ton père"]'::jsonb, 1, 'L’optatif seul exprime le souhait : c’est Ajax chez Sophocle.', 4),
    ('88f7649e-9ddf-51f5-a8d2-10ceda5d6d36'::uuid, '395a13d3-603b-5013-b1af-9c1b58168882'::uuid, 'Quelle construction exprime l’éventuel ?', 'mcq', '["Ἄν + optatif","Εἴθε + optatif","Ἐάν + subjonctif","Εἰ + indicatif imparfait"]'::jsonb, 2, 'Ἐάν, ὅταν, ὃς ἄν + subjonctif : « si jamais », « chaque fois que », « quiconque ».', 5),
    ('88d9d0c3-124a-52f1-aae1-0693b3fc9f3f'::uuid, '395a13d3-603b-5013-b1af-9c1b58168882'::uuid, 'Ὅταν est la contraction de ὅτε + ἄν.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec le subjonctif, il signifie « lorsque, chaque fois que ».', 6),
    ('2572e15d-b2b0-5d79-be6b-f21c98fa85ae'::uuid, '395a13d3-603b-5013-b1af-9c1b58168882'::uuid, 'Quelle négation accompagne le souhait ?', 'mcq', '["Μή","Οὐ","Οὐκ","Οὐδαμῶς"]'::jsonb, 0, 'Le souhait est une volonté : on le nie par μή.', 7),
    ('077ebd26-2616-5b6b-a7c1-6f290a42a71e'::uuid, '395a13d3-603b-5013-b1af-9c1b58168882'::uuid, 'Que signifie πόδας ὠκὺς Ἀχιλλεύς ?', 'mcq', '["Achille qui court à pied","Achille aux pieds blessés","Achille rapide comme le vent","Achille aux pieds rapides"]'::jsonb, 3, 'Πόδας est un accusatif de relation : rapide quant aux pieds.', 8),
    ('2e9420ca-df0a-5afd-8911-e3b0c6c27878'::uuid, '395a13d3-603b-5013-b1af-9c1b58168882'::uuid, 'Les pronoms réfléchis grecs ont un nominatif.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils renvoient au sujet et n’existent qu’aux cas obliques.', 9),
    ('cd58d4a5-e6c2-589f-bea8-4c3c8bd4f8e0'::uuid, '395a13d3-603b-5013-b1af-9c1b58168882'::uuid, 'Quel est le pronom réfléchi de la 1re personne à l’accusatif ?', 'mcq', '["Σεαυτόν","Ἐμαυτόν","Ἑαυτόν","Αὐτόν"]'::jsonb, 1, 'Ἐμαυτόν signifie « moi-même ».', 10),
    ('75d3a84d-4cd8-5586-b794-ad42c813f229'::uuid, '395a13d3-603b-5013-b1af-9c1b58168882'::uuid, 'Quel mot français vient de ταχύς, rapide ?', 'mcq', '["Tactique","Taxe","Tachycardie","Technique"]'::jsonb, 2, 'La tachycardie est un cœur qui bat trop vite.', 11),
    ('2f592d58-dc0a-5c78-bace-0fd252d8b592'::uuid, '395a13d3-603b-5013-b1af-9c1b58168882'::uuid, 'Dans ἀλγεῖ τὴν κεφαλήν, quelle est la fonction de τὴν κεφαλήν ?', 'mcq', '["Accusatif de relation","Complément d’objet direct","Accusatif de durée","Sujet"]'::jsonb, 0, '« Il a mal quant à la tête » : il a mal à la tête.', 12),
    ('edc90663-083b-511b-a106-395585e80ef1'::uuid, '55f955e9-32f7-5471-84ac-da198fe28796'::uuid, 'Que signifie la racine grecque κράτος ?', 'mcq', '["Le peuple","Le pouvoir","La cité","Le temps"]'::jsonb, 1, 'D’où démocratie, aristocratie, bureaucratie.', 1),
    ('c26ed3d8-c540-5fc0-a15b-24ecca9bb7fc'::uuid, '55f955e9-32f7-5471-84ac-da198fe28796'::uuid, 'Que désignait d’abord le mot σχολή, qui a donné « école » ?', 'mcq', '["Le loisir","La leçon","Le maître","La salle"]'::jsonb, 0, 'Étudier, c’était profiter de son temps libre.', 2),
    ('909e2c78-eee0-5936-bb63-f5c8b15e4721'::uuid, '55f955e9-32f7-5471-84ac-da198fe28796'::uuid, 'Qu’était d’abord un ἰδιώτης ?', 'mcq', '["Un fou","Un esclave","Un étranger","Un simple particulier"]'::jsonb, 3, 'Celui qui ne se mêle pas des affaires de la cité, par opposition au citoyen actif.', 3),
    ('c7195961-b7cb-568a-8090-925bd5dd8d92'::uuid, '55f955e9-32f7-5471-84ac-da198fe28796'::uuid, 'De quels mots est formé « nostalgie » ?', 'mcq', '["Νόστος, le retour, et ἄλγος, la douleur","Νύξ, la nuit, et ἄλγος","Νόμος, la loi, et λόγος","Νέος, nouveau, et γῆ"]'::jsonb, 0, 'La nostalgie est la douleur du retour ; le mot date de 1688.', 4),
    ('31a0f3d7-6bff-59b0-877b-8f3a16d613f5'::uuid, '55f955e9-32f7-5471-84ac-da198fe28796'::uuid, 'Quel mot contient l’α privatif ?', 'mcq', '["Archéologie","Anthropologie","Athée","Astronomie"]'::jsonb, 2, 'A- privatif + θεός : sans dieu.', 5),
    ('2411f5db-1f39-503f-9912-5efc2a028531'::uuid, '55f955e9-32f7-5471-84ac-da198fe28796'::uuid, 'Que signifie le préfixe τῆλε ?', 'mcq', '["Proche","Loin","Rapide","Voir"]'::jsonb, 1, 'Téléphone : la voix de loin ; télescope : regarder loin.', 6),
    ('2ae34160-595a-55d2-ba19-48d824f37828'::uuid, '55f955e9-32f7-5471-84ac-da198fe28796'::uuid, 'Le mot « panique » vient du dieu Pan.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'On lui attribuait les terreurs soudaines qui saisissent les troupeaux et les armées.', 7),
    ('2d538100-33d2-5eb6-8e1a-e68a4a55ae53'::uuid, '55f955e9-32f7-5471-84ac-da198fe28796'::uuid, 'Que signifie étymologiquement « enthousiasme » ?', 'mcq', '["La joie","L’énergie","L’amour","Le fait d’avoir un dieu en soi"]'::jsonb, 3, 'Ἔνθεος : habité par un dieu.', 8),
    ('7da72156-7dd8-56cb-9e63-ea288b79766a'::uuid, '55f955e9-32f7-5471-84ac-da198fe28796'::uuid, 'Quel mot grec s’oppose à φύσις, la nature ?', 'mcq', '["Νόμος, la loi, la convention","Κόσμος","Λόγος","Βίος"]'::jsonb, 0, 'Les sophistes opposaient ce qui est par nature et ce qui est par convention.', 9),
    ('e2242688-b9df-5798-9b47-500d3b85b71f'::uuid, '55f955e9-32f7-5471-84ac-da198fe28796'::uuid, 'Quel est l’équivalent latin de λόγος au sens de raison ?', 'mcq', '["Natura","Ratio","Homo","Fatum"]'::jsonb, 1, 'Λόγος, la parole raisonnée, correspond à ratio.', 10),
    ('6ab94736-9ff4-5041-81e9-8f1afd051eae'::uuid, '55f955e9-32f7-5471-84ac-da198fe28796'::uuid, 'Quelle racine signifie « le souffle, l’âme » ?', 'mcq', '["Βίος","Χρόνος","Ψυχή","Δῆμος"]'::jsonb, 2, 'Ψυχή a donné psychologie et psychiatrie.', 11),
    ('e854fe4e-11c5-5e6d-9b96-2cc4c2b7a865'::uuid, '55f955e9-32f7-5471-84ac-da198fe28796'::uuid, 'Ἀνήρ et ἄνθρωπος ont exactement le même sens.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ἄνθρωπος désigne l’être humain ; ἀνήρ, l’homme mâle, souvent le héros.', 12),
    ('d97a18a6-201b-50a1-a0fd-7d1f33e74024'::uuid, 'cd7ca04d-4b6d-5e5a-98f9-fe9d636eb757'::uuid, 'Quel dictionnaire est autorisé à l’épreuve de grec ?', 'mcq', '["Aucun","Un dictionnaire grec-français","Un dictionnaire de français","Une grammaire grecque"]'::jsonb, 1, 'Seul un dictionnaire grec-français (le Bailly, en général) est autorisé.', 1),
    ('519c4624-a180-5922-bfb8-a13799c9b139'::uuid, 'cd7ca04d-4b6d-5e5a-98f9-fe9d636eb757'::uuid, 'Combien de points vaut la traduction ?', 'mcq', '["10","2","6","4"]'::jsonb, 2, 'La traduction d’environ 90 mots vaut 6 points sur 20.', 2),
    ('f7f65ed3-df39-5b2c-a8d5-94cb69c66f08'::uuid, 'cd7ca04d-4b6d-5e5a-98f9-fe9d636eb757'::uuid, 'Quelle œuvre grecque fournit le texte de l’épreuve pour 2026-2028 ?', 'mcq', '["Les Histoires vraies de Lucien","L’Odyssée","Œdipe roi","La République"]'::jsonb, 0, 'Le programme limitatif associe Lucien et Calvino.', 3),
    ('45e01559-5b3b-5351-897f-dee334423447'::uuid, 'cd7ca04d-4b6d-5e5a-98f9-fe9d636eb757'::uuid, 'Pourquoi lire l’article avant le nom ?', 'mcq', '["Parce qu’il est plus court","Parce qu’il porte l’accent","Parce qu’il est toujours au nominatif","Parce qu’il donne le cas, le genre et le nombre"]'::jsonb, 3, 'Même quand le nom est inconnu, sa forme à lui renseigne.', 4),
    ('7cc4db28-8461-5aaf-a81e-e3193c099765'::uuid, 'cd7ca04d-4b6d-5e5a-98f9-fe9d636eb757'::uuid, 'Que signifie la particule γάρ ?', 'mcq', '["Donc","Car","Mais","Et"]'::jsonb, 1, 'Γάρ introduit une explication ; οὖν une conséquence.', 5),
    ('e0cba69d-9fd2-5edf-bbbe-2fa2b27edd23'::uuid, 'cd7ca04d-4b6d-5e5a-98f9-fe9d636eb757'::uuid, 'De quel verbe εἶπον est-il l’aoriste ?', 'mcq', '["Λέγω","Ὁράω","Ἔρχομαι","Εἰμί"]'::jsonb, 0, 'Εἶπον, « je dis », sert d’aoriste à λέγω.', 6),
    ('731d8a41-a0b2-5e6d-b31e-9f76bf5a0334'::uuid, 'cd7ca04d-4b6d-5e5a-98f9-fe9d636eb757'::uuid, 'Un participe grec se traduit souvent par une subordonnée.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Selon le sens : temporelle, causale, concessive…', 7),
    ('c5ed9fa8-47ed-5283-8122-e0da6002f49a'::uuid, 'cd7ca04d-4b6d-5e5a-98f9-fe9d636eb757'::uuid, 'Comment se prononce l’esprit rude ?', 'mcq', '["Comme un s","Il ne se prononce pas","Comme un r roulé","Comme un h"]'::jsonb, 3, 'Ἡμέρα se lit « hèméra » : d’où éphémère.', 8),
    ('821b9070-adfe-5ae1-b7f4-57ae1f54143b'::uuid, 'cd7ca04d-4b6d-5e5a-98f9-fe9d636eb757'::uuid, 'Les questions de langue et de lexique peuvent porter sur le passage à traduire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La définition de l’épreuve l’exclut expressément.', 9),
    ('d0126eca-abec-59b7-b880-9b602c8f3417'::uuid, 'cd7ca04d-4b6d-5e5a-98f9-fe9d636eb757'::uuid, 'Dans l’essai, que faut-il faire dans chaque paragraphe ?', 'mcq', '["Résumer un seul texte","Confronter au moins deux textes du corpus","Citer uniquement le grec","Raconter la vie de Lucien"]'::jsonb, 1, 'La confrontation est au cœur de l’essai.', 10),
    ('dfb6d9b0-6a76-5761-9812-c1c481bc0f16'::uuid, 'cd7ca04d-4b6d-5e5a-98f9-fe9d636eb757'::uuid, 'Dans une subordonnée, qu’indique l’aoriste avant tout ?', 'mcq', '["Le futur","Le passé lointain","L’aspect","La politesse"]'::jsonb, 2, 'Hors de l’indicatif, l’aoriste marque l’aspect ponctuel, pas l’époque.', 11),
    ('080c02f5-12ef-5b7e-a37b-9b151892133d'::uuid, 'cd7ca04d-4b6d-5e5a-98f9-fe9d636eb757'::uuid, 'Combien de temps dure l’exposé à l’oral de contrôle ?', 'mcq', '["Dix minutes","Cinq minutes","Vingt minutes","Trente minutes"]'::jsonb, 0, 'Dix minutes d’exposé, puis dix minutes d’entretien, après vingt minutes de préparation.', 12),
    ('26e0907d-3691-52da-8c63-0fef30b47263'::uuid, '4216b358-d8d8-5840-8dc9-f29bbcab1c41'::uuid, 'De quel verbe latin vient le mot fatum ?', 'mcq', '["facere, faire","fari, parler","fallere, tromper","ferre, porter"]'::jsonb, 1, 'Fatum vient de fari, « parler » : le destin est ce qui a été dit une fois pour toutes.', 1),
    ('dca21391-7c12-574c-b5c0-9f0f8104c8bb'::uuid, '4216b358-d8d8-5840-8dc9-f29bbcab1c41'::uuid, 'Dans les Métamorphoses d’Ovide, comment s’appelle l’état du monde avant l’ordre ?', 'mcq', '["Le cosmos","L’Olympe","Le chaos","L’Hadès"]'::jsonb, 2, 'Ovide écrit « quem dixere chaos » : un seul visage de la nature, sans séparation des éléments.', 2),
    ('c0def0ab-b9c8-5ff6-a5cc-8a930aaea3fb'::uuid, '4216b358-d8d8-5840-8dc9-f29bbcab1c41'::uuid, 'Que sont les Parques ?', 'mcq', '["Les fileuses qui règlent la durée de chaque vie","Les prêtresses de Vesta","Les juges des Enfers","Les muses de l’histoire"]'::jsonb, 0, 'Les Parques filent, mesurent et coupent le fil de la vie, comme les Moires grecques.', 3),
    ('8cc6c78e-5da7-538d-866c-6f9b89fcced1'::uuid, '4216b358-d8d8-5840-8dc9-f29bbcab1c41'::uuid, 'Que signifie « fato profugus », au début de l’Énéide ?', 'mcq', '["Fuyant le destin","Maître de son destin","Oublié du destin","Exilé par le destin"]'::jsonb, 3, 'L’ablatif fato exprime la cause : Énée est chassé de Troie par le destin qui l’envoie fonder Rome.', 4),
    ('475669c9-61f5-5dcc-b4e7-384a1e3aceb6'::uuid, '4216b358-d8d8-5840-8dc9-f29bbcab1c41'::uuid, 'Chez Virgile, Énée est admirable parce qu’il se révolte contre le destin.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Sa vertu est la pietas : il accepte le rôle que le destin lui assigne, même au prix de Didon.', 5),
    ('a58c4ad4-6e29-5e72-9f84-f05ee08aa1d8'::uuid, '4216b358-d8d8-5840-8dc9-f29bbcab1c41'::uuid, 'Quel devin romain observe le vol des oiseaux ?', 'mcq', '["L’haruspice","La Sibylle","L’augure","Le flamine"]'::jsonb, 2, 'L’augure prend les auspices (avis + specere) ; l’haruspice, lui, lit les entrailles.', 6),
    ('0bba3b22-8553-536e-918a-63b54e655e17'::uuid, '4216b358-d8d8-5840-8dc9-f29bbcab1c41'::uuid, 'Qui guide Énée aux Enfers au chant VI de l’Énéide ?', 'mcq', '["La Sibylle de Cumes","Mercure","Didon","La Pythie"]'::jsonb, 0, 'La Sibylle de Cumes, prophétesse d’Apollon, conduit Énée chez les morts.', 7),
    ('758ca8cd-d6b2-5958-b928-e0df022ed4c7'::uuid, '4216b358-d8d8-5840-8dc9-f29bbcab1c41'::uuid, 'Dans le De rerum natura, qu’est-ce qui forme le monde ?', 'mcq', '["Un démiurge","Jupiter","Les Parques","La rencontre des atomes"]'::jsonb, 3, 'Lucrèce, épicurien, explique le monde sans intervention divine, par le mouvement des atomes.', 8),
    ('0d23472d-e85e-53d3-a7bb-bae06c2af6dc'::uuid, '4216b358-d8d8-5840-8dc9-f29bbcab1c41'::uuid, 'Que signale un prodige, pour un Romain ?', 'mcq', '["Une victoire prochaine","La rupture de la paix avec les dieux","La naissance d’un empereur","La fin d’une magistrature"]'::jsonb, 1, 'Le prodige montre que la pax deorum est rompue : il faut l’expier par des rites.', 9),
    ('a99ff5b8-34cc-56e3-bdbf-f06d3b34c9bb'::uuid, '4216b358-d8d8-5840-8dc9-f29bbcab1c41'::uuid, 'Selon la tradition reprise par Virgile, les songes vrais sortent par la porte de corne.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La porte de corne laisse passer les songes vrais, celle d’ivoire les songes trompeurs.', 10),
    ('31edbd16-7b6b-50f8-81ed-d776fd3140f8'::uuid, '4216b358-d8d8-5840-8dc9-f29bbcab1c41'::uuid, 'Que lit l’haruspice ?', 'mcq', '["Les étoiles","Les livres sibyllins","Les entrailles des victimes","Le vol des oiseaux"]'::jsonb, 2, 'L’haruspicine, d’origine étrusque, interprète le foie et les entrailles des animaux sacrifiés.', 11),
    ('d75b0ccb-8429-56f6-b6d1-6470e79a60f8'::uuid, '4216b358-d8d8-5840-8dc9-f29bbcab1c41'::uuid, 'Chez Ovide, quel être naît en dernier et lève le visage vers le ciel ?', 'mcq', '["Le cheval","L’homme","Le géant","L’aigle"]'::jsonb, 1, 'L’homme, créé en dernier, est le seul vivant qui regarde vers le ciel.', 12),
    ('1f985b59-5623-5fa6-908c-97ca650fb044'::uuid, 'cdf844b8-baa3-547e-9f0f-41f0ea20b17d'::uuid, 'Quel est le mot clé des tragédies de Sénèque ?', 'mcq', '["Pietas","Furor","Gravitas","Otium"]'::jsonb, 1, 'Le furor, passion devenue folie, pousse les héros de Sénèque au crime.', 1),
    ('e6a29aee-032b-53bf-aa9e-0378de8f44bc'::uuid, 'cdf844b8-baa3-547e-9f0f-41f0ea20b17d'::uuid, 'Dans quelle tragédie Atrée sert-il à son frère la chair de ses fils ?', 'mcq', '["Médée","Œdipe","Thyeste","Phèdre"]'::jsonb, 2, 'Thyeste met en scène la vengeance d’Atrée contre son frère, au cœur de la malédiction des Atrides.', 2),
    ('9bd0fcf6-9b24-5b48-af1a-3ad4f6cf2fb5'::uuid, 'cdf844b8-baa3-547e-9f0f-41f0ea20b17d'::uuid, 'Que signifie « Medea superest » ?', 'mcq', '["Il reste Médée","Médée est vaincue","Médée s’enfuit","Médée pleure"]'::jsonb, 0, 'Tout lui a été retiré, sauf elle-même : sa volonté suffit au crime.', 3),
    ('42e5a87a-cf72-56ea-853b-7f42ffde32b5'::uuid, 'cdf844b8-baa3-547e-9f0f-41f0ea20b17d'::uuid, 'Sénèque a été le précepteur de Néron.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Sénèque fut précepteur puis conseiller de Néron, qui lui ordonna de se donner la mort en 65.', 4),
    ('71de2f00-dfdc-51e2-9686-6de28f135ab5'::uuid, 'cdf844b8-baa3-547e-9f0f-41f0ea20b17d'::uuid, 'À quelle famille maudite appartiennent Laïos et Œdipe ?', 'mcq', '["Les Atrides","Les Pélopides","Les Scipions","Les Labdacides"]'::jsonb, 3, 'Les Labdacides descendent de Labdacos : Laïos, Œdipe, puis Étéocle, Polynice et Antigone.', 5),
    ('8ee7992d-237b-5d44-8b90-452721e7fff2'::uuid, 'cdf844b8-baa3-547e-9f0f-41f0ea20b17d'::uuid, 'Selon Sénèque, qu’est-ce qui compte dans la vie comme dans une pièce ?', 'mcq', '["Sa durée","Le nombre de spectateurs","La qualité du jeu","Le décor"]'::jsonb, 2, '« Non quam diu, sed quam bene acta sit » : non la durée, mais la façon dont elle est jouée.', 6),
    ('a841c8f6-30fb-570a-bc88-8a05b42776e1'::uuid, 'cdf844b8-baa3-547e-9f0f-41f0ea20b17d'::uuid, 'Quel auteur fait dire à un personnage « Le monde entier est un théâtre » ?', 'mcq', '["Molière","Shakespeare","Racine","Calderón"]'::jsonb, 1, 'C’est la tirade de Jacques dans Comme il vous plaira de Shakespeare, héritière du theatrum mundi antique.', 7),
    ('79f9497a-97b7-5697-8c22-7efb5d5e6f0b'::uuid, 'cdf844b8-baa3-547e-9f0f-41f0ea20b17d'::uuid, 'Que désigne le latin scelus ?', 'mcq', '["Le crime","Le destin","La scène","Le masque"]'::jsonb, 0, 'Scelus désigne le crime, souvent le crime monstrueux qui souille une famille.', 8),
    ('60040e09-740b-5753-9233-21d385cfc5d0'::uuid, 'cdf844b8-baa3-547e-9f0f-41f0ea20b17d'::uuid, 'Chez Sénèque, le crime est souvent préparé et revendiqué par le héros.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le crime y est voulu et proclamé : la passion l’emporte sur une raison que le héros aurait pu écouter.', 9),
    ('3bcdaf81-2f29-515e-aece-b738c2a0e2d2'::uuid, 'cdf844b8-baa3-547e-9f0f-41f0ea20b17d'::uuid, 'Quelle doctrine philosophique Sénèque défend-il dans ses traités ?', 'mcq', '["L’épicurisme","Le cynisme","Le scepticisme","Le stoïcisme"]'::jsonb, 3, 'Sénèque est stoïcien : la raison doit gouverner les passions, ce que ses héros tragiques ne font pas.', 10),
    ('a2d93744-bda2-51f2-bd9b-ed40627a8d5a'::uuid, 'cdf844b8-baa3-547e-9f0f-41f0ea20b17d'::uuid, 'Selon Suétone, qu’a demandé Auguste à ses amis avant de mourir ?', 'mcq', '["S’il avait bien joué la comédie de la vie","S’ils le vengeraient","Qui serait son successeur","S’il deviendrait un dieu"]'::jsonb, 0, 'Auguste reprend l’image du theatrum mundi : la vie est un rôle qu’il faut bien tenir.', 11),
    ('aea3323b-a020-589c-b07d-c811670dfe8a'::uuid, 'cdf844b8-baa3-547e-9f0f-41f0ea20b17d'::uuid, 'Quelle pièce de Corneille pratique le théâtre dans le théâtre ?', 'mcq', '["Le Cid","Horace","L’Illusion comique","Cinna"]'::jsonb, 2, 'L’Illusion comique (1636) joue sur l’illusion : le spectateur découvre qu’il regardait une pièce.', 12),
    ('dc3acb1d-146b-5436-9b89-3642fee5dec6'::uuid, 'c2330ce7-e037-5213-b45d-669cb5b8a3c4'::uuid, 'En quelle année Ovide est-il relégué ?', 'mcq', '["44 av. J.-C.","8 ap. J.-C.","27 av. J.-C.","64 ap. J.-C."]'::jsonb, 1, 'Auguste relègue Ovide en 8 après J.-C. ; le poète meurt à Tomis vers 17.', 1),
    ('918cbd79-49c6-54d8-bb23-79fff23609a5'::uuid, 'c2330ce7-e037-5213-b45d-669cb5b8a3c4'::uuid, 'Où se trouve Tomis ?', 'mcq', '["En Sicile","En Gaule","Sur la mer Noire","En Égypte"]'::jsonb, 2, 'Tomis, sur le Pont-Euxin, est l’actuelle Constanța, en Roumanie.', 2),
    ('a751f455-b23f-5432-8449-8e1ef9118b8a'::uuid, 'c2330ce7-e037-5213-b45d-669cb5b8a3c4'::uuid, 'Quelles sont, selon Ovide, les deux causes de sa perte ?', 'mcq', '["Un poème et une erreur","L’argent et l’ambition","Un complot et une trahison","L’impiété et le luxe"]'::jsonb, 0, '« Carmen et error » : l’Art d’aimer et une faute qu’il n’a jamais révélée.', 3),
    ('01da3848-67dd-5502-b675-524324cb43bd'::uuid, 'c2330ce7-e037-5213-b45d-669cb5b8a3c4'::uuid, 'Le relégué perd sa citoyenneté romaine.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La relégation laisse au condamné sa citoyenneté et ses biens ; c’est l’exil qui les lui retire.', 4),
    ('9d2a2223-2e86-5b0b-ad5b-ba787bb374ec'::uuid, 'c2330ce7-e037-5213-b45d-669cb5b8a3c4'::uuid, 'Dans quel vers sont écrits les Tristes ?', 'mcq', '["L’hexamètre seul","Le sénaire iambique","Le vers saturnien","Le distique élégiaque"]'::jsonb, 3, 'Hexamètre suivi d’un pentamètre : le distique élégiaque est le vers de la plainte.', 5),
    ('82e47468-0db6-5431-bedc-d3f004019c6c'::uuid, 'c2330ce7-e037-5213-b45d-669cb5b8a3c4'::uuid, 'Qui prend la parole dans l’élégie III, 1 ?', 'mcq', '["Le livre lui-même","Auguste","La femme d’Ovide","Le Danube"]'::jsonb, 0, 'Le livre envoyé à Rome parle et découvre que les bibliothèques publiques le refusent.', 6),
    ('dd584d94-3ed0-55ab-9ff4-0f2fc0e4baf8'::uuid, 'c2330ce7-e037-5213-b45d-669cb5b8a3c4'::uuid, 'Que signifie « ingenio perii » ?', 'mcq', '["J’ai péri par la guerre","C’est mon talent qui m’a perdu","Mon génie m’a sauvé","J’ai perdu mon talent"]'::jsonb, 1, 'Ingenio est un ablatif de cause, perii le parfait de pereo : « par mon talent j’ai péri ».', 7),
    ('7a865b5c-cb81-5f5c-9c35-0c9cbd4216fb'::uuid, 'c2330ce7-e037-5213-b45d-669cb5b8a3c4'::uuid, 'Quel fleuve gèle dans l’élégie III, 10 ?', 'mcq', '["Le Tibre","Le Nil","L’Hister, c’est-à-dire le Danube","Le Rhône"]'::jsonb, 2, 'Ovide décrit l’Hister gelé, que les barbares traversent à cheval.', 8),
    ('bcf868c1-f885-5099-9d97-6c1dff202243'::uuid, 'c2330ce7-e037-5213-b45d-669cb5b8a3c4'::uuid, 'D’après l’élégie III, 9, d’où viendrait le nom de Tomis ?', 'mcq', '["D’un roi gète","D’un tombeau d’Achille","D’une montagne","Du meurtre d’Absyrtos découpé par Médée"]'::jsonb, 3, 'Le nom est rattaché au grec temnein, « couper » : Médée y aurait découpé son frère.', 9),
    ('3e7f2ce8-dd4b-5186-84be-b6b2bb4c9697'::uuid, 'c2330ce7-e037-5213-b45d-669cb5b8a3c4'::uuid, 'Que désigne le mot ingenium ?', 'mcq', '["Le talent, le génie","L’ingénieur","La naissance","La prison"]'::jsonb, 0, 'Ingenium, le talent naturel, est à la fois la cause de l’exil et la consolation du poète.', 10),
    ('c535cff1-e2e2-54c7-86ab-93fd4d70d5fe'::uuid, 'c2330ce7-e037-5213-b45d-669cb5b8a3c4'::uuid, 'Les Tristes sont aussi un plaidoyer adressé à Auguste.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Chaque détail du froid et de la barbarie sert à obtenir un exil plus doux.', 11),
    ('e8f7ebca-9671-5177-be2a-14a8cf41a290'::uuid, 'c2330ce7-e037-5213-b45d-669cb5b8a3c4'::uuid, 'À qui est adressée l’élégie III, 7 ?', 'mcq', '["À Auguste","À Tibère","À Périlla, jeune poétesse","À Virgile"]'::jsonb, 2, 'Ovide encourage Périlla à écrire : le génie est le seul bien qu’on ne peut pas confisquer.', 12),
    ('60242f46-584e-5ad9-a87a-2ca4f9a0e024'::uuid, 'adaec0c2-b867-5dd7-bed8-099170cc2731'::uuid, 'Quelle œuvre moderne accompagne les Tristes au programme limitatif ?', 'mcq', '["Mémoires d’Hadrien","La ferme africaine","L’Étranger","Le Désert des Tartares"]'::jsonb, 1, 'Le programme 2026-2028 associe Ovide, Tristes III, et Karen Blixen, La ferme africaine.', 1),
    ('439134f7-4a56-5be6-a305-3622dca4ab2e'::uuid, 'adaec0c2-b867-5dd7-bed8-099170cc2731'::uuid, 'De quelle nationalité est Karen Blixen ?', 'mcq', '["Norvégienne","Britannique","Danoise","Suédoise"]'::jsonb, 2, 'Karen Blixen est danoise ; elle signe souvent Isak Dinesen.', 2),
    ('06ca1b1b-f175-543c-ab67-f7ecfc6717bb'::uuid, 'adaec0c2-b867-5dd7-bed8-099170cc2731'::uuid, 'Où se trouvait la ferme de Karen Blixen ?', 'mcq', '["Au pied des collines de Ngong, au Kenya","Au bord du Nil","Au Cap","Au Sénégal"]'::jsonb, 0, 'Sa plantation de café était près de Nairobi, au pied des collines de Ngong.', 3),
    ('a47801a9-4e3b-5694-a552-f203f00d1ef1'::uuid, 'adaec0c2-b867-5dd7-bed8-099170cc2731'::uuid, 'Que cultivait-on sur la ferme de Karen Blixen ?', 'mcq', '["Le thé","Le coton","La canne à sucre","Le café"]'::jsonb, 3, 'C’était une plantation de café, qui finit par faire faillite.', 4),
    ('0df7a087-ccd1-5db3-906c-0eda8edc67cc'::uuid, 'adaec0c2-b867-5dd7-bed8-099170cc2731'::uuid, 'Karen Blixen écrit La ferme africaine après son retour au Danemark.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le livre paraît en 1937, six ans après son départ du Kenya : elle écrit parce qu’elle est partie.', 5),
    ('923e6899-97fe-5cef-9123-6e64d55e64ad'::uuid, 'adaec0c2-b867-5dd7-bed8-099170cc2731'::uuid, 'Qu’est-ce qui distingue d’abord les deux départs ?', 'mcq', '["Ils ont lieu la même année","Ovide part de force, Blixen par choix","Blixen est exilée par un roi","Ovide part pour cultiver la terre"]'::jsonb, 1, 'Ovide est relégué par Auguste ; Blixen choisit de partir pour une vie nouvelle.', 6),
    ('9d20c688-fb4b-59d6-8142-129ff8afef25'::uuid, 'adaec0c2-b867-5dd7-bed8-099170cc2731'::uuid, 'Quel ami de Karen Blixen meurt en 1931 dans l’accident de son avion ?', 'mcq', '["Farah","Bror Blixen","Denys Finch Hatton","Kamante"]'::jsonb, 2, 'La mort de Denys Finch Hatton s’ajoute à la faillite de la ferme et précipite le départ.', 7),
    ('ad2d754a-6cef-59be-9b60-f94991200870'::uuid, 'adaec0c2-b867-5dd7-bed8-099170cc2731'::uuid, 'Ovide écrit les Tristes pendant son exil, au présent de la plainte.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les élégies sont envoyées de Tomis ; Blixen, elle, écrit au passé, après le retour.', 8),
    ('9785f540-2c03-595c-8230-3844f81b01eb'::uuid, 'adaec0c2-b867-5dd7-bed8-099170cc2731'::uuid, 'Pour Ovide, à qui s’adresse en dernier ressort le plaidoyer des Tristes ?', 'mcq', '["Au peuple de Tomis","À Auguste","Aux dieux des Enfers","À Virgile"]'::jsonb, 1, 'Chaque plainte vise à fléchir Auguste pour obtenir un exil plus doux.', 9),
    ('3b6f36a9-34d7-5095-9014-61840ecd5d67'::uuid, 'adaec0c2-b867-5dd7-bed8-099170cc2731'::uuid, 'Dans un essai, par quoi vaut-il mieux commencer un rapprochement ?', 'mcq', '["Par la biographie complète des auteurs","Par un jugement de goût","Par un résumé des deux livres","Par un motif commun précis"]'::jsonb, 3, 'Un motif précis (l’hiver, la maison perdue, la langue) permet de citer, comparer puis nuancer.', 10),
    ('5a0d2989-8f8f-5ca1-943a-3d05f74281b3'::uuid, 'adaec0c2-b867-5dd7-bed8-099170cc2731'::uuid, 'Que signifie le latin patria ?', 'mcq', '["La terre des pères, la patrie","Le patrimoine","Le patron","La paternité"]'::jsonb, 0, 'Patria, dérivé de pater, désigne la terre des pères : pour Ovide, Rome.', 11),
    ('4ca59e7a-d64a-5e2f-a785-447764021122'::uuid, 'adaec0c2-b867-5dd7-bed8-099170cc2731'::uuid, 'Quel genre littéraire est La ferme africaine ?', 'mcq', '["Une tragédie","Une épopée","Un récit autobiographique","Un recueil d’élégies"]'::jsonb, 2, 'C’est le récit des années kényanes de l’autrice, écrit à la première personne.', 12),
    ('d63d55c0-3b30-522f-be14-97d346e263d8'::uuid, '6cdedc3b-0601-56b1-bdcf-971e02b9ffe4'::uuid, 'Que signifie le verbe defigere, qui a donné les « défixions » ?', 'mcq', '["Clouer, fixer","Brûler","Chanter","Défaire"]'::jsonb, 0, 'La tablette « cloue » l’adversaire pour l’immobiliser ; on la perçait d’ailleurs d’un clou.', 1),
    ('8731aa30-09ef-5296-85e5-df63a7b1fa13'::uuid, '6cdedc3b-0601-56b1-bdcf-971e02b9ffe4'::uuid, 'Sur quel matériau les tablettes d’exécration sont-elles le plus souvent gravées ?', 'mcq', '["L’or","Le plomb","Le marbre","Le papyrus"]'::jsonb, 1, 'Le plomb, métal lourd et froid associé aux Enfers, était roulé puis jeté dans une tombe ou un puits.', 2),
    ('f4039b48-fcaf-54c0-9b1d-293b67bc1ecd'::uuid, '6cdedc3b-0601-56b1-bdcf-971e02b9ffe4'::uuid, 'Quel auteur a été accusé de magie et a écrit sa défense, l’Apologie ?', 'mcq', '["Cicéron","Horace","Apulée","Tacite"]'::jsonb, 2, 'Apulée fut accusé d’avoir séduit par magie la riche veuve Pudentilla.', 3),
    ('d84d0da3-d4cf-5a25-8e81-afb6518f0ee1'::uuid, '6cdedc3b-0601-56b1-bdcf-971e02b9ffe4'::uuid, 'Dans L’Âne d’or, grâce à quelle déesse Lucius redevient-il homme ?', 'mcq', '["Vénus","Diane","Hécate","Isis"]'::jsonb, 3, 'Au livre XI, Isis lui fait manger des roses : Lucius retrouve forme humaine et devient son initié.', 4),
    ('e7a21644-045c-56a0-8673-ff44cacc5f51'::uuid, '6cdedc3b-0601-56b1-bdcf-971e02b9ffe4'::uuid, 'La loi des Douze Tables punissait déjà certaines pratiques magiques.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle punissait celui qui attirait par des chants les récoltes d’autrui dans son champ.', 5),
    ('93ea0ac2-6bef-544f-93d2-ccbbad812527'::uuid, '6cdedc3b-0601-56b1-bdcf-971e02b9ffe4'::uuid, 'Quelle sorcière apparaît chez Horace ?', 'mcq', '["Érichtho","Canidia","Pamphile","Circé"]'::jsonb, 1, 'Canidia, dans les Épodes et les Satires, prépare des philtres macabres.', 6),
    ('06bba9d1-6da6-55cd-9aac-94238f3f693f'::uuid, '6cdedc3b-0601-56b1-bdcf-971e02b9ffe4'::uuid, 'Chez Lucain, que fait Érichtho ?', 'mcq', '["Elle ranime un cadavre pour qu’il prédise l’avenir","Elle change des hommes en porcs","Elle rajeunit Éson","Elle fait gagner un aurige"]'::jsonb, 0, 'Dans la Pharsale, la sorcière thessalienne interroge un mort sur l’issue de la guerre civile.', 7),
    ('928e56b6-8afe-5170-8e7f-215ea7564097'::uuid, '6cdedc3b-0601-56b1-bdcf-971e02b9ffe4'::uuid, 'Quelle région passait pour la patrie des sorcières ?', 'mcq', '["La Sicile","L’Égypte","La Gaule","La Thessalie"]'::jsonb, 3, 'On disait que les Thessaliennes savaient faire descendre la Lune du ciel.', 8),
    ('4b1eb3a0-e4dc-5a11-a2a5-90c706e18dc5'::uuid, '6cdedc3b-0601-56b1-bdcf-971e02b9ffe4'::uuid, 'Que résume la formule do ut des ?', 'mcq', '["La contrainte magique","L’échange avec les dieux : je donne pour que tu donnes","La loi du talion","La prière des morts"]'::jsonb, 1, 'La religion romaine est un contrat : on offre pour obtenir ; la magie prétend contraindre.', 9),
    ('36b75bf3-d9dd-59cb-9f83-c39d7351c59e'::uuid, '6cdedc3b-0601-56b1-bdcf-971e02b9ffe4'::uuid, 'La magie se distingue de la religion notamment par son caractère secret et privé.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La religion est publique et civique ; la magie agit dans l’ombre, souvent contre autrui.', 10),
    ('8d7175f1-fcb8-5297-a3e0-0f707738aefb'::uuid, '6cdedc3b-0601-56b1-bdcf-971e02b9ffe4'::uuid, 'D’où vient le mot magus ?', 'mcq', '["Du latin magnus, grand","De l’étrusque","Du perse, par le grec","De l’hébreu"]'::jsonb, 2, 'Les mages étaient les prêtres des Perses : la magie, c’est d’abord la religion des autres.', 11),
    ('5423b516-793c-5890-a043-9dc0d74b80ae'::uuid, '6cdedc3b-0601-56b1-bdcf-971e02b9ffe4'::uuid, 'Dans les Métamorphoses d’Ovide, qui Médée rajeunit-elle ?', 'mcq', '["Jason","Éson, le père de Jason","Pélias","Égée"]'::jsonb, 1, 'Elle remplace le sang du vieil Éson par un breuvage d’herbes magiques.', 12),
    ('2bdfbd6b-65cb-5cd6-b8b4-baffd0bcb7a4'::uuid, '2dc6a3ba-5e98-59bd-abdb-e174da44b18d'::uuid, 'Quel philosophe grec Lucrèce met-il en vers ?', 'mcq', '["Platon","Épicure","Zénon","Aristote"]'::jsonb, 1, 'Le De rerum natura expose la physique et la morale d’Épicure.', 1),
    ('eadb7c87-84ca-597c-b0c0-bc2a3e40a63c'::uuid, '2dc6a3ba-5e98-59bd-abdb-e174da44b18d'::uuid, 'Comment Lucrèce appelle-t-il la légère déviation des atomes ?', 'mcq', '["L’inane","Le fatum","Le clinamen","L’animus"]'::jsonb, 2, 'Le clinamen permet aux atomes de se rencontrer et fonde la liberté humaine.', 2),
    ('540494d1-55aa-5b1d-b333-854ec0eb1677'::uuid, '2dc6a3ba-5e98-59bd-abdb-e174da44b18d'::uuid, 'Que signifie « Tantum religio potuit suadere malorum » ?', 'mcq', '["Tant la religion a pu conseiller de crimes","La religion a vaincu tant de maux","Tant de malheurs ont suscité la religion","La religion ne peut rien contre le mal"]'::jsonb, 0, 'Lucrèce commente le sacrifice d’Iphigénie : la crainte superstitieuse mène au crime.', 3),
    ('04d8488b-3de9-580a-bc5a-3dcd7a1a89c0'::uuid, '2dc6a3ba-5e98-59bd-abdb-e174da44b18d'::uuid, 'Selon Lucrèce, les dieux interviennent sans cesse dans la vie des hommes.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils existent mais vivent heureux, loin du monde, sans s’occuper des hommes.', 4),
    ('787036e0-8cd0-5da7-80f2-f8ea1ba7331e'::uuid, '2dc6a3ba-5e98-59bd-abdb-e174da44b18d'::uuid, 'Quel est le principe « nullam rem e nihilo gigni » ?', 'mcq', '["Tout naît de l’eau","Tout vient des dieux","Rien ne meurt","Rien ne naît de rien"]'::jsonb, 3, 'Aucune chose ne naît du néant, même par la volonté divine : tout vient d’atomes préexistants.', 5),
    ('ed2c15ac-66bd-5e4d-85ad-1402c4973756'::uuid, '2dc6a3ba-5e98-59bd-abdb-e174da44b18d'::uuid, 'Quelle fonction religieuse Cicéron exerçait-il ?', 'mcq', '["Pontife","Flamine","Haruspice","Augure"]'::jsonb, 3, 'Cicéron était augure, ce qui rend d’autant plus piquante sa critique de la divination.', 6),
    ('205196af-fcfb-5042-b5a3-adeb424a3745'::uuid, '2dc6a3ba-5e98-59bd-abdb-e174da44b18d'::uuid, 'Dans quelle œuvre Cicéron discute-t-il de la valeur de la divination ?', 'mcq', '["Le De divinatione","Les Catilinaires","Le De oratore","Les Verrines"]'::jsonb, 0, 'Au livre I, Quintus la défend ; au livre II, Cicéron la réfute.', 7),
    ('43ed980d-573a-5825-83ba-b0a7baa94dfd'::uuid, '2dc6a3ba-5e98-59bd-abdb-e174da44b18d'::uuid, 'D’après Cicéron, de quoi Caton s’étonnait-il ?', 'mcq', '["Qu’un augure pût se tromper","Qu’un haruspice pût en croiser un autre sans rire","Que les dieux parlent aux oiseaux","Que le Sénat consulte les Sibylles"]'::jsonb, 1, 'Le mot de Caton suggère que les haruspices eux-mêmes ne croyaient pas à leur art.', 8),
    ('355ad15d-ad14-5773-934a-fc194f46b25c'::uuid, '2dc6a3ba-5e98-59bd-abdb-e174da44b18d'::uuid, 'Chez Cicéron, que désigne superstitio ?', 'mcq', '["Le culte des ancêtres","La piété filiale","Une crainte excessive et crédule","Le respect des lois"]'::jsonb, 2, 'La superstitio asservit l’esprit ; la religio est un culte réglé, utile à la cité.', 9),
    ('7cc5fffb-1172-511f-82fe-5e7587ff00a6'::uuid, '2dc6a3ba-5e98-59bd-abdb-e174da44b18d'::uuid, 'Pour Lucrèce, l’âme est mortelle.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Faite d’atomes, elle se disperse à la mort : il n’y a donc rien à craindre après.', 10),
    ('0ba5e875-5b7e-5ca4-9c14-f4774b7cb14e'::uuid, '2dc6a3ba-5e98-59bd-abdb-e174da44b18d'::uuid, 'Quel connecteur latin signifie « donc » ?', 'mcq', '["Igitur","Sed","Nam","Autem"]'::jsonb, 0, 'Igitur et ergo introduisent une conclusion ; nam et enim une explication.', 11),
    ('8b2dd838-9dc6-56dd-b67b-9ab160fd0593'::uuid, '2dc6a3ba-5e98-59bd-abdb-e174da44b18d'::uuid, 'À quelle école appartient Cicéron quand il suspend son jugement ?', 'mcq', '["Au Portique","Au Jardin","À la Nouvelle Académie","Au Lycée"]'::jsonb, 2, 'La Nouvelle Académie cherche le plus probable sans prétendre à la certitude.', 12),
    ('65df73fd-05c5-5439-b465-5bbf0b2cf9e7'::uuid, 'a3ab10af-c696-511e-9bcf-b1b9df37f105'::uuid, 'Quelle est la vertu romaine du devoir envers les dieux, la patrie et la famille ?', 'mcq', '["La virtus","La pietas","La clementia","La gravitas"]'::jsonb, 1, 'La pietas règle les devoirs envers les dieux, la patrie et les parents ; c’est la vertu d’Énée.', 1),
    ('e6bf4176-3d82-527c-a079-e6e937d00986'::uuid, 'a3ab10af-c696-511e-9bcf-b1b9df37f105'::uuid, 'Quels dieux protègent la maison romaine ?', 'mcq', '["Les Lares et les Pénates","Les Parques","Les Muses","Les Titans"]'::jsonb, 0, 'Les Lares et les Pénates veillent sur le foyer et les provisions de la famille.', 2),
    ('d25647ed-d4c8-55d1-b26a-263295d28c6d'::uuid, 'a3ab10af-c696-511e-9bcf-b1b9df37f105'::uuid, 'De quel pays vient le culte de Mithra ?', 'mcq', '["L’Égypte","La Phrygie","La Perse","La Grèce"]'::jsonb, 2, 'Mithra, dieu perse, est honoré dans des grottes, surtout par les soldats.', 3),
    ('18b43b6f-f667-55a9-8081-22ad346c5efc'::uuid, 'a3ab10af-c696-511e-9bcf-b1b9df37f105'::uuid, 'Quel empereur accuse les chrétiens après l’incendie de Rome en 64 ?', 'mcq', '["Trajan","Auguste","Constantin","Néron"]'::jsonb, 3, 'Tacite rapporte que Néron fit des chrétiens les boucs émissaires de l’incendie.', 4),
    ('90e0aa8e-eade-567c-bc99-049078d9d6a0'::uuid, 'a3ab10af-c696-511e-9bcf-b1b9df37f105'::uuid, 'Que demande Pline le Jeune à Trajan dans sa lettre X, 96 ?', 'mcq', '["Comment traiter les chrétiens de sa province","S’il faut construire un temple","De lever une armée","De libérer des esclaves"]'::jsonb, 0, 'Gouverneur de Bithynie, Pline ne sait pas comment procéder contre les chrétiens dénoncés.', 5),
    ('f550cd99-6708-5742-bbb8-03a79d292162'::uuid, 'a3ab10af-c696-511e-9bcf-b1b9df37f105'::uuid, 'Trajan ordonne de rechercher activement les chrétiens.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il répond qu’il ne faut pas les rechercher, mais punir ceux qui, dénoncés, refusent de sacrifier.', 6),
    ('ca4cec46-ad4e-5dde-8a54-c9f3bd22fd9e'::uuid, 'a3ab10af-c696-511e-9bcf-b1b9df37f105'::uuid, 'En quelle année l’édit de Thessalonique fait-il du christianisme la religion de l’Empire ?', 'mcq', '["313","64","410","380"]'::jsonb, 3, 'En 380, Théodose impose le christianisme ; les cultes païens sont interdits en 391-392.', 7),
    ('59b6e537-3614-5edb-a47b-dfa92338991b'::uuid, 'a3ab10af-c696-511e-9bcf-b1b9df37f105'::uuid, 'Qu’est-ce que la Vulgate ?', 'mcq', '["Un recueil de lois","La traduction latine de la Bible par Jérôme","Un poème de Virgile","Un édit de Constantin"]'::jsonb, 1, 'Jérôme traduit la Bible en latin à la fin du IVe siècle ; elle sera lue pendant plus de mille ans.', 8),
    ('f9cb8bdb-4473-555a-afd4-6d522334f2a6'::uuid, 'a3ab10af-c696-511e-9bcf-b1b9df37f105'::uuid, 'Quel événement pousse Augustin à écrire La Cité de Dieu ?', 'mcq', '["La mort de Constantin","La prise de Jérusalem","Le sac de Rome par Alaric en 410","La chute de Carthage"]'::jsonb, 2, 'Les païens accusaient les chrétiens d’avoir causé le désastre ; Augustin leur répond.', 9),
    ('8e2843e9-e3d0-5e34-a48d-4be26a2878e9'::uuid, 'a3ab10af-c696-511e-9bcf-b1b9df37f105'::uuid, 'D’où vient le mot « païen » ?', 'mcq', '["De paganus, le paysan","De pax, la paix","De pagina, la page","De Pan, le dieu"]'::jsonb, 0, 'Les campagnes restèrent longtemps fidèles aux anciens dieux : le paysan devint le païen.', 10),
    ('e1db6739-edbf-5752-8cd9-35445176294c'::uuid, 'a3ab10af-c696-511e-9bcf-b1b9df37f105'::uuid, 'Le Sénat a réprimé les Bacchanales en 186 av. J.-C.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le sénatus-consulte des Bacchanales encadre sévèrement ce culte jugé dangereux pour l’ordre.', 11),
    ('8d2033c5-8e32-56b7-9a3a-b300afa7bb95'::uuid, 'a3ab10af-c696-511e-9bcf-b1b9df37f105'::uuid, 'Quelle déesse phrygienne est introduite à Rome en 204 av. J.-C. ?', 'mcq', '["Isis","Minerve","Vesta","Cybèle, la Magna Mater"]'::jsonb, 3, 'Pendant la guerre contre Hannibal, Rome fait venir la Grande Mère de Phrygie.', 12),
    ('5679e4b6-ce81-521e-8f3c-5712815a94c3'::uuid, 'bba833f9-43b6-5e05-9ad0-5e221276286d'::uuid, 'Que signifie « Vindica te tibi » ?', 'mcq', '["Venge-toi","Reprends possession de toi-même","Connais-toi toi-même","Donne-toi aux autres"]'::jsonb, 1, 'Sénèque invite Lucilius à se revendiquer, c’est-à-dire à reprendre possession de son temps.', 1),
    ('1ea55792-6171-5522-b245-422df8389b33'::uuid, 'bba833f9-43b6-5e05-9ad0-5e221276286d'::uuid, 'Selon Sénèque, quelle est la seule chose qui nous appartient vraiment ?', 'mcq', '["Le temps","La fortune","Le corps","La gloire"]'::jsonb, 0, '« Tempus tantum nostrum est » : seul le temps est à nous.', 2),
    ('8d98647a-3f48-50d5-8c93-458e58d9cdec'::uuid, 'bba833f9-43b6-5e05-9ad0-5e221276286d'::uuid, 'À qui Sénèque adresse-t-il ses 124 lettres ?', 'mcq', '["À Néron","À Lucilius","À Atticus","À Mécène"]'::jsonb, 1, 'Les Lettres à Lucilius guident un ami sur le chemin de la sagesse stoïcienne.', 3),
    ('6fade0f5-022d-5304-b316-430f50c8ae3d'::uuid, 'bba833f9-43b6-5e05-9ad0-5e221276286d'::uuid, 'Pour les épicuriens, le bonheur réside dans l’absence de trouble.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est l’ataraxie : le plaisir épicurien est avant tout tranquillité de l’âme.', 4),
    ('929b99d6-eb9c-56da-b1cd-ef9bba8a9d60'::uuid, 'bba833f9-43b6-5e05-9ad0-5e221276286d'::uuid, 'Que signifie carpere dans « carpe diem » ?', 'mcq', '["Profiter sans limite","Oublier","Cueillir","Compter"]'::jsonb, 2, 'Carpere, c’est cueillir un fruit mûr : goûter le présent, non s’étourdir.', 5),
    ('8e96ab50-ee77-5a47-8240-3afc6d37502b'::uuid, 'bba833f9-43b6-5e05-9ad0-5e221276286d'::uuid, 'Que désigne l’aurea mediocritas d’Horace ?', 'mcq', '["La médiocrité","La richesse","La pauvreté volontaire","Le juste milieu"]'::jsonb, 3, 'Le « juste milieu d’or » évite à la fois la misère et l’excès du luxe.', 6),
    ('2b4d117e-46b4-5a2b-beab-10c52232e0e1'::uuid, 'bba833f9-43b6-5e05-9ad0-5e221276286d'::uuid, 'Qui a fondé le stoïcisme ?', 'mcq', '["Épicure","Diogène","Zénon de Citium","Pythagore"]'::jsonb, 2, 'Zénon de Citium enseignait sous le Portique peint (stoa) d’Athènes, vers 300 av. J.-C.', 7),
    ('8c3b0f22-bd68-55e7-9679-128ec062f674'::uuid, 'bba833f9-43b6-5e05-9ad0-5e221276286d'::uuid, 'Comment Sénèque meurt-il ?', 'mcq', '["Au combat","Sur ordre de Néron, en s’ouvrant les veines","Empoisonné par Agrippine","De vieillesse en exil"]'::jsonb, 1, 'Accusé d’avoir participé à la conjuration de Pison, il reçoit l’ordre de mourir en 65.', 8),
    ('2ed88349-a662-574e-bd6d-548b000dcc30'::uuid, 'bba833f9-43b6-5e05-9ad0-5e221276286d'::uuid, 'Que veut dire « Non omnis moriar » ?', 'mcq', '["Je ne mourrai pas tout entier","Nul n’échappe à la mort","Je ne veux pas mourir","Tous mourront"]'::jsonb, 0, 'Horace compte survivre par son œuvre, « monument plus durable que l’airain ».', 9),
    ('09618681-485a-541e-81b6-a6b98b36de62'::uuid, 'bba833f9-43b6-5e05-9ad0-5e221276286d'::uuid, 'Les stoïciens conseillent de vivre caché, loin de la cité.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est la règle épicurienne ; les stoïciens appellent au contraire à servir la cité.', 10),
    ('551c8bd1-af79-508c-8f78-4c3340bfef6f'::uuid, 'bba833f9-43b6-5e05-9ad0-5e221276286d'::uuid, 'Dans « carpe diem », à quel cas est diem ?', 'mcq', '["Nominatif","Datif","Ablatif","Accusatif"]'::jsonb, 3, 'Diem est l’accusatif de dies, complément d’objet de carpe.', 11),
    ('e8c6f55d-3cfc-51af-80d8-de720ac66d05'::uuid, 'bba833f9-43b6-5e05-9ad0-5e221276286d'::uuid, 'Selon Sénèque, dans De la brièveté de la vie, quel est notre vrai problème ?', 'mcq', '["Nous avons trop peu de temps","Nous perdons beaucoup de temps","Les dieux nous volent le temps","Le temps n’existe pas"]'::jsonb, 1, 'Nous n’avons pas peu de temps, nous en perdons beaucoup : la vie est longue si l’on sait l’employer.', 12),
    ('9836b61e-2732-5033-b8df-0827151b15af'::uuid, '2e3e9adc-ced0-5826-aa89-a5686635474d'::uuid, 'Combien de livres compte l’Histoire naturelle de Pline l’Ancien ?', 'mcq', '["12","37","6","142"]'::jsonb, 1, 'Pline couvre en 37 livres tout le savoir de son temps, du ciel aux pierres précieuses.', 1),
    ('4f6d21d5-42a8-5b4e-92d6-1631e1d7aa48'::uuid, '2e3e9adc-ced0-5826-aa89-a5686635474d'::uuid, 'À quel futur empereur l’Histoire naturelle est-elle dédiée ?', 'mcq', '["Titus","Néron","Hadrien","Auguste"]'::jsonb, 0, 'Pline dédie son œuvre à Titus, fils de Vespasien.', 2),
    ('701b2dc4-8a3d-54f5-832b-e0633d7c11af'::uuid, '2e3e9adc-ced0-5826-aa89-a5686635474d'::uuid, 'Qui raconte la mort de Pline l’Ancien ?', 'mcq', '["Tacite","Suétone","Pline le Jeune, son neveu","Sénèque"]'::jsonb, 2, 'Pline le Jeune écrit deux lettres à Tacite sur l’éruption et la mort de son oncle.', 3),
    ('72ce5fd4-e1b6-5ea9-9420-cf67dda1099b'::uuid, '2e3e9adc-ced0-5826-aa89-a5686635474d'::uuid, 'À quoi Pline le Jeune compare-t-il le nuage du Vésuve ?', 'mcq', '["À une tour","À un champignon","À une vague","À un pin parasol"]'::jsonb, 3, 'Un tronc très haut, puis des branches : c’est l’image du pin parasol.', 4),
    ('59934509-8e2b-5c2d-90b3-e756473e281d'::uuid, '2e3e9adc-ced0-5826-aa89-a5686635474d'::uuid, 'En quelle année le Vésuve ensevelit-il Pompéi ?', 'mcq', '["79","64","44","410"]'::jsonb, 0, 'L’éruption de 79 ensevelit Pompéi, Herculanum et Stabies.', 5),
    ('8d175cb0-e0f3-5c54-9516-57a7daf7f3aa'::uuid, '2e3e9adc-ced0-5826-aa89-a5686635474d'::uuid, 'Pline l’Ancien meurt en tentant de secourir des habitants et d’observer l’éruption.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Commandant de la flotte de Misène, il se porte au secours des habitants et meurt à Stabies.', 6),
    ('c42db7a3-505b-588b-9de4-f62bbb01deac'::uuid, '2e3e9adc-ced0-5826-aa89-a5686635474d'::uuid, 'Qu’appelle-t-on une éruption plinienne ?', 'mcq', '["Une coulée de lave lente","Une éruption à colonne verticale géante","Un séisme sous-marin","Une éruption sans cendres"]'::jsonb, 1, 'Le nom de Pline est resté à ce type d’éruption explosive décrit par son neveu.', 7),
    ('a3a5559a-6908-52a8-a089-d559a9d1ace4'::uuid, '2e3e9adc-ced0-5826-aa89-a5686635474d'::uuid, 'Quelle œuvre de Sénèque cherche les causes des séismes et des comètes ?', 'mcq', '["Les Lettres à Lucilius","La Médée","Les Questions naturelles","De la colère"]'::jsonb, 2, 'Pour Sénèque, connaître les causes délivre l’âme de la peur.', 8),
    ('43087181-a8cb-5f67-8a52-6cf1e2aa9f69'::uuid, '2e3e9adc-ced0-5826-aa89-a5686635474d'::uuid, 'Galien, médecin de Rome, écrivait en latin.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Galien, né à Pergame, écrivait en grec : la médecine savante de Rome restait grecque.', 9),
    ('b0fb0a44-7418-5c77-8718-cd0ec923fa2e'::uuid, '2e3e9adc-ced0-5826-aa89-a5686635474d'::uuid, 'De quel verbe vient natura ?', 'mcq', '["Nare, nager","Nasci, naître","Narrare, raconter","Nectere, lier"]'::jsonb, 1, 'La nature, c’est ce qui fait naître et croître.', 10),
    ('2bf54f8c-6539-5a49-afa9-cee463174c0b'::uuid, '2e3e9adc-ced0-5826-aa89-a5686635474d'::uuid, 'Que désigne l’expression orbis terrarum ?', 'mcq', '["Le monde habité, le cercle des terres","L’orbite de la Lune","Le ciel étoilé","Les Enfers"]'::jsonb, 0, 'L’orbis terrarum est l’ensemble des terres connues, disposées en cercle autour de la Méditerranée.', 11),
    ('08049df4-5c46-5ce4-b0e2-10a38de6c936'::uuid, '2e3e9adc-ced0-5826-aa89-a5686635474d'::uuid, 'Qui a rédigé en latin un traité De medicina au Ier siècle ?', 'mcq', '["Galien","Hippocrate","Vitruve","Celse"]'::jsonb, 3, 'Celse est l’auteur du grand traité latin de médecine, remarquable par sa clarté.', 12),
    ('5549d438-1bd4-5e37-88de-6683e95e3abb'::uuid, 'ebd9ba77-a6b6-5399-85dd-6702f4cd88ac'::uuid, 'Quelles sont les trois exigences de l’architecture selon Vitruve ?', 'mcq', '["Firmitas, utilitas, venustas","Pietas, virtus, fides","Ordo, forma, color","Aqua, terra, ignis"]'::jsonb, 0, 'Solidité, utilité, beauté : la triade vitruvienne reste une référence des architectes.', 1),
    ('e2e591c9-6972-54c0-8789-76f7f8207d56'::uuid, 'ebd9ba77-a6b6-5399-85dd-6702f4cd88ac'::uuid, 'Quel artiste de la Renaissance a dessiné l’Homme de Vitruve ?', 'mcq', '["Michel-Ange","Raphaël","Botticelli","Léonard de Vinci"]'::jsonb, 3, 'Léonard inscrit le corps humain dans un cercle et un carré, d’après les proportions de Vitruve.', 2),
    ('c902971a-f846-50ad-baf1-d6858bb7fd3d'::uuid, 'ebd9ba77-a6b6-5399-85dd-6702f4cd88ac'::uuid, 'Que porte le pont du Gard ?', 'mcq', '["Une route impériale","L’aqueduc de Nîmes","Un temple","Un rempart"]'::jsonb, 1, 'Construit au Ier siècle, il fait franchir le Gardon à l’aqueduc qui alimentait Nîmes.', 3),
    ('045f51d7-02b3-580b-a131-1efcc3e9cb45'::uuid, 'ebd9ba77-a6b6-5399-85dd-6702f4cd88ac'::uuid, 'Le béton romain pouvait durcir même sous l’eau.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Grâce à la cendre volcanique, l’opus caementicium prenait même dans l’eau.', 4),
    ('ff21b1e7-1864-53b8-b5c3-e946c246173c'::uuid, 'ebd9ba77-a6b6-5399-85dd-6702f4cd88ac'::uuid, 'Quel monument romain possède une coupole de plus de 43 mètres percée d’un oculus ?', 'mcq', '["Le Colisée","La Maison carrée","Le Panthéon","Le Circus Maximus"]'::jsonb, 2, 'La coupole du Panthéon, reconstruit sous Hadrien, reste la plus grande en béton non armé.', 5),
    ('503535d3-62a8-529c-a6ba-a52614d00d10'::uuid, 'ebd9ba77-a6b6-5399-85dd-6702f4cd88ac'::uuid, 'Quel conseil Dédale donne-t-il à Icare ?', 'mcq', '["Voler le plus haut possible","Se tenir dans la voie du milieu","Suivre les oiseaux","Ne jamais regarder la mer"]'::jsonb, 1, '« Medio ut limite curras » : ni trop près du soleil, ni trop près de la mer.', 6),
    ('57d6f4f3-4563-5cb5-86f3-43a344fc28af'::uuid, 'ebd9ba77-a6b6-5399-85dd-6702f4cd88ac'::uuid, 'Quelle déesse rend vivante la statue de Pygmalion ?', 'mcq', '["Minerve","Junon","Diane","Vénus"]'::jsonb, 3, 'Touchée par la prière du sculpteur, Vénus anime la statue d’ivoire.', 7),
    ('6fd5edbe-ae26-536c-8a0c-59f49312d092'::uuid, 'ebd9ba77-a6b6-5399-85dd-6702f4cd88ac'::uuid, 'Que signifie « ars adeo latet arte sua » ?', 'mcq', '["L’art est inutile","Tant l’art se cache par son art même","L’art est un mensonge","L’artiste se cache"]'::jsonb, 1, 'La perfection de la statue fait oublier qu’elle est fabriquée.', 8),
    ('5f87a642-9d4f-5d2f-bac8-4a27fd5d9a33'::uuid, 'ebd9ba77-a6b6-5399-85dd-6702f4cd88ac'::uuid, 'Qui a écrit un traité sur l’alimentation en eau de Rome ?', 'mcq', '["Frontin","Vitruve","Pline l’Ancien","Caton"]'::jsonb, 0, 'Frontin, curator aquarum à la fin du Ier siècle, décrit les aqueducs de la ville.', 9),
    ('15ab1fcd-46aa-5514-b54e-9cfdb973ae8b'::uuid, 'ebd9ba77-a6b6-5399-85dd-6702f4cd88ac'::uuid, 'Le De architectura de Vitruve est le seul traité d’architecture antique conservé.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est pourquoi il a tant compté pour les architectes de la Renaissance.', 10),
    ('aa2c4601-7328-55a9-acf2-f627eee8527a'::uuid, 'ebd9ba77-a6b6-5399-85dd-6702f4cd88ac'::uuid, 'Quelle voie, commencée en 312 av. J.-C., relie Rome au sud de l’Italie ?', 'mcq', '["La via Domitia","La via Aurelia","La via Appia","La via Egnatia"]'::jsonb, 2, 'La via Appia, « reine des routes », porte le nom du censeur Appius Claudius.', 11),
    ('e4d49688-838d-5db1-a7bd-3e59ea198159'::uuid, 'ebd9ba77-a6b6-5399-85dd-6702f4cd88ac'::uuid, 'Quel mot français ne vient PAS du latin ars ?', 'mcq', '["Artisan","Artifice","Artiste","Technique"]'::jsonb, 3, 'Technique vient du grec technè ; art, artisan, artifice et artiste viennent de ars.', 12),
    ('90edf0ca-ec41-53fe-9170-6001bdf5e41b'::uuid, 'bec89ced-fea1-559a-a870-f98bbd03b8cd'::uuid, 'Que signifie mare nostrum ?', 'mcq', '["La mer des morts","Notre mer","La mer du milieu","La mer intérieure"]'::jsonb, 1, 'Les Romains appellent ainsi la Méditerranée, dont ils contrôlent tous les rivages.', 1),
    ('f1ed1d7f-7c37-5209-beed-3508f565bf8b'::uuid, 'bec89ced-fea1-559a-a870-f98bbd03b8cd'::uuid, 'En quelle année Carthage est-elle détruite par Rome ?', 'mcq', '["146 av. J.-C.","79 ap. J.-C.","44 av. J.-C.","212 av. J.-C."]'::jsonb, 0, 'À la fin de la troisième guerre punique, Carthage est rasée, puis refondée plus tard en colonie romaine.', 2),
    ('b86b8af0-833b-53c0-8ecf-474eea6b8008'::uuid, 'bec89ced-fea1-559a-a870-f98bbd03b8cd'::uuid, 'Dans quel pays actuel se trouve Leptis Magna ?', 'mcq', '["La Tunisie","L’Égypte","La Libye","Le Maroc"]'::jsonb, 2, 'Leptis Magna, en Libye, est la ville natale de Septime Sévère.', 3),
    ('e3298d38-e467-5f7c-9018-dfb1dd7d9cd3'::uuid, 'bec89ced-fea1-559a-a870-f98bbd03b8cd'::uuid, 'Comment s’appelle la rue principale nord-sud d’une ville romaine ?', 'mcq', '["Le decumanus","La via","Le forum","Le cardo"]'::jsonb, 3, 'Le cardo croise le decumanus (est-ouest) ; le forum s’installe à leur croisement.', 4),
    ('79d0143c-9bc7-5e27-b2e3-30fc3da592b0'::uuid, 'bec89ced-fea1-559a-a870-f98bbd03b8cd'::uuid, 'Timgad, en Algérie, a été fondée sous Trajan avec un plan en damier.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Fondée vers 100, Timgad est un exemple parfait d’urbanisme romain régulier.', 5),
    ('549b59b0-ffb5-5c6b-8394-b1a3bb102c9a'::uuid, 'bec89ced-fea1-559a-a870-f98bbd03b8cd'::uuid, 'Quel monument célèbre se trouve à Éphèse ?', 'mcq', '["La bibliothèque de Celsus","La Maison carrée","Le pont du Gard","La colonne Trajane"]'::jsonb, 0, 'Sa façade du IIe siècle a été relevée par les archéologues.', 6),
    ('e589cd4d-1c25-59a4-a116-9d9ad2e168e5'::uuid, 'bec89ced-fea1-559a-a870-f98bbd03b8cd'::uuid, 'Qui ouvre la première bibliothèque publique de Rome ?', 'mcq', '["Auguste","Asinius Pollion","Trajan","Cicéron"]'::jsonb, 1, 'Asinius Pollion ouvre la première bibliothèque publique de Rome en 39 av. J.-C.', 7),
    ('41e5a016-9a58-5a0b-9cba-3715b7976c1f'::uuid, 'bec89ced-fea1-559a-a870-f98bbd03b8cd'::uuid, 'Qu’a livré la villa des Papyrus d’Herculanum ?', 'mcq', '["Des statues d’or","Des fresques érotiques","Des rouleaux carbonisés, surtout de philosophie épicurienne","Des tablettes de défixion"]'::jsonb, 2, 'L’éruption de 79 a carbonisé la bibliothèque ; l’imagerie numérique commence à la faire lire.', 8),
    ('69e61ab0-dff8-5f51-a29e-25df91a7964e'::uuid, 'bec89ced-fea1-559a-a870-f98bbd03b8cd'::uuid, 'Chez qui l’élève romain apprend-il l’art de parler ?', 'mcq', '["Le litterator","Le grammaticus","Le paedagogus","Le rhetor"]'::jsonb, 3, 'Le rhéteur enseigne l’éloquence, dernière étape des études.', 9),
    ('8c4fb6b7-6f69-5ec9-84dc-cead745beaf7'::uuid, 'bec89ced-fea1-559a-a870-f98bbd03b8cd'::uuid, 'Que dit la formule « Graecia capta ferum victorem cepit » ?', 'mcq', '["La Grèce a vaincu Rome par les armes","Rome a détruit la culture grecque","La Grèce conquise a conquis son vainqueur","La Grèce a été libérée par Rome"]'::jsonb, 2, 'Horace reconnaît que Rome, victorieuse, a été conquise par la culture grecque.', 10),
    ('339ea7ec-ed57-5a90-9383-4fbd523c3db7'::uuid, 'bec89ced-fea1-559a-a870-f98bbd03b8cd'::uuid, 'La colonne Vendôme s’inspire de la colonne Trajane.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle reprend son fût à décor spiralé qui raconte des campagnes militaires.', 11),
    ('72c7a501-536c-5884-a125-36b9c7f9a5fa'::uuid, 'bec89ced-fea1-559a-a870-f98bbd03b8cd'::uuid, 'Où se trouvent des monuments antiques dynamités par l’État islamique en 2015 ?', 'mcq', '["À Pompéi","À Palmyre","À Carthage","À Nîmes"]'::jsonb, 1, 'À Palmyre, en Syrie, la destruction visait à effacer une mémoire commune.', 12),
    ('02cfc455-99bd-554a-a28c-dcfeeee3bcb3'::uuid, '64eca411-9f9d-528e-a7d1-5c74899d1e49'::uuid, 'Quel est le parfait de fero ?', 'mcq', '["Feri","Ferui","Tuli","Latus sum"]'::jsonb, 2, 'Fero, ferre, tuli, latum : trois radicaux différents, à apprendre par cœur.', 1),
    ('ebc5473b-43a9-5d65-8b1b-2e8ed1649a81'::uuid, '64eca411-9f9d-528e-a7d1-5c74899d1e49'::uuid, 'Que signifie « Noli me tangere » ?', 'mcq', '["Tu ne peux pas me toucher","Ne me touche pas","Je ne veux pas te toucher","Touche-moi"]'::jsonb, 1, 'Noli + infinitif exprime la défense : « ne… pas ».', 2),
    ('39995cf8-42c3-5c8b-b54b-af4226e33c2f'::uuid, '64eca411-9f9d-528e-a7d1-5c74899d1e49'::uuid, 'Quel verbe sert de passif à facio ?', 'mcq', '["Fio","Fero","Eo","Volo"]'::jsonb, 0, 'Fio, fieri, factus sum : « devenir, être fait ».', 3),
    ('2fc7b87f-7aad-57a1-bcfd-29c7305d435e'::uuid, '64eca411-9f9d-528e-a7d1-5c74899d1e49'::uuid, 'Que signifie « ausus est » ?', 'mcq', '["Il a été osé","Il osera","Il ose","Il a osé"]'::jsonb, 3, 'Audeo est semi-déponent : forme passive au parfait, sens actif.', 4),
    ('9ea12762-5f77-51f9-8414-82938a45c81e'::uuid, '64eca411-9f9d-528e-a7d1-5c74899d1e49'::uuid, 'Que signifie « me pudet stultitiae meae » ?', 'mcq', '["Ma sottise me plaît","J’ai honte de ma sottise","Il convient d’être sot","Je me repens de ma sagesse"]'::jsonb, 1, 'Pudet : accusatif de la personne (me), génitif de la cause (stultitiae).', 5),
    ('755edb00-c281-5221-bb56-8e9e5074a31c'::uuid, '64eca411-9f9d-528e-a7d1-5c74899d1e49'::uuid, 'Avec licet, la personne est au datif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Licet mihi ire : « il m’est permis d’aller ».', 6),
    ('41bf702f-8373-563b-8e9d-54601dff1cc8'::uuid, '64eca411-9f9d-528e-a7d1-5c74899d1e49'::uuid, 'Dans « eo cubitum », qu’exprime le supin ?', 'mcq', '["La cause","Le moyen","Le but","Le temps"]'::jsonb, 2, 'Après un verbe de mouvement, le supin en -um exprime le but : « je vais me coucher ».', 7),
    ('a123080c-233b-555c-b1bb-67c496e626ca'::uuid, '64eca411-9f9d-528e-a7d1-5c74899d1e49'::uuid, 'Quelle réponse attend une question introduite par num ?', 'mcq', '["Oui","Une alternative","Une précision de lieu","Non"]'::jsonb, 3, 'Num attend « non », nonne attend « oui », -ne reste neutre.', 8),
    ('bb7a8a7d-a21f-5d43-a862-5a0dc026d3a2'::uuid, '64eca411-9f9d-528e-a7d1-5c74899d1e49'::uuid, 'Que signifie nemo non ?', 'mcq', '["Tout le monde","Personne","Quelqu’un","Presque personne"]'::jsonb, 0, 'Deux négations s’annulent : « personne ne… pas », donc tout le monde.', 9),
    ('85355b1c-3c62-5a8f-8d03-a3cb8c68a93c'::uuid, '64eca411-9f9d-528e-a7d1-5c74899d1e49'::uuid, 'Que signifie « videris esse felix » ?', 'mcq', '["On te voit heureux","Tu sembles être heureux","Tu vois le bonheur","Tu seras vu heureux"]'::jsonb, 1, 'Videor, en construction personnelle, signifie « sembler ».', 10),
    ('157faeab-bac6-5d9b-b2f6-e91bca41a89c'::uuid, '64eca411-9f9d-528e-a7d1-5c74899d1e49'::uuid, 'Dans « mirabile dictu », dictu est un supin en -u.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le supin en -u complète un adjectif : « étonnant à dire ».', 11),
    ('b6bec3bc-8e48-5430-a11f-ccb12a6167e0'::uuid, '64eca411-9f9d-528e-a7d1-5c74899d1e49'::uuid, 'Que signifie uterque ?', 'mcq', '["Chacun","Un autre","L’un et l’autre","Aucun des deux"]'::jsonb, 2, 'Uterque se dit de deux : l’un et l’autre ; quisque signifie chacun.', 12),
    ('43626888-30dd-5a69-886f-2c48465fbf9d'::uuid, 'add952ac-0ef7-506a-9332-118470116bfc'::uuid, 'Au style indirect, que devient une principale déclarative ?', 'mcq', '["Une proposition au subjonctif","Une proposition infinitive","Un ablatif absolu","Une relative"]'::jsonb, 1, 'Le sujet passe à l’accusatif et le verbe à l’infinitif.', 1),
    ('1f6e7fda-2c5f-5096-a6d5-bf064bd45967'::uuid, 'add952ac-0ef7-506a-9332-118470116bfc'::uuid, 'Au style indirect, que devient une subordonnée ?', 'mcq', '["Elle passe au subjonctif","Elle reste à l’indicatif","Elle passe à l’infinitif","Elle disparaît"]'::jsonb, 0, 'Toute subordonnée du discours rapporté est au subjonctif.', 2),
    ('0d1284e7-78dc-57c5-815f-5d0e2408c2a6'::uuid, 'add952ac-0ef7-506a-9332-118470116bfc'::uuid, 'Au style indirect, par quoi est remplacé ego, désignant celui qui parle ?', 'mcq', '["Is","Ille","Se","Hic"]'::jsonb, 2, 'Le réfléchi se renvoie au locuteur dont on rapporte les paroles.', 3),
    ('4628e171-e9df-51df-8fac-4fa9f252125e'::uuid, 'add952ac-0ef7-506a-9332-118470116bfc'::uuid, 'Le subjonctif d’attraction modale a un sens propre de souhait.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il ne fait que marquer la dépendance ; on le traduit par un indicatif.', 4),
    ('c6c9711b-01d2-554f-a053-db429ef97e0b'::uuid, 'add952ac-0ef7-506a-9332-118470116bfc'::uuid, 'Que signifie « Quidquid id est, timeo Danaos et dona ferentes » ?', 'mcq', '["Quoi que ce soit, je crains les Grecs, même porteurs de présents","Ce sont les Grecs qui portent des présents","Je donne tout aux Grecs","Les Grecs craignent les dons"]'::jsonb, 0, 'Laocoon se méfie du cheval de Troie : quidquid est un relatif indéfini.', 5),
    ('69c75b85-de6c-5953-91a0-74d146b8b0a4'::uuid, 'add952ac-0ef7-506a-9332-118470116bfc'::uuid, 'Que signifie odi ?', 'mcq', '["J’ai haï autrefois","Je haïrai","On me hait","Je hais"]'::jsonb, 3, 'Odi est un parfait à sens de présent.', 6),
    ('b9f6420d-98bf-551c-9c9c-43c096abe3c5'::uuid, 'add952ac-0ef7-506a-9332-118470116bfc'::uuid, 'Que veut dire memento mori ?', 'mcq', '["Souviens-toi que tu vas mourir","La mort se souvient","Il faut mourir en souvenir","Oublie la mort"]'::jsonb, 0, 'Memento est l’impératif de memini, parfait à sens de présent.', 7),
    ('ee5a8925-6044-5dac-9a99-34cdab90f573'::uuid, 'add952ac-0ef7-506a-9332-118470116bfc'::uuid, 'Novi, parfait de nosco, signifie…', 'mcq', '["J’ai oublié","Je sais, je connais","Je suis nouveau","Je renouvelle"]'::jsonb, 1, 'Avoir appris, c’est savoir : le parfait prend le sens d’un présent.', 8),
    ('dd9fb35d-3fe8-5e75-8f6b-2322d357be6b'::uuid, 'add952ac-0ef7-506a-9332-118470116bfc'::uuid, 'Que signifie « puer decem annos natus » ?', 'mcq', '["Un enfant né il y a dix jours","Un enfant de dix ans","Dix enfants nés","Un enfant de dix mois"]'::jsonb, 1, 'Natus + accusatif de durée exprime l’âge.', 9),
    ('a46d5fdb-43c8-519c-a5b2-905874e45964'::uuid, 'add952ac-0ef7-506a-9332-118470116bfc'::uuid, 'Dans « decem annos natus », annos est un accusatif de durée.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’accusatif exprime la durée : né depuis dix ans.', 10),
    ('c2a3c4e6-b720-5a40-b94a-ce1c8487f5f6'::uuid, 'add952ac-0ef7-506a-9332-118470116bfc'::uuid, 'Après une principale au passé, quel temps exprime la simultanéité au subjonctif ?', 'mcq', '["Le présent","Le parfait","Le plus-que-parfait","L’imparfait"]'::jsonb, 3, 'Concordance : principale passée, simultanéité au subjonctif imparfait.', 11),
    ('389b4377-f439-5817-9ca3-945149221386'::uuid, 'add952ac-0ef7-506a-9332-118470116bfc'::uuid, 'Quel est le sens de quicumque ?', 'mcq', '["Chacun","Quelqu’un","Quiconque, qui que ce soit qui","Personne"]'::jsonb, 2, 'Quicumque et quisquis sont des relatifs indéfinis : quiconque.', 12),
    ('2175f497-5c96-572b-bab8-14843e93b09a'::uuid, '377c2756-1b2c-597b-86ed-478eee5b1d24'::uuid, 'De quel verbe vient monstrum ?', 'mcq', '["Monere, avertir","Mons, la montagne","Mostrare, exhiber","Mori, mourir"]'::jsonb, 0, 'Le monstre est d’abord un avertissement envoyé par les dieux.', 1),
    ('efefc4a0-90dd-5a88-90c8-c7ce5b1a3689'::uuid, '377c2756-1b2c-597b-86ed-478eee5b1d24'::uuid, 'Que désignait d’abord le templum ?', 'mcq', '["Une maison de dieux","Un espace du ciel découpé par l’augure","Un tombeau","Un autel domestique"]'::jsonb, 1, 'L’augure découpait un espace du ciel pour y lire le vol des oiseaux : d’où contempler.', 2),
    ('0242d2a1-15d3-5275-86bc-57c70623ed54'::uuid, '377c2756-1b2c-597b-86ed-478eee5b1d24'::uuid, 'D’où vient le verbe « inaugurer » ?', 'mcq', '["D’aurum, l’or","D’augere, augmenter","D’augurium, le présage","D’Augustus"]'::jsonb, 2, 'Inaugurer, c’était prendre les auspices avant d’ouvrir un lieu.', 3),
    ('4f4e868d-771f-5209-9d64-422bf59aa249'::uuid, '377c2756-1b2c-597b-86ed-478eee5b1d24'::uuid, 'Homo est apparenté à humus, la terre.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’homme est le « terrestre », opposé aux dieux du ciel.', 4),
    ('9e965821-bac0-5845-99dc-9906e3e1b977'::uuid, '377c2756-1b2c-597b-86ed-478eee5b1d24'::uuid, 'Quel est le mot populaire issu de hospitale ?', 'mcq', '["Hôpital","Hospitalité","Hospice","Hôtel"]'::jsonb, 3, 'Hôtel est le mot populaire, hôpital le mot savant.', 5),
    ('d0b79951-5c9c-512f-9b55-a50f7370086f'::uuid, '377c2756-1b2c-597b-86ed-478eee5b1d24'::uuid, 'Quel doublet savant correspond à « poison » ?', 'mcq', '["Potion","Portion","Position","Passion"]'::jsonb, 0, 'Potionem a donné poison (populaire) et potion (savant).', 6),
    ('acdcadee-e2a1-5e59-85f4-3cd85e85cd1a'::uuid, '377c2756-1b2c-597b-86ed-478eee5b1d24'::uuid, 'De quels éléments est formé exsilium ?', 'mcq', '["Ex + silere, se taire","Ex + solum, le sol","Ex + salire, sauter","Ex + sol, le soleil"]'::jsonb, 1, 'L’exilé est hors de son sol, hors de sa terre.', 7),
    ('0c096bc5-ff82-5105-b5e8-3e0520d31dd6'::uuid, '377c2756-1b2c-597b-86ed-478eee5b1d24'::uuid, 'Chez Cicéron, que désigne humanitas ?', 'mcq', '["La foule","La faiblesse humaine","La culture et la bienveillance","La mortalité"]'::jsonb, 2, 'L’humanitas est ce qui rend vraiment humain : l’éducation et la douceur envers autrui.', 8),
    ('f065291f-64e0-53d2-a29b-9d6d66db99e7'::uuid, '377c2756-1b2c-597b-86ed-478eee5b1d24'::uuid, 'Quel mot français vient de vir ?', 'mcq', '["Virgule","Virus","Virage","Vertu"]'::jsonb, 3, 'Virtus, la qualité de l’homme courageux, a donné vertu.', 9),
    ('0b572e3a-5b5f-5512-83d5-1c0c192a8a56'::uuid, '377c2756-1b2c-597b-86ed-478eee5b1d24'::uuid, 'À l’épreuve, la question de lexique demande seulement la traduction du mot.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il faut expliquer le sens en contexte et ce qu’il apporte à l’interprétation.', 10),
    ('f66a88ec-9fbb-5c4b-b040-f38b16399753'::uuid, '377c2756-1b2c-597b-86ed-478eee5b1d24'::uuid, 'Quel mot ne contient PAS la racine duc-, conduire ?', 'mcq', '["Aqueduc","Éducation","Caduc","Conduire"]'::jsonb, 2, 'Caduc vient de cadere, tomber ; les autres viennent de ducere.', 11),
    ('fbd40a95-cefa-5ee9-95c9-916c74cff50f'::uuid, '377c2756-1b2c-597b-86ed-478eee5b1d24'::uuid, 'Quel équivalent grec correspond à natura ?', 'mcq', '["Physis","Moira","Anthropos","Logos"]'::jsonb, 0, 'Physis, la nature, a donné physique ; natura et physis dérivent tous deux de verbes signifiant naître, croître.', 12),
    ('6ede1052-5a2f-500c-9c22-f8068dc302bf'::uuid, '68f4604e-d434-5294-aead-12e01462bb86'::uuid, 'Combien de temps dure l’épreuve écrite de spécialité LLCA ?', 'mcq', '["2 heures","4 heures","3 heures","5 heures"]'::jsonb, 1, 'L’épreuve dure 4 heures, avec un dictionnaire latin-français.', 1),
    ('5a9c8659-2b97-5a43-bb87-5839b58c70d1'::uuid, '68f4604e-d434-5294-aead-12e01462bb86'::uuid, 'Combien de mots environ faut-il traduire à l’écrit ?', 'mcq', '["30","300","90","150"]'::jsonb, 2, 'La traduction porte sur environ 90 mots de l’œuvre antique au programme.', 2),
    ('9a94cc66-5f4e-546a-9bbd-36bdab19cb24'::uuid, '68f4604e-d434-5294-aead-12e01462bb86'::uuid, 'Combien de points vaut l’essai ?', 'mcq', '["10","6","4","20"]'::jsonb, 0, 'La partie « compréhension et interprétation » vaut 10 points sur 20.', 3),
    ('f1ca6bc1-579c-5790-b33f-de53097a9756'::uuid, '68f4604e-d434-5294-aead-12e01462bb86'::uuid, 'Quel document est autorisé à l’épreuve ?', 'mcq', '["Les œuvres du programme","Une grammaire latine","Aucun document","Un dictionnaire latin-français"]'::jsonb, 3, 'Seul le dictionnaire latin-français est autorisé à l’écrit.', 4),
    ('781da216-af47-5342-b26c-5aad925694d2'::uuid, '68f4604e-d434-5294-aead-12e01462bb86'::uuid, 'Pour traduire, par quoi faut-il commencer après avoir lu le chapeau ?', 'mcq', '["Par chercher chaque mot au dictionnaire","Par repérer les verbes conjugués","Par traduire le premier mot","Par écrire le français"]'::jsonb, 1, 'Un verbe conjugué = une proposition : c’est l’ossature de la phrase.', 5),
    ('e1db8bcd-99cb-5165-b206-fe907b842c66'::uuid, '68f4604e-d434-5294-aead-12e01462bb86'::uuid, 'La question sur le fait de langue demande d’identifier la forme puis de l’interpréter.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Un point pour l’identification, un point pour ce que la forme apporte au sens.', 6),
    ('8576f402-18bc-5a10-9f21-ee0c18261a20'::uuid, '68f4604e-d434-5294-aead-12e01462bb86'::uuid, 'Combien de textes compte le corpus de l’épreuve ?', 'mcq', '["Deux","Quatre","Un seul","Trois"]'::jsonb, 3, 'Le texte antique au programme, un extrait de l’œuvre moderne, et un court texte antique en traduction.', 7),
    ('7206a1d1-39c3-5f06-9487-269564738819'::uuid, '68f4604e-d434-5294-aead-12e01462bb86'::uuid, 'Quelle œuvre moderne accompagne les Tristes pour 2026-2028 ?', 'mcq', '["La ferme africaine de Karen Blixen","Mémoires d’Hadrien","L’Exil et le Royaume","Le Baron perché"]'::jsonb, 0, 'Le Baron perché accompagne Lucien, pour le grec.', 8),
    ('f39b7dd5-b7ce-5e3c-a215-e4c8df3a4a7e'::uuid, '68f4604e-d434-5294-aead-12e01462bb86'::uuid, 'Dans un essai, traiter les textes l’un après l’autre est la meilleure méthode.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il faut les confronter à l’intérieur de chaque partie.', 9),
    ('5163e672-42d5-5ae3-bc3b-1bfe682a026f'::uuid, '68f4604e-d434-5294-aead-12e01462bb86'::uuid, 'Chez Ovide, quelle unité correspond souvent à une phrase ?', 'mcq', '["Le vers seul","Le distique élégiaque","La strophe","Le chant"]'::jsonb, 1, 'Un hexamètre et un pentamètre forment souvent une unité de sens.', 10),
    ('aaf51f5d-100d-5b21-8472-696cb8a7ff40'::uuid, '68f4604e-d434-5294-aead-12e01462bb86'::uuid, 'À l’oral de contrôle, combien de mots au plus faut-il traduire ?', 'mcq', '["90","10","25","50"]'::jsonb, 2, 'L’extrait à traduire compte 25 mots au plus, tirés du passage commenté.', 11),
    ('790c6e65-06c3-5d89-8495-3c98e3b9b8c1'::uuid, '68f4604e-d434-5294-aead-12e01462bb86'::uuid, 'Pourquoi relire sa traduction à la fin ?', 'mcq', '["Pour la raccourcir","Pour vérifier que chaque mot est traduit et que le français a un sens","Pour ajouter des notes","Pour recopier le latin"]'::jsonb, 1, 'Un oubli ou un contresens se repère souvent à la relecture d’une phrase française absurde.', 12),
    ('79af701c-627b-5571-8fff-bf41eef44e6c'::uuid, 'd4bc1887-8c6a-56af-8867-c7cc4f6e44cf'::uuid, 'Dans *A Modest Proposal* (1729), que « propose » Swift pour régler la misère irlandaise ?', 'mcq', '["Une réforme agraire","L’émigration vers l’Amérique","Que les riches mangent les enfants des pauvres","Une taxe sur les propriétaires anglais"]'::jsonb, 2, 'La proposition monstrueuse, exposée sur un ton calme, est le cœur de l’ironie satirique.', 1),
    ('13b068b5-635f-5f8e-8589-9998a57f635b'::uuid, 'd4bc1887-8c6a-56af-8867-c7cc4f6e44cf'::uuid, 'Quelle chanson de Billie Holiday (1939) dénonce les lynchages dans le Sud des États-Unis ?', 'mcq', '["*Strange Fruit*","*Summertime*","*Blowin’ in the Wind*","*Mississippi Goddam*"]'::jsonb, 0, 'Les « fruits étranges » sont les corps des victimes pendus aux arbres.', 2),
    ('cfe7c3cb-0c45-58a0-af62-7c5085b0137c'::uuid, 'd4bc1887-8c6a-56af-8867-c7cc4f6e44cf'::uuid, 'Quelle phrase célèbre vient d’*Animal Farm* ?', 'mcq', '["« Big Brother is watching you »","« All animals are equal, but some animals are more equal than others »","« I have a dream »","« To be or not to be »"]'::jsonb, 1, 'Orwell (1945) montre comment une révolution se retourne contre son idéal d’égalité.', 3),
    ('beeeed12-b61f-5910-9e66-d6b833527304'::uuid, 'd4bc1887-8c6a-56af-8867-c7cc4f6e44cf'::uuid, '*The Jungle* d’Upton Sinclair (1906) révèle les conditions de travail…', 'mcq', '["Des mines de charbon galloises","Des plantations de coton","Des usines textiles de Manchester","Des abattoirs de Chicago"]'::jsonb, 3, 'Le scandale conduit à une loi fédérale sur l’hygiène des aliments.', 4),
    ('b90f1044-b5ed-5fb9-9502-0a685f484dd8'::uuid, 'd4bc1887-8c6a-56af-8867-c7cc4f6e44cf'::uuid, 'Bob Dylan a reçu le prix Nobel de littérature en 2016.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le jury a reconnu la chanson comme une forme de poésie.', 5),
    ('76d53c02-6aad-549f-bb79-3426a481f364'::uuid, 'd4bc1887-8c6a-56af-8867-c7cc4f6e44cf'::uuid, 'Quel procédé repose sur le fait de dire le contraire de ce qu’on pense ?', 'mcq', '["L’hyperbole","La métaphore","L’ironie","L’allitération"]'::jsonb, 2, 'L’ironie compte sur le lecteur pour rétablir le vrai sens.', 6),
    ('99b63c4e-3993-5785-8703-29097d71b8f0'::uuid, 'd4bc1887-8c6a-56af-8867-c7cc4f6e44cf'::uuid, 'Quel roman de 1852 a pesé dans le débat sur l’abolition de l’esclavage ?', 'mcq', '["*Uncle Tom’s Cabin*","*Hard Times*","*The Grapes of Wrath*","*Great Expectations*"]'::jsonb, 0, 'Harriet Beecher Stowe y montre l’esclavage de l’intérieur.', 7),
    ('527f2731-a56f-5d3c-8ee7-9592debec106'::uuid, 'd4bc1887-8c6a-56af-8867-c7cc4f6e44cf'::uuid, 'Dans *Hard Times* (1854), Dickens critique une école qui ne veut enseigner que…', 'mcq', '["La religion","Les « facts »","Le latin","La musique"]'::jsonb, 1, 'Le roman attaque l’utilitarisme de la ville industrielle.', 8),
    ('e102e88e-18f6-587e-95b5-f88571bf647a'::uuid, 'd4bc1887-8c6a-56af-8867-c7cc4f6e44cf'::uuid, 'Que dénonce Hogarth dans sa gravure *Gin Lane* (1751) ?', 'mcq', '["La guerre contre la France","La monarchie","Les ravages de l’alcool chez les pauvres","La traite négrière"]'::jsonb, 2, 'La gravure montre un quartier londonien détruit par le gin.', 9),
    ('4df2821f-1393-50a1-ad63-be4f43bd24a4'::uuid, 'd4bc1887-8c6a-56af-8867-c7cc4f6e44cf'::uuid, 'Comment traduire « to raise awareness » ?', 'mcq', '["Élever le niveau","Sensibiliser","Se réveiller","Protester"]'::jsonb, 1, 'Expression très utile dans une synthèse sur l’art engagé.', 10),
    ('954362fd-7d87-565a-a3ce-62868bc2cdaf'::uuid, 'd4bc1887-8c6a-56af-8867-c7cc4f6e44cf'::uuid, 'Banksy est un artiste de rue dont l’identité est publiquement connue.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il reste anonyme : son œuvre parle sans que son auteur apparaisse.', 11),
    ('db68d264-4804-5ebf-9838-1d2db28e88e8'::uuid, 'd4bc1887-8c6a-56af-8867-c7cc4f6e44cf'::uuid, '*The Grapes of Wrath* (1939) raconte…', 'mcq', '["La ruée vers l’or","La guerre de Sécession","La vie à Harlem","L’exode des fermiers ruinés vers la Californie"]'::jsonb, 3, 'Steinbeck suit la famille Joad pendant la Grande Dépression.', 12),
    ('267f65b1-d8be-5a87-a978-da40a4bced08'::uuid, '8fe36e85-422f-5e48-94e7-8675575de21f'::uuid, 'En quelle année un juge américain déclare-t-il *Ulysses* de Joyce non obscène ?', 'mcq', '["1922","1945","1933","1960"]'::jsonb, 2, 'Le juge Woolsey lève l’interdiction en 1933.', 1),
    ('a739133d-76b6-5e7e-ae9a-d588a77db4ca'::uuid, '8fe36e85-422f-5e48-94e7-8675575de21f'::uuid, 'Quel éditeur est acquitté en 1960 dans le procès de *Lady Chatterley’s Lover* ?', 'mcq', '["Faber","Oxford University Press","Macmillan","Penguin"]'::jsonb, 3, 'Le procès reconnaît la valeur littéraire du roman de D. H. Lawrence.', 2),
    ('696ca9f1-c4a3-58a4-a02b-8c0d3fc6536c'::uuid, '8fe36e85-422f-5e48-94e7-8675575de21f'::uuid, 'Quel poème d’Allen Ginsberg a donné lieu à un procès pour obscénité en 1957 ?', 'mcq', '["*Howl*","*The Waste Land*","*Song of Myself*","*Daddy*"]'::jsonb, 0, 'L’éditeur, à San Francisco, est acquitté.', 3),
    ('ccea7474-a41d-5c76-9e6c-c1952496eafb'::uuid, '8fe36e85-422f-5e48-94e7-8675575de21f'::uuid, 'Le Code Hays encadrait…', 'mcq', '["La presse écrite britannique","Le contenu des films hollywoodiens","La radio publique","L’édition de poésie"]'::jsonb, 1, 'Appliqué de 1934 à 1968, il pousse les cinéastes à suggérer plutôt qu’à montrer.', 4),
    ('a1effeb5-3188-5cc3-a255-681614b304fc'::uuid, '8fe36e85-422f-5e48-94e7-8675575de21f'::uuid, 'Salman Rushdie a été visé par une fatwa après la publication de *The Satanic Verses*.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La fatwa de 1989 l’oblige à vivre des années sous protection.', 5),
    ('fa5f8fb3-ca2a-5fbb-8a6d-d671eed30256'::uuid, '8fe36e85-422f-5e48-94e7-8675575de21f'::uuid, 'Quel artiste a peint les *Campbell’s Soup Cans* (1962) ?', 'mcq', '["Roy Lichtenstein","Banksy","Jackson Pollock","Andy Warhol"]'::jsonb, 3, 'Le pop art interroge la frontière entre art et produit de consommation.', 6),
    ('61a5d04a-09f6-5a99-9872-e36057402acf'::uuid, '8fe36e85-422f-5e48-94e7-8675575de21f'::uuid, 'Pourquoi Oscar Wilde est-il condamné en 1895 ?', 'mcq', '["Pour « grossière indécence », c’est-à-dire son homosexualité","Pour trahison","Pour avoir publié un pamphlet contre la reine","Pour escroquerie"]'::jsonb, 0, 'Il est condamné à deux ans de travaux forcés.', 7),
    ('9b0fe7d0-02e9-5a76-bd16-156df1650809'::uuid, '8fe36e85-422f-5e48-94e7-8675575de21f'::uuid, 'Quel argument a sauvé *Ulysses* et *Lady Chatterley* devant les juges ?', 'mcq', '["Leur succès commercial","Leur valeur littéraire","L’âge de leurs auteurs","Leur caractère religieux"]'::jsonb, 1, 'La valeur artistique justifiait ce que les livres montraient.', 8),
    ('c16f2950-68aa-5deb-ae47-eafb820f907d'::uuid, '8fe36e85-422f-5e48-94e7-8675575de21f'::uuid, 'Que se passe-t-il en 2018 avec *Girl with Balloon* de Banksy ?', 'mcq', '["Elle est volée","Elle est interdite","Elle s’autodétruit en partie juste après sa vente","Elle est repeinte par la ville"]'::jsonb, 2, 'Le geste, censé critiquer le marché de l’art, fait monter sa valeur.', 9),
    ('d6282172-0d2b-538b-9ad4-673f2f76fafd'::uuid, '8fe36e85-422f-5e48-94e7-8675575de21f'::uuid, 'Comment dit-on « la liberté d’expression » en anglais ?', 'mcq', '["Freedom of speech","Free will","Speech therapy","Liberty of press"]'::jsonb, 0, 'Aux États-Unis, elle est garantie par le premier amendement.', 10),
    ('2bae67e9-e75a-502b-9134-ddf819bb9c18'::uuid, '8fe36e85-422f-5e48-94e7-8675575de21f'::uuid, 'Le Code Hays est toujours appliqué aujourd’hui à Hollywood.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est abandonné en 1968 au profit du classement des films par âge.', 11),
    ('097a5155-8f11-5772-a773-7ba96ceedd4c'::uuid, '8fe36e85-422f-5e48-94e7-8675575de21f'::uuid, 'Que signifie « to spark a debate » ?', 'mcq', '["Clore un débat","Perdre un débat","Arbitrer un débat","Déclencher un débat"]'::jsonb, 3, 'To spark : faire jaillir une étincelle.', 12),
    ('3365455b-9207-568a-ae85-cf7eb0f59db5'::uuid, '4d13ef34-f58f-5b32-a9a8-6656aeed6ea7'::uuid, 'Quel levier d’Aristote repose sur la crédibilité de l’orateur ?', 'mcq', '["Le pathos","L’ethos","Le logos","Le kairos"]'::jsonb, 1, 'Ethos : on écoute l’orateur parce qu’on lui fait confiance.', 1),
    ('e8e5f4eb-3d7e-5ec9-9127-a4572fd3c6d1'::uuid, '4d13ef34-f58f-5b32-a9a8-6656aeed6ea7'::uuid, 'Qui a prononcé le *Gettysburg Address* en 1863 ?', 'mcq', '["George Washington","Frederick Douglass","Abraham Lincoln","Thomas Jefferson"]'::jsonb, 2, 'Il y définit la démocratie par un tricolon célèbre.', 2),
    ('b2da72d0-b7d2-5dfa-87a1-3ddc6abfde25'::uuid, '4d13ef34-f58f-5b32-a9a8-6656aeed6ea7'::uuid, '« Of the people, by the people, for the people » est un exemple de…', 'mcq', '["Tricolon","Chiasme","Oxymore","Question rhétorique"]'::jsonb, 0, 'Une série de trois éléments, rythmée et facile à retenir.', 3),
    ('2b0edadf-268c-5f0a-ad5d-2dcff3a08f5a'::uuid, '4d13ef34-f58f-5b32-a9a8-6656aeed6ea7'::uuid, 'La phrase de Kennedy « Ask not what your country can do for you — ask what you can do for your country » repose sur…', 'mcq', '["Une anaphore","Une litote","Un euphémisme","Un chiasme"]'::jsonb, 3, 'Les termes s’inversent : A-B / B-A.', 4),
    ('4d937c6b-dcd7-5f22-8521-4d4e476c5cfd'::uuid, '4d13ef34-f58f-5b32-a9a8-6656aeed6ea7'::uuid, 'Dans *12 Angry Men*, combien de jurés votent « coupable » au premier vote ?', 'mcq', '["Six","Onze","Douze","Neuf"]'::jsonb, 1, 'Seul le juré n° 8 refuse de voter coupable sans discussion.', 5),
    ('06da5828-e5c6-53a7-be96-680bb90c0733'::uuid, '4d13ef34-f58f-5b32-a9a8-6656aeed6ea7'::uuid, 'Quel acteur joue le juré n° 8 dans le film de Sidney Lumet ?', 'mcq', '["Henry Fonda","Marlon Brando","James Stewart","Gregory Peck"]'::jsonb, 0, 'Il incarne le doute raisonnable face aux certitudes.', 6),
    ('7688b9e3-cf6c-5a00-a84c-cd5c4122cf76'::uuid, '4d13ef34-f58f-5b32-a9a8-6656aeed6ea7'::uuid, 'Le juré n° 8 affirme dès le début que l’accusé est innocent.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il dit seulement qu’il a un doute raisonnable et veut en parler.', 7),
    ('a037efa8-7b5e-50e7-a031-d2b49bfa7fac'::uuid, '4d13ef34-f58f-5b32-a9a8-6656aeed6ea7'::uuid, 'Quelle oratrice pose la question « Ain’t I a Woman? » en 1851 ?', 'mcq', '["Harriet Tubman","Rosa Parks","Sojourner Truth","Maya Angelou"]'::jsonb, 2, 'Ancienne esclave, elle réclame les droits des femmes noires.', 8),
    ('894099ba-5149-5094-a026-597965901f51'::uuid, '4d13ef34-f58f-5b32-a9a8-6656aeed6ea7'::uuid, 'Dans *Julius Caesar*, Marc Antoine répète que Brutus est « an honourable man » pour…', 'mcq', '["Le défendre sincèrement","Retourner la foule contre lui par l’ironie","Annoncer sa mort","Demander sa grâce"]'::jsonb, 1, 'À force de répétition, la phrase finit par signifier son contraire.', 9),
    ('447dd7cf-d755-548c-9655-bab759c6a8ef'::uuid, '4d13ef34-f58f-5b32-a9a8-6656aeed6ea7'::uuid, 'Le discours de Churchill de 1940 est célèbre pour l’anaphore de « we shall fight ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La répétition en tête de phrase martèle la détermination.', 10),
    ('f344aa8e-5d25-5ade-a08f-297a06b44471'::uuid, '4d13ef34-f58f-5b32-a9a8-6656aeed6ea7'::uuid, 'Que signifie « reasonable doubt » ?', 'mcq', '["Une erreur judiciaire","Un témoin douteux","Une preuve irréfutable","Le doute raisonnable"]'::jsonb, 3, 'Principe clé : on ne condamne pas s’il subsiste un doute raisonnable.', 11),
    ('e173ec84-83a1-5771-8a32-6d8b81b63ef6'::uuid, '4d13ef34-f58f-5b32-a9a8-6656aeed6ea7'::uuid, 'Quelle est la particularité de mise en scène de *12 Angry Men* ?', 'mcq', '["Un huis clos presque entièrement dans une seule pièce","Des flash-backs sur le crime","Un tournage en couleurs dans plusieurs villes","Une voix off omniprésente"]'::jsonb, 0, 'La caméra se rapproche peu à peu : la pression monte.', 12),
    ('daeb9741-2637-5284-bf26-dadda41509ce'::uuid, 'e775a374-c375-5a2d-a9f2-c148ed5e8b34'::uuid, 'Qui a écrit *The Handmaid’s Tale* (1985) ?', 'mcq', '["Doris Lessing","Toni Morrison","Margaret Atwood","Ursula K. Le Guin"]'::jsonb, 2, 'Romancière canadienne, elle en publie la suite en 2019.', 1),
    ('f9e0e9fc-7cd9-5b01-95a0-a898db5a8d48'::uuid, 'e775a374-c375-5a2d-a9f2-c148ed5e8b34'::uuid, 'Comment s’appelle le régime qui a remplacé les États-Unis dans le roman ?', 'mcq', '["Oceania","Gilead","Panem","Airstrip One"]'::jsonb, 1, 'Gilead est une théocratie fondée sur une lecture littérale de la Bible.', 2),
    ('2e38a2ed-f716-5d55-8bd9-5ff71ae0cfbd'::uuid, 'e775a374-c375-5a2d-a9f2-c148ed5e8b34'::uuid, 'Que signifie le nom « Offred » ?', 'mcq', '["« Celle qui appartient à Fred »","« Offerte en rouge »","« Celle qui a fui »","« Libérée »"]'::jsonb, 0, 'Of Fred : même son nom lui a été retiré.', 3),
    ('c7c212da-fe22-5e2c-9627-8220ddf5fe71'::uuid, 'e775a374-c375-5a2d-a9f2-c148ed5e8b34'::uuid, 'Quel roman d’Orwell invente Big Brother et la Newspeak ?', 'mcq', '["*Animal Farm*","*Brave New World*","*Fahrenheit 451*","*Nineteen Eighty-Four*"]'::jsonb, 3, 'Publié en 1949, il imagine une surveillance totale.', 4),
    ('20c60c63-584b-52af-b129-4d903f0fe390'::uuid, 'e775a374-c375-5a2d-a9f2-c148ed5e8b34'::uuid, 'Dans *Fahrenheit 451*, les pompiers…', 'mcq', '["Brûlent les livres","Éteignent les incendies de forêt","Surveillent les écrans","Gardent les frontières"]'::jsonb, 0, 'Ray Bradbury, 1953 : 451 °F est la température à laquelle le papier brûle.', 5),
    ('0a2f5032-111a-5fbd-beb6-23462604effd'::uuid, 'e775a374-c375-5a2d-a9f2-c148ed5e8b34'::uuid, 'Comment s’appelle le réseau de résistance dans le roman d’Atwood ?', 'mcq', '["Mayday","Underground","Freedom","Red Cross"]'::jsonb, 0, 'Ofglen, la compagne de courses d’Offred, en fait partie.', 6),
    ('d4e76097-5fb0-5db8-a099-7ee6b43067a6'::uuid, 'e775a374-c375-5a2d-a9f2-c148ed5e8b34'::uuid, 'Le roman s’achève sur un colloque d’historiens en 2195.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les « Historical Notes » commentent le récit avec une légèreté glaçante.', 7),
    ('c8262a92-a69b-5d18-945e-e759ba1ce0f9'::uuid, 'e775a374-c375-5a2d-a9f2-c148ed5e8b34'::uuid, 'Qui est Serena Joy ?', 'mcq', '["L’amie rebelle d’Offred","Une servante évadée","L’épouse du Commandant","La fille d’Offred"]'::jsonb, 2, 'Ancienne chanteuse, elle militait pour le retour des femmes au foyer.', 8),
    ('c1c8b974-f3c5-5ab3-b1a7-960a7422a8e9'::uuid, 'e775a374-c375-5a2d-a9f2-c148ed5e8b34'::uuid, 'Que dit Atwood de l’invention de son roman ?', 'mcq', '["Tout y est imaginaire","Rien n’y est arrivé nulle part avant","Elle s’est inspirée d’un rêve","Rien n’y figure qui ne soit déjà arrivé quelque part"]'::jsonb, 3, 'La dystopie rassemble des faits réels, elle ne les invente pas.', 9),
    ('6eccb651-5b3c-5895-9bcc-6f2d0880120d'::uuid, 'e775a374-c375-5a2d-a9f2-c148ed5e8b34'::uuid, 'Dans *Brave New World* (1932), la population est maintenue heureuse par…', 'mcq', '["La peur de la guerre","Le conditionnement et une drogue, le soma","La prière obligatoire","Des écrans dans chaque maison"]'::jsonb, 1, 'Huxley imagine un bonheur imposé, pas une terreur.', 10),
    ('6d4841da-2419-51a5-bd3b-d5c27a0a4eac'::uuid, 'e775a374-c375-5a2d-a9f2-c148ed5e8b34'::uuid, 'Comment traduire « to be stripped of one’s rights » ?', 'mcq', '["Défendre ses droits","Céder ses droits","Être privé de ses droits","Réclamer ses droits"]'::jsonb, 2, 'To strip : dépouiller.', 11),
    ('26ae48fb-7ffd-5fe3-a6fc-3a905f683bb1'::uuid, 'e775a374-c375-5a2d-a9f2-c148ed5e8b34'::uuid, 'Le costume rouge des servantes est devenu un symbole de manifestation.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Des militantes le portent pour défendre les droits des femmes.', 12),
    ('6064b3f4-078a-5651-9c7e-ffbb779191fb'::uuid, 'fa92e8c9-510e-58d0-aaf6-cbb57c9a2819'::uuid, 'Combien de vers compte un sonnet shakespearien ?', 'mcq', '["12","16","10","14"]'::jsonb, 3, 'Trois quatrains et un distique final.', 1),
    ('c217b707-5154-5ab5-9727-1c13d5ccdcad'::uuid, 'fa92e8c9-510e-58d0-aaf6-cbb57c9a2819'::uuid, 'Quel vers ouvre le Sonnet 18 de Shakespeare ?', 'mcq', '["« To be or not to be »","« Shall I compare thee to a summer’s day? »","« I wandered lonely as a cloud »","« Hope is the thing with feathers »"]'::jsonb, 1, 'Le poème promet l’éternité à la personne aimée.', 2),
    ('f3cedb79-f443-50be-98d2-3c899e32a2ff'::uuid, 'fa92e8c9-510e-58d0-aaf6-cbb57c9a2819'::uuid, 'Wordsworth définit la poésie comme « the spontaneous overflow of powerful feelings ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Dans la préface des *Lyrical Ballads* (1800).', 3),
    ('2707e0ed-1d71-586d-a72f-f59d006ab488'::uuid, 'fa92e8c9-510e-58d0-aaf6-cbb57c9a2819'::uuid, 'Avec qui Wordsworth publie-t-il les *Lyrical Ballads* en 1798 ?', 'mcq', '["Coleridge","Byron","Keats","Shelley"]'::jsonb, 0, 'Ce recueil est considéré comme l’acte de naissance du romantisme anglais.', 4),
    ('95899130-2ea6-5a59-b17f-585f27f76ecb'::uuid, 'fa92e8c9-510e-58d0-aaf6-cbb57c9a2819'::uuid, 'Dans *The Piano*, pourquoi Ada ne parle-t-elle pas ?', 'mcq', '["Elle ne parle pas anglais","Elle a fait vœu de silence religieux","Elle est muette depuis l’enfance","Elle a perdu la voix pendant le voyage"]'::jsonb, 2, 'Le piano devient sa voix.', 5),
    ('40566569-fc13-50d8-9e39-c63bac3a82f7'::uuid, 'fa92e8c9-510e-58d0-aaf6-cbb57c9a2819'::uuid, 'Qui a réalisé *The Piano* (1993) ?', 'mcq', '["Sofia Coppola","Jane Campion","Kathryn Bigelow","Greta Gerwig"]'::jsonb, 1, 'Elle est la première réalisatrice à recevoir la Palme d’or.', 6),
    ('7c4b7e55-bbf9-507a-a7c6-c9faed4b31a5'::uuid, 'fa92e8c9-510e-58d0-aaf6-cbb57c9a2819'::uuid, 'Dans quel pays se déroule *The Piano* ?', 'mcq', '["En Écosse","En Australie","Au Canada","En Nouvelle-Zélande"]'::jsonb, 3, 'Ada y est envoyée pour épouser un colon, Stewart.', 7),
    ('c6c5b939-cdaa-516c-8ee2-b38942c48c41'::uuid, 'fa92e8c9-510e-58d0-aaf6-cbb57c9a2819'::uuid, 'La poésie de Sylvia Plath est dite « confessionnelle ».', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle expose le moi le plus intime, comme Robert Lowell.', 8),
    ('bf95d784-c182-5617-ab23-f974373f1e13'::uuid, 'fa92e8c9-510e-58d0-aaf6-cbb57c9a2819'::uuid, 'Qui obtient le piano d’Ada contre des terres et lui propose un marché ?', 'mcq', '["Stewart","Baines","Flora","Son père"]'::jsonb, 1, 'Ada regagne le piano touche après touche, en échange de leçons.', 9),
    ('222f0337-78df-5da9-832a-342fc917fe98'::uuid, 'fa92e8c9-510e-58d0-aaf6-cbb57c9a2819'::uuid, 'Comment traduire « grief » ?', 'mcq', '["Le chagrin, le deuil","La colère","La honte","La joie"]'::jsonb, 0, 'À ne pas confondre avec le français « grief » (reproche).', 10),
    ('cfa72bd7-78b0-5d53-9dd0-7ce2664d7817'::uuid, 'fa92e8c9-510e-58d0-aaf6-cbb57c9a2819'::uuid, 'Quel compositeur signe la musique de *The Piano* ?', 'mcq', '["John Williams","Hans Zimmer","Michael Nyman","Philip Glass"]'::jsonb, 2, 'Sa musique tient lieu de voix au personnage d’Ada.', 11),
    ('698950b9-8dad-5607-9d8c-95aaf0e90d62'::uuid, 'fa92e8c9-510e-58d0-aaf6-cbb57c9a2819'::uuid, 'Que signifie « to convey an emotion » ?', 'mcq', '["Cacher une émotion","Maîtriser une émotion","Exagérer une émotion","Transmettre une émotion"]'::jsonb, 3, 'To convey : transmettre, communiquer.', 12),
    ('ce9cce29-f424-5ca3-af04-5227b7b300e2'::uuid, 'f1e48311-ee7d-558d-899e-aea27325872f'::uuid, 'Qui joue Beatrice dans *Much Ado About Nothing* de Kenneth Branagh ?', 'mcq', '["Kate Winslet","Helena Bonham Carter","Emma Thompson","Judi Dench"]'::jsonb, 2, 'Branagh joue lui-même Benedick.', 1),
    ('4a0e8d75-1774-5115-9145-5a61097a1cc2'::uuid, 'f1e48311-ee7d-558d-899e-aea27325872f'::uuid, 'Comment Shakespeare qualifie-t-il la joute entre Beatrice et Benedick ?', 'mcq', '["A merry war","A cold war","A love game","A civil war"]'::jsonb, 0, 'Une guerre joyeuse de mots d’esprit qui cache un amour.', 2),
    ('4e1189fd-f4ee-5724-8d0e-77e8327f2359'::uuid, 'f1e48311-ee7d-558d-899e-aea27325872f'::uuid, 'Quel personnage monte une fausse preuve pour salir Hero ?', 'mcq', '["Dogberry","Don Pedro","Claudio","Don John"]'::jsonb, 3, 'Le frère jaloux fait croire à l’infidélité de Hero.', 3),
    ('9ae8701d-8fe7-54b6-8afe-38edde99fdfa'::uuid, 'f1e48311-ee7d-558d-899e-aea27325872f'::uuid, 'Sur quel jeu de mots repose le titre *Much Ado About Nothing* ?', 'mcq', '["Nothing / nodding","Nothing / noting","Ado / adieu","Much / match"]'::jsonb, 1, '« Noting » : épier, remarquer — tout le monde s’observe dans la pièce.', 4),
    ('1b667fc2-ae6e-5394-bf63-2fe9e989d8c3'::uuid, 'f1e48311-ee7d-558d-899e-aea27325872f'::uuid, 'Dans la pièce, Hero se fait passer pour morte afin d’être lavée de l’accusation.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La fausse mort est une dernière mise en scène, qui rétablit la vérité.', 5),
    ('acdc608b-87bc-5129-a3a8-cea450862a28'::uuid, 'f1e48311-ee7d-558d-899e-aea27325872f'::uuid, 'Qu’est-ce qu’un monologue dramatique, comme « My Last Duchess » de Browning ?', 'mcq', '["Un dialogue entre deux amants","Un poème où un personnage parle et se trahit devant un auditeur muet","Une tirade de tragédie grecque","Un sonnet en vers libres"]'::jsonb, 1, 'Le duc révèle sans le vouloir qu’il a fait disparaître sa femme.', 6),
    ('d5f82eff-4bed-5e3e-84e4-b31ac9121719'::uuid, 'f1e48311-ee7d-558d-899e-aea27325872f'::uuid, 'Quel sociologue décrit la vie sociale comme un théâtre avec scène et coulisses ?', 'mcq', '["Erving Goffman","Max Weber","Pierre Bourdieu","Émile Durkheim"]'::jsonb, 0, '*The Presentation of Self in Everyday Life*, 1956.', 7),
    ('d2c0da71-69ad-5297-9c2d-64de6d7127d8'::uuid, 'f1e48311-ee7d-558d-899e-aea27325872f'::uuid, 'Dans *The Importance of Being Earnest* (1895), les héros…', 'mcq', '["Écrivent leurs mémoires","Partent en guerre","S’inventent un double pour échapper aux convenances","Se déguisent en femmes"]'::jsonb, 2, 'Oscar Wilde se moque de la respectabilité victorienne.', 8),
    ('0b280d3c-a310-501a-98b9-642dab6fb321'::uuid, 'f1e48311-ee7d-558d-899e-aea27325872f'::uuid, '*Narrative of the Life of Frederick Douglass* est un récit autobiographique d’esclave.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Publié en 1845, il montre comment apprendre à lire libère le « je ».', 9),
    ('515b333d-e1f9-588a-92c3-17e74ba92299'::uuid, 'f1e48311-ee7d-558d-899e-aea27325872f'::uuid, 'Que signifie « to eavesdrop » ?', 'mcq', '["Calomnier","Se déguiser","Mentir","Écouter aux portes"]'::jsonb, 3, 'Les « gulling scenes » reposent sur des conversations écoutées exprès.', 10),
    ('b5510c14-d3b6-560e-bb80-7b0193eea5cf'::uuid, 'f1e48311-ee7d-558d-899e-aea27325872f'::uuid, 'Dans quelle région Branagh tourne-t-il son film ?', 'mcq', '["En Écosse","En Toscane","En Andalousie","En Provence"]'::jsonb, 1, 'Le soleil italien donne à la comédie son éclat.', 11),
    ('97eb2d61-c918-582a-bfb0-94c27d413fcc'::uuid, 'f1e48311-ee7d-558d-899e-aea27325872f'::uuid, 'Quel personnage, ridicule chef de la garde, découvre pourtant la vérité ?', 'mcq', '["Benedick","Leonato","Dogberry","Borachio"]'::jsonb, 2, 'Ironie shakespearienne : le plus sot démasque le complot.', 12),
    ('3e1162b7-0130-5469-ae72-698650e818b8'::uuid, '5cf9b765-e17f-5f6b-9cff-d746b1f2fe72'::uuid, 'Que désigne le mot « Bildungsroman » ?', 'mcq', '["Un roman épistolaire","Un roman historique","Un roman de formation","Un roman policier"]'::jsonb, 2, 'Le héros y grandit à travers une suite d’épreuves.', 1),
    ('bcb965aa-9146-52b8-92f3-4330783b9742'::uuid, '5cf9b765-e17f-5f6b-9cff-d746b1f2fe72'::uuid, 'Dans *Great Expectations*, qui est en réalité le bienfaiteur de Pip ?', 'mcq', '["Miss Havisham","Un ancien forçat","Son oncle","Joe Gargery"]'::jsonb, 1, 'Pip apprend que la vraie valeur n’est pas le rang social.', 2),
    ('5bed0d47-159b-5f7a-9b73-5afbca0d6735'::uuid, '5cf9b765-e17f-5f6b-9cff-d746b1f2fe72'::uuid, 'Qui a écrit *The Catcher in the Rye* (1951) ?', 'mcq', '["J. D. Salinger","Jack Kerouac","John Steinbeck","F. Scott Fitzgerald"]'::jsonb, 0, 'Holden Caulfield y rejette le monde « phony » des adultes.', 3),
    ('170775be-bae2-50a6-8bd6-158d357f3f31'::uuid, '5cf9b765-e17f-5f6b-9cff-d746b1f2fe72'::uuid, 'En quelle personne *Boyhood* de Coetzee est-il écrit ?', 'mcq', '["Première personne","Deuxième personne","Première personne du pluriel","Troisième personne"]'::jsonb, 3, 'Une autobiographie qui refuse le « je » et tient l’enfant à distance.', 4),
    ('ff535c13-ca6f-5d0a-8fde-362caf837544'::uuid, '5cf9b765-e17f-5f6b-9cff-d746b1f2fe72'::uuid, '*Boyhood* est écrit au présent.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'On reste dans l’instant de l’enfant, sans sagesse d’adulte.', 5),
    ('18651e47-22e2-5b62-be31-851192e0661f'::uuid, '5cf9b765-e17f-5f6b-9cff-d746b1f2fe72'::uuid, 'Dans quelle ville de province la famille du jeune Coetzee s’installe-t-elle ?', 'mcq', '["Johannesburg","Worcester","Durban","Pretoria"]'::jsonb, 1, 'Une petite ville près du Cap, dans les années 1940-1950.', 6),
    ('a90676c8-510c-5074-afcb-71f3fe149f55'::uuid, '5cf9b765-e17f-5f6b-9cff-d746b1f2fe72'::uuid, 'Quelle religion l’enfant déclare-t-il au hasard à l’école ?', 'mcq', '["Catholique","Juive","Protestante","Musulmane"]'::jsonb, 0, 'Il doit ensuite tenir ce mensonge.', 7),
    ('b3119040-539d-5f84-bd9f-24def0edc8ce'::uuid, '5cf9b765-e17f-5f6b-9cff-d746b1f2fe72'::uuid, 'En quelle année J. M. Coetzee a-t-il reçu le prix Nobel de littérature ?', 'mcq', '["1993","2016","2003","1987"]'::jsonb, 2, 'Écrivain sud-africain né en 1940 au Cap.', 8),
    ('eb42f6b2-15ce-540e-8563-968bd4283f25'::uuid, '5cf9b765-e17f-5f6b-9cff-d746b1f2fe72'::uuid, 'Qui a popularisé en littérature le mot « épiphanie » (révélation soudaine) ?', 'mcq', '["Charles Dickens","James Joyce","Harper Lee","Charlotte Brontë"]'::jsonb, 1, 'Dans l’œuvre de Joyce, un détail banal révèle soudain une vérité.', 9),
    ('c5e34514-44c9-5061-80c1-05f514098f58'::uuid, '5cf9b765-e17f-5f6b-9cff-d746b1f2fe72'::uuid, 'Dans *To Kill a Mockingbird*, Scout découvre le racisme de son village grâce au procès défendu par son père.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Harper Lee, 1960 : Atticus Finch défend un homme noir accusé à tort.', 10),
