    ('fb49cda7-e7d2-5f5c-8c58-d63e4ce9c25f'::uuid, '67eca403-e120-5bb8-8fb0-70a3381282e7'::uuid, 'Par quel moyen Ifemelu analyse-t-elle la race aux États-Unis ?', 'mcq', '["Un blog","Un journal intime","Un podcast","Des lettres à Obinze"]'::jsonb, 0, 'Son blog au titre ironique la fait connaître.', 8),
