    ('b9a3dea8-eb32-5744-8e42-de2dc2203e82'::uuid, '67eca403-e120-5bb8-8fb0-70a3381282e7'::uuid, 'À la fin, Ifemelu reste définitivement aux États-Unis.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle rentre à Lagos après treize ans et y retrouve Obinze.', 10),
    ('6a0987aa-dad7-544c-82b7-dda0e0fdf50a'::uuid, '67eca403-e120-5bb8-8fb0-70a3381282e7'::uuid, 'Comment traduire « to be undocumented » ?', 'mcq', '["Être sans papiers","Être mal informé","Être illettré","Être anonyme"]'::jsonb, 0, 'C’est la situation d’Obinze à Londres.', 11),
    ('efd6f171-2251-593b-ac74-e6bbea0aaf1a'::uuid, '67eca403-e120-5bb8-8fb0-70a3381282e7'::uuid, 'Quel sens donner à « belonging » ?', 'mcq', '["La possession","L’appartenance","Le bagage","La nostalgie"]'::jsonb, 1, 'Mot clé des œuvres sur la migration.', 12),
    ('28829173-0084-5cb7-a089-9c51f6b1843a'::uuid, 'a7d85167-2c69-5b18-b44a-49bf59ba3636'::uuid, 'Qui a écrit *The God of Small Things* (1997) ?', 'mcq', '["Salman Rushdie","Arundhati Roy","Kiran Desai","Jhumpa Lahiri"]'::jsonb, 1, 'C’est son premier roman, couronné par le prix Booker.', 1),
    ('79331605-7ccd-575c-b621-2697aca4bc8f'::uuid, 'a7d85167-2c69-5b18-b44a-49bf59ba3636'::uuid, 'Dans quel État de l’Inde se déroule le roman ?', 'mcq', '["Le Kerala","Le Bengale","Le Pendjab","Le Rajasthan"]'::jsonb, 0, 'À Ayemenem, dans une famille chrétienne syrienne.', 2),
    ('62c165b7-63c2-551e-94dc-f6f590d17169'::uuid, 'a7d85167-2c69-5b18-b44a-49bf59ba3636'::uuid, 'Qui est Velutha ?', 'mcq', '["Le père des jumeaux","Un policier","Un menuisier intouchable qu’Ammu aime","Le cousin anglais"]'::jsonb, 2, 'Il est le « dieu des petites choses ».', 3),
    ('103c1571-3155-5157-87e7-3fbeae9a9d41'::uuid, 'a7d85167-2c69-5b18-b44a-49bf59ba3636'::uuid, 'Que disent les « Love Laws » ?', 'mcq', '["Qui doit se marier avant trente ans","Comment célébrer un mariage","Qui peut hériter de la maison","Qui doit être aimé, comment, et combien"]'::jsonb, 3, 'Ammu et Velutha les enfreignent en s’aimant malgré la caste.', 4),
    ('448d47aa-8861-5c94-95eb-331bb8e70f99'::uuid, 'a7d85167-2c69-5b18-b44a-49bf59ba3636'::uuid, 'Comment s’appellent les jumeaux du roman ?', 'mcq', '["Estha et Rahel","Ifemelu et Obinze","Sophie et Ammu","Chacko et Baby"]'::jsonb, 0, 'Séparés après le drame, ils se retrouvent à trente et un ans.', 5),
    ('8349e346-4e85-5ec5-8ee4-1d2b51b8df9f'::uuid, 'a7d85167-2c69-5b18-b44a-49bf59ba3636'::uuid, 'Le roman suit un ordre strictement chronologique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il circule entre 1969 et 1993, par fragments.', 6),
    ('f7032e80-d74a-55ee-9c25-36810f2c3f5f'::uuid, 'a7d85167-2c69-5b18-b44a-49bf59ba3636'::uuid, 'Que devient Sophie Mol, la cousine anglaise ?', 'mcq', '["Elle épouse Chacko","Elle se noie","Elle rentre en Angleterre","Elle devient religieuse"]'::jsonb, 1, 'Sa noyade déclenche la catastrophe.', 7),
    ('3aa5e41f-14a6-5671-98ea-dbe843c59ddd'::uuid, 'a7d85167-2c69-5b18-b44a-49bf59ba3636'::uuid, 'En quelle année ont lieu l’indépendance de l’Inde et la Partition ?', 'mcq', '["1919","1965","1857","1947"]'::jsonb, 3, 'L’Inde et le Pakistan se séparent dans la violence.', 8),
    ('1bfa168d-d990-5963-a874-14f4d6c6c06c'::uuid, 'a7d85167-2c69-5b18-b44a-49bf59ba3636'::uuid, 'Quel roman de Salman Rushdie (1981) suit des enfants nés à l’heure de l’indépendance ?', 'mcq', '["*The Satanic Verses*","*Midnight’s Children*","*A Passage to India*","*Shame*"]'::jsonb, 1, 'Il a reçu le prix Booker.', 9),
    ('a60cc972-5999-5970-8a45-141aec0a7247'::uuid, 'a7d85167-2c69-5b18-b44a-49bf59ba3636'::uuid, 'Que désignent les « Small Things » du titre ?', 'mcq', '["Les objets de la fabrique","Les enfants seulement","Les gestes et moments intimes, face aux grandes forces de l’Histoire","Les petits villages du Kerala"]'::jsonb, 2, 'Les « Big Things » finissent par écraser les petites.', 10),
    ('2a6036cf-ca97-5f19-aed0-3926cad402ba'::uuid, 'a7d85167-2c69-5b18-b44a-49bf59ba3636'::uuid, 'Arundhati Roy réinvente la langue anglaise avec des mots coupés, collés ou lus à l’envers.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Un geste postcolonial : l’anglais de l’ancien colonisateur est réapproprié.', 11),
    ('4578c714-434c-57f2-ab42-5577b490d386'::uuid, 'a7d85167-2c69-5b18-b44a-49bf59ba3636'::uuid, 'Comment traduire « to transgress » ?', 'mcq', '["Transmettre","Transformer","Traverser un pont","Transgresser"]'::jsonb, 3, 'Franchir une limite interdite.', 12),
    ('a52c4a24-82ce-5dd5-9472-5f173ea3992b'::uuid, 'f7bfbdb5-d44f-59f4-9750-6ddfd13a14af'::uuid, 'Qui a écrit *The Caretaker* (1960) ?', 'mcq', '["Samuel Beckett","Tom Stoppard","John Osborne","Harold Pinter"]'::jsonb, 3, 'Dramaturge britannique, prix Nobel de littérature en 2005.', 1),
    ('ef6ec20a-2600-5515-ba6e-3459c5120c0c'::uuid, 'f7bfbdb5-d44f-59f4-9750-6ddfd13a14af'::uuid, 'Combien de personnages compte *The Caretaker* ?', 'mcq', '["Deux","Trois","Cinq","Sept"]'::jsonb, 1, 'Aston, Mick et Davies.', 2),
    ('ebd8b744-96cb-5ffc-8144-c8f35668c9d7'::uuid, 'f7bfbdb5-d44f-59f4-9750-6ddfd13a14af'::uuid, 'Quel faux nom Davies utilise-t-il ?', 'mcq', '["Bernard Jenkins","John Smith","Jim Farrell","Tom White"]'::jsonb, 0, 'Son identité reste impossible à vérifier.', 3),
    ('94c2a067-4dbb-5ea9-a48a-0d7ad85a74bc'::uuid, 'f7bfbdb5-d44f-59f4-9750-6ddfd13a14af'::uuid, 'Où Davies dit-il devoir aller chercher ses papiers ?', 'mcq', '["À Brighton","À Liverpool","À Sidcup","À Dublin"]'::jsonb, 2, 'Il n’y va jamais : l’identité qu’on ne prouve pas.', 4),
    ('7599c0e8-dbfc-55e7-af61-2365b9fdf715'::uuid, 'f7bfbdb5-d44f-59f4-9750-6ddfd13a14af'::uuid, 'Que rêve de construire Aston ?', 'mcq', '["Une maison de campagne","Un abri de jardin","Un bateau","Une boutique"]'::jsonb, 1, 'The shed : un projet qui ne se réalise jamais.', 5),
    ('061ae086-8f0a-558e-9e10-5071f862f8ef'::uuid, 'f7bfbdb5-d44f-59f4-9750-6ddfd13a14af'::uuid, 'Dans son monologue de la fin de l’acte II, Aston raconte les électrochocs qu’il a subis.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Un moment rare de confidence dans la pièce.', 6),
    ('d6ec8198-1e2d-556b-99e1-6021ceef228a'::uuid, 'f7bfbdb5-d44f-59f4-9750-6ddfd13a14af'::uuid, 'Que désigne l’expression « comedy of menace » ?', 'mcq', '["Une comédie musicale","Une tragédie en vers","Une farce sans enjeu","Une comédie où plane une menace diffuse"]'::jsonb, 3, 'L’expression est du critique Irving Wardle.', 7),
    ('cb446da7-14b9-5726-877b-27b24703663a'::uuid, 'f7bfbdb5-d44f-59f4-9750-6ddfd13a14af'::uuid, 'Comment se termine la pièce pour Davies ?', 'mcq', '["Il devient gardien de la maison","Il est chassé par les deux frères","Il part à Sidcup","Il épouse la voisine"]'::jsonb, 1, 'Il a voulu monter les frères l’un contre l’autre.', 8),
    ('076dd9b3-f230-5599-a091-a0a3b5ff5317'::uuid, 'f7bfbdb5-d44f-59f4-9750-6ddfd13a14af'::uuid, 'Chez Pinter, les pauses et silences sont indiqués par l’auteur et comptent autant que les répliques.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le non-dit pèse plus que ce qui est dit.', 9),
    ('b6e497fa-363f-5b64-a290-3bebb9743dd5'::uuid, 'f7bfbdb5-d44f-59f4-9750-6ddfd13a14af'::uuid, 'Que désigne l’adjectif « Pinteresque » ?', 'mcq', '["Un décor luxueux","Un climat de menace diffuse et de silences lourds","Un style poétique en vers","Un humour purement burlesque"]'::jsonb, 1, 'Le mot est entré dans la langue anglaise.', 10),
    ('c80418af-ae76-5d00-9635-2a6d6ed6b1dd'::uuid, 'f7bfbdb5-d44f-59f4-9750-6ddfd13a14af'::uuid, 'Qui est le propriétaire de la maison ?', 'mcq', '["Mick","Aston","Davies","Un voisin absent"]'::jsonb, 0, 'Le frère cadet, imprévisible et ironique.', 11),
    ('039f8cd4-575b-54e4-829f-178bdd32edc6'::uuid, 'f7bfbdb5-d44f-59f4-9750-6ddfd13a14af'::uuid, 'Que signifie « a power struggle » ?', 'mcq', '["Une coupure de courant","Une lutte des classes","Un rapport de force","Un effort physique"]'::jsonb, 2, 'Toute la pièce est un combat pour une place.', 12),
    ('8b610ddc-e629-55b8-a8e0-24e137dd5108'::uuid, '7290250c-1db0-55b5-926b-ff7677dbc78b'::uuid, 'Sur combien de points la synthèse est-elle notée à l’écrit de LLCER ?', 'mcq', '["10","12","16","20"]'::jsonb, 2, 'La traduction ou transposition vaut les 4 points restants.', 1),
    ('a6dd5e20-9aaa-5715-bdf4-d3b5ea917ad0'::uuid, '7290250c-1db0-55b5-926b-ff7677dbc78b'::uuid, 'Quelle longueur vise la synthèse ?', 'mcq', '["Environ 150 mots","Environ 500 mots","Environ 1 000 mots","Au moins 2 pages"]'::jsonb, 1, 'Il faut rester dans ces bornes : c’est aussi une compétence évaluée.', 2),
    ('e69b7a9b-acf1-54ef-a8e1-d4c4fd9761cf'::uuid, '7290250c-1db0-55b5-926b-ff7677dbc78b'::uuid, 'Combien de temps dure l’épreuve écrite de LLCER en terminale ?', 'mcq', '["3 h 30","2 heures","4 heures","1 h 30"]'::jsonb, 0, 'Synthèse et traduction/transposition dans le même temps.', 3),
    ('aaabef3d-cdbc-55b5-b0c8-368c5bc5d0a5'::uuid, '7290250c-1db0-55b5-926b-ff7677dbc78b'::uuid, 'Une bonne synthèse présente les documents l’un après l’autre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle les croise : chaque paragraphe fait dialoguer plusieurs documents.', 4),
    ('b9e014d0-9514-5aa7-9fc4-b4b7c5d161ad'::uuid, '7290250c-1db0-55b5-926b-ff7677dbc78b'::uuid, 'Que faut-il lire en premier ?', 'mcq', '["Le document le plus long","Le document iconographique","Les sources","Les consignes"]'::jsonb, 3, 'Elles disent ce qu’il faut chercher dans le dossier.', 5),
    ('df0f2526-3bea-50ca-9ed6-f035e5afb7e5'::uuid, '7290250c-1db0-55b5-926b-ff7677dbc78b'::uuid, 'Combien de documents compte généralement le dossier ?', 'mcq', '["Trois ou quatre","Un seul","Six à huit","Dix"]'::jsonb, 0, 'Textes littéraires, articles, parfois une image.', 6),
    ('dd151d58-75ed-5257-b2d1-93bbb62dae66'::uuid, '7290250c-1db0-55b5-926b-ff7677dbc78b'::uuid, 'Quel connecteur exprime une concession ?', 'mcq', '["Therefore","Moreover","Although","Similarly"]'::jsonb, 2, 'Although : bien que.', 7),
    ('805dffde-baf9-5b2f-aa23-33f1ec67e7f6'::uuid, '7290250c-1db0-55b5-926b-ff7677dbc78b'::uuid, 'Quel connecteur sert à comparer deux documents semblables ?', 'mcq', '["However","Likewise","Thus","Whereas"]'::jsonb, 1, 'Likewise : de même.', 8),
    ('5a3187fe-0e61-55fc-909d-0fea4b470d50'::uuid, '7290250c-1db0-55b5-926b-ff7677dbc78b'::uuid, 'Dans une synthèse, il faut citer brièvement et indiquer la source du document.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Doc. A, doc. B… : le correcteur doit voir les liens.', 9),
    ('308914e9-fea4-54c3-90ef-254d5d17a06e'::uuid, '7290250c-1db0-55b5-926b-ff7677dbc78b'::uuid, 'Que signifie « to shed light on » ?', 'mcq', '["Éteindre","Éclairer, mettre en lumière","Cacher","Contredire"]'::jsonb, 1, 'Très utile pour montrer qu’un document en éclaire un autre.', 10),
    ('30849f65-d395-5b35-99df-2fb64ffd775c'::uuid, '7290250c-1db0-55b5-926b-ff7677dbc78b'::uuid, 'Quel est le rôle de l’introduction d’une synthèse ?', 'mcq', '["Donner son avis personnel","Résumer le premier document","Réciter le cours","Présenter le dossier et sa problématique"]'::jsonb, 3, 'Elle annonce l’enjeu commun aux documents.', 11),
    ('d3f1e165-02ad-5fb6-9946-b92cd1ef6f9e'::uuid, '7290250c-1db0-55b5-926b-ff7677dbc78b'::uuid, 'Quelle erreur coûte le plus cher ?', 'mcq', '["Utiliser « moreover »","Oublier de répondre à une consigne","Écrire une conclusion courte","Citer un document entre guillemets"]'::jsonb, 1, 'La synthèse est guidée par les consignes : en oublier une la rend incomplète.', 12),
    ('2badfc30-99a3-5b4a-afb1-fdb54d14a255'::uuid, '9722b4f3-bd9f-5b46-a52d-91e511de259f'::uuid, 'Combien de points vaut la traduction ou transposition ?', 'mcq', '["2","4","8","16"]'::jsonb, 1, 'La synthèse vaut les 16 autres points.', 1),
    ('18b04fd6-d7e6-5489-a0a9-9c405a857767'::uuid, '9722b4f3-bd9f-5b46-a52d-91e511de259f'::uuid, 'Dans quelle langue rédige-t-on la traduction ou la transposition ?', 'mcq', '["En français","En anglais","Au choix","Dans les deux langues"]'::jsonb, 0, 'On passe de l’anglais au français.', 2),
    ('6c2189fd-ef93-54e0-82f5-f04d4d409163'::uuid, '9722b4f3-bd9f-5b46-a52d-91e511de259f'::uuid, 'Comment traduire « I have lived here for ten years » ?', 'mcq', '["J’ai vécu ici pendant dix ans","Je vivrai ici dix ans","J’habite ici depuis dix ans","J’avais habité ici dix ans"]'::jsonb, 2, 'Le present perfect + for exprime une durée qui continue : présent en français.', 3),
    ('83c80dd7-c1cb-5602-9f06-2980b571cc88'::uuid, '9722b4f3-bd9f-5b46-a52d-91e511de259f'::uuid, 'Que signifie « actually » ?', 'mcq', '["Actuellement","Activement","Exactement","En fait"]'::jsonb, 3, 'Actuellement se dit « currently ».', 4),
    ('abf5f74d-b64a-5caf-9f8f-09ec7d4c9d61'::uuid, '9722b4f3-bd9f-5b46-a52d-91e511de259f'::uuid, 'Que signifie « eventually » ?', 'mcq', '["Éventuellement","Finalement","Évidemment","Occasionnellement"]'::jsonb, 1, 'Éventuellement se dit « possibly ».', 5),
    ('c0305b5a-b4e1-50a3-9533-3df9a5d61491'::uuid, '9722b4f3-bd9f-5b46-a52d-91e511de259f'::uuid, 'Comment traduire « He swam across the river » ?', 'mcq', '["Il traversa la rivière à la nage","Il nagea à travers la rivière","Il nageait la rivière","Il nagea contre la rivière"]'::jsonb, 0, 'Chassé-croisé : le mouvement passe dans le verbe français.', 6),
    ('bb2ff424-aa26-5e2e-b6b0-bcc488a565a7'::uuid, '9722b4f3-bd9f-5b46-a52d-91e511de259f'::uuid, 'Une transposition consiste à traduire le texte mot à mot.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle rend compte des idées principales, avec ses propres mots.', 7),
    ('8e2569bd-1560-5b10-b6b0-b77f095ac035'::uuid, '9722b4f3-bd9f-5b46-a52d-91e511de259f'::uuid, 'Quelle longueur fait environ le passage à traduire ?', 'mcq', '["50 signes","5 000 signes","500 signes","2 pages"]'::jsonb, 2, 'Un passage court, qui demande de la précision.', 8),
    ('518ec76e-3d2f-51a5-bc31-f00b57992d40'::uuid, '9722b4f3-bd9f-5b46-a52d-91e511de259f'::uuid, 'Dans un récit littéraire, le prétérit anglais se traduit souvent par…', 'mcq', '["Le futur","Le passé simple ou l’imparfait","Le présent uniquement","Le conditionnel"]'::jsonb, 1, 'Le passé composé partout alourdit un texte littéraire.', 9),
    ('b4102b91-b9af-531a-958e-75a23efa6c0a'::uuid, '9722b4f3-bd9f-5b46-a52d-91e511de259f'::uuid, '« Library » signifie « librairie ».', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Library = bibliothèque ; librairie = bookshop.', 10),
    ('2345f0e6-9c83-57f3-8895-52c9596ef3c4'::uuid, '9722b4f3-bd9f-5b46-a52d-91e511de259f'::uuid, 'Que signifie « to pretend » ?', 'mcq', '["Prétendre","Présenter","Préférer","Faire semblant"]'::jsonb, 3, 'Prétendre (affirmer) se dit « to claim ».', 11),
    ('633883c3-126a-538b-9c54-9983ebcd9997'::uuid, '9722b4f3-bd9f-5b46-a52d-91e511de259f'::uuid, 'Quelle est la dernière étape d’une bonne traduction ?', 'mcq', '["Relire le français seul, pour qu’il sonne juste","Relire l’anglais","Compter les mots","Ajouter des explications"]'::jsonb, 0, 'La traduction doit se lire comme un texte français.', 12),
    ('5022dc0e-7e9d-5c7a-8b71-149946706acc'::uuid, '53efd0f9-d6b8-5260-aaeb-e2dfee3a7e90'::uuid, 'Combien de temps dure l’oral de LLCER en terminale ?', 'mcq', '["10 minutes","30 minutes","45 minutes","20 minutes"]'::jsonb, 3, '10 minutes de présentation au plus, puis un échange.', 1),
    ('004c2f28-96ec-5149-89f2-e3ddba490df7'::uuid, '53efd0f9-d6b8-5260-aaeb-e2dfee3a7e90'::uuid, 'Dispose-t-on d’un temps de préparation avant l’oral ?', 'mcq', '["Oui, 30 minutes","Non, aucun","Oui, 1 heure","Oui, 10 minutes"]'::jsonb, 1, 'On s’appuie sur le dossier préparé pendant l’année.', 2),
    ('32bfe42a-a50d-58a5-abf7-4265bdb42ec1'::uuid, '53efd0f9-d6b8-5260-aaeb-e2dfee3a7e90'::uuid, 'Combien de documents au moins compte le dossier personnel en LLCER anglais ?', 'mcq', '["Quatre","Deux","Dix","Un"]'::jsonb, 0, 'Quatre à six, dont au moins un extrait d’une œuvre intégrale.', 3),
    ('006e48d2-5c95-5175-846c-c08a63a387a9'::uuid, '53efd0f9-d6b8-5260-aaeb-e2dfee3a7e90'::uuid, 'Combien d’œuvres d’art visuel au plus le dossier peut-il contenir ?', 'mcq', '["Aucune","Une","Quatre","Deux"]'::jsonb, 3, 'Tableau, affiche, extrait de film, photographie…', 4),
    ('aa1590aa-8361-58d2-a072-28bb1e67d6bc'::uuid, '53efd0f9-d6b8-5260-aaeb-e2dfee3a7e90'::uuid, 'Combien d’œuvres intégrales la classe étudie-t-elle en terminale ?', 'mcq', '["Une","Trois","Six","Douze"]'::jsonb, 1, 'Deux littéraires et une filmique, une par thématique.', 5),
    ('2d791041-5f16-5fbd-be00-b05717e579ea'::uuid, '53efd0f9-d6b8-5260-aaeb-e2dfee3a7e90'::uuid, 'Laquelle de ces œuvres est au programme limitatif 2026-2028 ?', 'mcq', '["*The Great Gatsby*","*Jane Eyre*","*Brooklyn*","*1984*"]'::jsonb, 2, 'Le roman de Colm Tóibín (2009) figure parmi les huit œuvres littéraires.', 6),
