    ('fa54810c-1c62-57df-815f-4b900c9b8785'::uuid, 'fb5ad615-a798-53f9-9f59-85d44fd5996c'::uuid, 'Sur les instruments d’époque, les cordes sont en…', 'mcq', '["Métal","Nylon","Soie","Boyau"]'::jsonb, 3, 'Un son plus doux et plus grainé.', 4),
    ('5290804c-2e7f-533f-9ab3-2856f9050c55'::uuid, 'fb5ad615-a798-53f9-9f59-85d44fd5996c'::uuid, 'L’interprétation historiquement informée garantit de jouer exactement comme en 1753.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est une quête et un choix artistique : on ne connaît pas tout des pratiques anciennes.', 5),
    ('b8287bba-dfd0-589a-9a7e-6dcba1ac3901'::uuid, 'fb5ad615-a798-53f9-9f59-85d44fd5996c'::uuid, 'Qu’est-ce qu’un arrangement ?', 'mcq', '["La réécriture de l’accompagnement, de l’effectif ou de l’harmonie d’une œuvre","Un contrat entre éditeur et auteur","Le classement des pistes d’un album","Une œuvre entièrement nouvelle"]'::jsonb, 0, 'Russell Garcia arrange Gershwin pour le disque de 1958.', 6),
    ('431c6477-56be-5a1d-a984-f6d47b1bb472'::uuid, 'fb5ad615-a798-53f9-9f59-85d44fd5996c'::uuid, 'Qu’est-ce qu’un pastiche ?', 'mcq', '["Une copie illégale","Une œuvre composée « à la manière de »","Un enregistrement public","Une œuvre inachevée"]'::jsonb, 1, 'Un exercice fréquent de création au lycée.', 7),
    ('6e518e9d-1edc-591e-8feb-87a214943bee'::uuid, 'fb5ad615-a798-53f9-9f59-85d44fd5996c'::uuid, 'Adapter une œuvre à d’autres instruments, c’est faire une…', 'mcq', '["Modulation","Improvisation","Transcription","Cadence"]'::jsonb, 2, 'Le Wq 172 existe pour violoncelle, flûte et clavecin.', 8),
    ('57b40eea-9742-5f89-b650-9cdea247333a'::uuid, 'fb5ad615-a798-53f9-9f59-85d44fd5996c'::uuid, 'Qui fonde le Concentus Musicus de Vienne en 1953 ?', 'mcq', '["Nikolaus Harnoncourt","Herbert von Karajan","William Christie","Jordi Savall"]'::jsonb, 0, 'Un pionnier des instruments d’époque.', 9),
    ('1ca85889-e8a4-5785-a6a0-bbd418f29eba'::uuid, 'fb5ad615-a798-53f9-9f59-85d44fd5996c'::uuid, 'Quel paramètre change généralement le plus d’une version à une autre ?', 'mcq', '["Le texte","La forme","La mélodie","Le timbre et le style"]'::jsonb, 3, 'La mélodie et la forme permettent de reconnaître l’œuvre.', 10),
    ('c27636b9-f998-5b2c-8a3d-e47c8aa0390c'::uuid, 'fb5ad615-a798-53f9-9f59-85d44fd5996c'::uuid, 'Les héritiers des Gershwin ont exigé que *Porgy and Bess* soit chanté par des interprètes noirs.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Une exigence liée à l’identité même de l’œuvre.', 11),
    ('faf6353d-bc98-524f-a270-d3382008fdc7'::uuid, 'fb5ad615-a798-53f9-9f59-85d44fd5996c'::uuid, 'Face à deux versions d’une œuvre, quelle attitude est attendue ?', 'mcq', '["Désigner la meilleure","Comparer et interpréter chaque projet artistique, sans hiérarchiser","Préférer toujours la plus ancienne","Préférer toujours la plus célèbre"]'::jsonb, 1, 'Chaque version éclaire l’œuvre autrement.', 12),
    ('fd53d7c7-f65a-59cf-857b-c4d8114587f9'::uuid, '1a30edd7-dab4-5902-a42d-e4d752e57956'::uuid, 'De quel territoire le maloya est-il originaire ?', 'mcq', '["La Martinique","La Réunion","Tahiti","La Guyane"]'::jsonb, 1, 'Chants des esclaves et engagés venus d’Afrique et de Madagascar.', 1),
    ('ca0d7f77-ff05-5640-a07a-fe21fbbc60ae'::uuid, '1a30edd7-dab4-5902-a42d-e4d752e57956'::uuid, 'En quelle année le maloya est-il inscrit au patrimoine immatériel de l’UNESCO ?', 'mcq', '["2014","1994","2009","2020"]'::jsonb, 2, 'Le gwoka de Guadeloupe l’a été en 2014.', 2),
    ('856f7c6d-9fde-557c-a70d-6756b9568f40'::uuid, '1a30edd7-dab4-5902-a42d-e4d752e57956'::uuid, 'Qu’est-ce qu’un chant responsorial ?', 'mcq', '["Un soliste chante, un chœur lui répond","Tous chantent à l’unisson","Une voix seule sans accompagnement","Deux chœurs en canon"]'::jsonb, 0, 'C’est la forme du maloya, du bèlè ou du gwoka.', 3),
    ('5bd32d36-e590-5d48-81cd-1c4905b2a85e'::uuid, '1a30edd7-dab4-5902-a42d-e4d752e57956'::uuid, 'Qu’est-ce que le kayamb ?', 'mcq', '["Un tambour sur cadre","Une flûte en bambou","Une guitare à quatre cordes","Un hochet en radeau de tiges rempli de graines"]'::jsonb, 3, 'Instrument emblématique du maloya.', 4),
    ('81aaaee5-6133-5e9c-a182-6012544b6789'::uuid, '1a30edd7-dab4-5902-a42d-e4d752e57956'::uuid, 'Les himene de Polynésie sont nés de la rencontre des chants polynésiens et des cantiques protestants.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Apportés par les missionnaires au XIXe siècle.', 5),
    ('8b4e7d00-c827-58fd-a418-8c9648c42b28'::uuid, '1a30edd7-dab4-5902-a42d-e4d752e57956'::uuid, 'Quel artiste réunionnais interprète *Laviyon* (1994) ?', 'mcq', '["Admiral T","Eugène Mona","Danyel Waro","Kassav’"]'::jsonb, 2, 'Une grande voix du maloya.', 6),
    ('d02ab521-62c6-5d02-9ce5-946caf296994'::uuid, '1a30edd7-dab4-5902-a42d-e4d752e57956'::uuid, 'Quelle œuvre antillaise de 1978 figure au corpus de l’option ?', 'mcq', '["*Ti Milo* d’Eugène Mona","*Zouk la sé sèl médikaman nou ni*","*Haka Enana*","*Rest’ là Maloya*"]'::jsonb, 0, 'Reprise par Admiral T en 2011.', 7),
    ('ad72e8f7-22f2-5d30-accb-db106277ad9c'::uuid, '1a30edd7-dab4-5902-a42d-e4d752e57956'::uuid, 'Que désigne le « métissage » musical ?', 'mcq', '["La disparition des musiques locales","L’interdiction d’un genre","La rencontre de musiques qui crée des esthétiques nouvelles","Une musique jouée à l’unisson"]'::jsonb, 2, 'Par exemple le maloya électrique.', 8),
    ('f00370bd-03ad-538b-b371-99cbf35f0496'::uuid, '1a30edd7-dab4-5902-a42d-e4d752e57956'::uuid, 'Qu’étudie l’ethnomusicologie ?', 'mcq', '["L’acoustique des salles","Les musiques dans leur culture et selon leurs propres règles","Le droit des musiciens","La lutherie"]'::jsonb, 1, 'Elle évite de juger une musique avec des critères qui ne sont pas les siens.', 9),
    ('38176330-2d98-5983-bcb8-ef756e223a72'::uuid, '1a30edd7-dab4-5902-a42d-e4d752e57956'::uuid, 'Le maloya a toujours été encouragé par les autorités.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il a longtemps été interdit ou méprisé.', 10),
    ('149aa2a2-2aef-563f-8be5-4be757eadac1'::uuid, '1a30edd7-dab4-5902-a42d-e4d752e57956'::uuid, 'Quelle question relie les paires d’œuvres du corpus de l’option ?', 'mcq', '["Le prix des disques","La virtuosité instrumentale","Ancrage historique et présence contemporaine","La musique de film"]'::jsonb, 2, 'Une forme traditionnelle face à sa recréation.', 11),
    ('9222c4cc-307d-55a4-ad3c-66773ec927de'::uuid, '1a30edd7-dab4-5902-a42d-e4d752e57956'::uuid, 'Dans les himene, certaines voix tiennent une note grave prolongée appelée…', 'mcq', '["Un ostinato","Un riff","Une syncope","Un bourdon"]'::jsonb, 3, 'Les voix aiguës s’y ornent au-dessus.', 12),
    ('073017b4-9bfe-5783-9635-6600cc2c52db'::uuid, 'c099b54d-e656-5aed-88d7-e80dfa1aacde'::uuid, 'Combien de temps dure la partie écrite de l’épreuve de spécialité musique ?', 'mcq', '["2 heures","3 h 30","4 heures","1 h 30"]'::jsonb, 1, 'Elle comprend trois exercices indépendants.', 1),
    ('67564080-4bb2-510e-a1da-9acc171829bb'::uuid, 'c099b54d-e656-5aed-88d7-e80dfa1aacde'::uuid, 'Combien d’exercices compte l’écrit ?', 'mcq', '["Deux","Quatre","Trois","Un seul"]'::jsonb, 2, 'Description, commentaire comparé, commentaire de documents.', 2),
    ('82491f92-5582-58cd-8d79-6d10941a3b28'::uuid, 'c099b54d-e656-5aed-88d7-e80dfa1aacde'::uuid, 'Sur quoi porte le premier exercice ?', 'mcq', '["La description d’un bref extrait hors programme, identifié par le sujet","Une dissertation","Un commentaire de partition sans écoute","Une question de cours"]'::jsonb, 0, 'On attend une description objective du langage musical.', 3),
    ('1820cea0-ebad-5490-9c67-5f47f4ce016e'::uuid, 'c099b54d-e656-5aed-88d7-e80dfa1aacde'::uuid, 'Dans le commentaire comparé, l’un des deux extraits vient du programme limitatif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’autre est hors programme et accompagné de sa partition.', 4),
    ('81dfe373-5905-526c-85eb-f440e08c4ff4'::uuid, 'c099b54d-e656-5aed-88d7-e80dfa1aacde'::uuid, 'Quel exercice est le plus long ?', 'mcq', '["La description","Le commentaire de documents","Ils ont tous la même durée","Le commentaire comparé"]'::jsonb, 3, 'Entre 1 h 45 et 2 h 15.', 5),
    ('9dfde064-a725-59c3-89ac-bd0ed6427b7d'::uuid, 'c099b54d-e656-5aed-88d7-e80dfa1aacde'::uuid, 'À quoi doit servir la partition dans le commentaire comparé ?', 'mcq', '["À remplacer l’écoute","À confirmer et approfondir ce qu’on a entendu","À recopier des mesures entières","À deviner le compositeur"]'::jsonb, 1, 'On n’attend pas un lecteur chevronné, mais un usage ciblé.', 6),
    ('6d535f57-916a-5852-857b-efabf4c08016'::uuid, 'c099b54d-e656-5aed-88d7-e80dfa1aacde'::uuid, 'Sur quoi portent les documents du troisième exercice ?', 'mcq', '["L’histoire du Moyen Âge","La biographie d’un compositeur","La vie musicale contemporaine","La théorie de l’harmonie"]'::jsonb, 2, 'Articles, interviews, études de sociologie ou d’économie.', 7),
    ('5c98566b-207d-5f11-94cb-a908d8fbd19e'::uuid, 'c099b54d-e656-5aed-88d7-e80dfa1aacde'::uuid, 'Le troisième exercice doit être relié à au moins un champ de questionnement du programme.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est une attente explicite de l’épreuve.', 8),
    ('fe5c4c7b-0a1e-541a-897c-76048c156f7d'::uuid, 'c099b54d-e656-5aed-88d7-e80dfa1aacde'::uuid, 'Comment organiser un commentaire comparé ?', 'mcq', '["Un extrait puis l’autre","Par parties thématiques où les deux extraits sont comparés","Par ordre chronologique d’écoute seulement","En une seule liste de remarques"]'::jsonb, 1, 'Ressemblances et différences à l’intérieur de chaque partie.', 9),
    ('d9f4cd12-b043-5ed8-ab35-ecfb425be508'::uuid, 'c099b54d-e656-5aed-88d7-e80dfa1aacde'::uuid, 'Quelle part de la note globale représente l’écrit ?', 'mcq', '["Un quart","Les trois quarts","La totalité","La moitié"]'::jsonb, 3, 'L’oral compte pour l’autre moitié.', 10),
    ('3ba24aac-b999-58e5-8141-c1cce92f4321'::uuid, 'c099b54d-e656-5aed-88d7-e80dfa1aacde'::uuid, 'Dans l’exercice 1, on peut s’appuyer sur un musicogramme.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Et ajouter de brefs relevés sur portée.', 11),
    ('fcdcc4a8-2f26-57b6-a85e-1188d2f91dcd'::uuid, 'c099b54d-e656-5aed-88d7-e80dfa1aacde'::uuid, 'Quelle est l’erreur classique de l’exercice de description ?', 'mcq', '["Utiliser un vocabulaire technique","Minuter les événements","Donner des impressions sans les appuyer sur des faits musicaux","Faire un schéma"]'::jsonb, 2, 'Une impression ne vaut que si on dit ce qui la produit.', 12),
    ('39c088a8-e27a-5107-875f-331e975ae395'::uuid, '5c626154-826e-5aae-ad03-de4142ff0962'::uuid, 'Combien de temps dure la partie orale de l’épreuve de spécialité musique ?', 'mcq', '["30 minutes","20 minutes","1 heure","15 minutes"]'::jsonb, 0, 'Sans temps de préparation.', 1),
    ('17955e9a-f0fa-5a84-aab4-582d24c9d572'::uuid, '5c626154-826e-5aae-ad03-de4142ff0962'::uuid, 'Que présente le candidat pendant l’oral ?', 'mcq', '["Un morceau imposé par le jury","Une création collective élaborée pendant l’année de terminale","Un exposé sans musique","Un enregistrement réalisé chez lui"]'::jsonb, 1, 'Il l’interprète, puis expose sa démarche.', 2),
    ('8c7b0fe6-bf74-5527-8832-7679a5920737'::uuid, '5c626154-826e-5aae-ad03-de4142ff0962'::uuid, 'Un accompagnement enregistré est-il autorisé ?', 'mcq', '["Oui, sans limite","Oui, pour les instruments absents","Oui, s’il est fait en studio","Non, aucun"]'::jsonb, 3, 'Seuls des élèves du lycée peuvent accompagner le candidat.', 3),
    ('10f4f9a1-b74c-597e-9b57-00509dd93317'::uuid, '5c626154-826e-5aae-ad03-de4142ff0962'::uuid, 'Combien d’élèves au plus sont conseillés dans le groupe, candidat compris ?', 'mcq', '["Deux","Dix","Cinq","Toute la classe"]'::jsonb, 2, 'Pour que le rôle du candidat reste visible.', 4),
    ('b3cb626e-59b7-54f1-81cc-f9602e5958c2'::uuid, '5c626154-826e-5aae-ad03-de4142ff0962'::uuid, 'La représentation graphique remise au jury est évaluée.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle sert de support à l’entretien, elle n’est pas notée.', 5),
    ('f22c3397-1680-5dd3-9d80-cf0bd25ef749'::uuid, '5c626154-826e-5aae-ad03-de4142ff0962'::uuid, 'L’exposé doit établir un lien avec au moins une œuvre du programme limitatif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Et avec au moins un champ de questionnement.', 6),
    ('99516bd1-0f84-5264-a87c-9ced324f7380'::uuid, '5c626154-826e-5aae-ad03-de4142ff0962'::uuid, 'Quelle longueur maximale a le document de synthèse ?', 'mcq', '["Une page","Deux pages","Cinq pages","Dix pages"]'::jsonb, 1, 'Sur papier, visé par le professeur et le chef d’établissement.', 7),
    ('c5a60405-99ef-5b73-a161-53b7ce6bea2d'::uuid, '5c626154-826e-5aae-ad03-de4142ff0962'::uuid, 'Quand le document de synthèse est-il transmis au jury ?', 'mcq', '["Le jour même","Après l’épreuve","Quinze jours avant l’épreuve","Un an avant"]'::jsonb, 2, 'Le jury peut ainsi préparer l’entretien.', 8),
    ('95fbdccd-5f84-5e9e-affb-9a6cf18f34f0'::uuid, '5c626154-826e-5aae-ad03-de4142ff0962'::uuid, 'Si l’interprétation est collective, l’entretien l’est aussi.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'L’exposé et l’entretien sont toujours individuels.', 9),
    ('641dd522-82eb-5122-a57e-a0f5dec527b3'::uuid, '5c626154-826e-5aae-ad03-de4142ff0962'::uuid, 'Combien de temps au plus durent l’interprétation et l’exposé ensemble ?', 'mcq', '["5 minutes","30 minutes","25 minutes","15 minutes"]'::jsonb, 3, 'L’entretien occupe le temps restant.', 10),
    ('b29d1078-3cda-5600-bc3b-b01c5ae880e7'::uuid, '5c626154-826e-5aae-ad03-de4142ff0962'::uuid, 'Quelle est en terminale la « quatrième thématique » ?', 'mcq', '["Une thématique choisie par l’élève en lien avec son autre spécialité, travaillée en projet","Une thématique imposée par le ministère","La thématique de l’option","Une thématique réservée au grand oral de philosophie"]'::jsonb, 0, 'Elle peut nourrir une question du grand oral.', 11),
    ('934d3f6d-8337-572d-b9e4-84173be71eb4'::uuid, '5c626154-826e-5aae-ad03-de4142ff0962'::uuid, 'Que juge avant tout l’oral ?', 'mcq', '["La conformité exacte à la partition","Le nombre de musiciens","La compréhension par le candidat de ce qu’il a créé","La durée de la pièce"]'::jsonb, 2, 'La musique vivante peut s’éloigner de la partition.', 12),
    ('26c1bb1f-4f59-5dad-819b-6b3374217b47'::uuid, '45572fc7-5024-5ed0-9035-29b65e19fe61'::uuid, 'Dans un mouvement de translation, les points du solide…', 'mcq', '["Ont une vitesse qui dépend de leur distance à l’axe","Ont tous la même vitesse","Décrivent tous un cercle","Sont immobiles les uns par rapport au sol"]'::jsonb, 1, 'C’est la définition même de la translation : le solide se déplace sans tourner.', 1),
    ('92a12927-9710-5fef-a7eb-1e25bf2c7dde'::uuid, '45572fc7-5024-5ed0-9035-29b65e19fe61'::uuid, 'Un moteur tourne à 3 000 tr/min. Quelle est sa vitesse angulaire ?', 'mcq', '["50 rad/s","157 rad/s","314 rad/s","3 000 rad/s"]'::jsonb, 2, 'ω = 2π × 3 000 / 60 = 100π, soit environ 314 rad/s.', 2),
    ('7feb2a11-e3d5-5397-aee1-88a87e46d324'::uuid, '45572fc7-5024-5ed0-9035-29b65e19fe61'::uuid, 'Quelle relation lie la vitesse d’un point à la vitesse de rotation ?', 'mcq', '["v = ω / R","v = ω × R","v = ω + R","v = ω × R²"]'::jsonb, 1, 'Un point deux fois plus loin de l’axe va deux fois plus vite.', 3),
    ('a7c4a726-7de7-594c-9850-999a872c2053'::uuid, '45572fc7-5024-5ed0-9035-29b65e19fe61'::uuid, 'Sur un solide en rotation, tous les points ont la même vitesse.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Leur vitesse est proportionnelle à leur distance à l’axe : v = ω × R.', 4),
    ('b2dd2645-bbb1-5ec8-b659-ea6054497e80'::uuid, '45572fc7-5024-5ed0-9035-29b65e19fe61'::uuid, 'Comment obtient-on la distance parcourue à partir de la courbe v(t) ?', 'mcq', '["En lisant la pente de la courbe","En prenant la valeur maximale","En calculant l’aire sous la courbe","En divisant la vitesse par le temps"]'::jsonb, 2, 'La pente donne l’accélération ; l’aire donne la distance.', 5),
    ('86a5dcaa-c66a-56c7-aca1-e9661f50bf5c'::uuid, '45572fc7-5024-5ed0-9035-29b65e19fe61'::uuid, 'Un chariot passe de 0 à 3 m/s en 1,5 s. Son accélération vaut…', 'mcq', '["0,5 m/s²","4,5 m/s²","1,5 m/s²","2 m/s²"]'::jsonb, 3, 'a = Δv / Δt = 3 / 1,5 = 2 m/s².', 6),
    ('a7220eda-61b2-5523-aaf1-0db43e1fe4b4'::uuid, '45572fc7-5024-5ed0-9035-29b65e19fe61'::uuid, 'Quelle forme a la courbe de vitesse d’un axe qui accélère, roule, puis freine ?', 'mcq', '["Un trapèze","Une droite horizontale","Une parabole","Une sinusoïde"]'::jsonb, 0, 'Montée, palier, descente : c’est le profil le plus courant en automatisme.', 7),
    ('084a6817-1746-5a15-a18b-b7766b0ec000'::uuid, '45572fc7-5024-5ed0-9035-29b65e19fe61'::uuid, 'Dans un mouvement uniformément accéléré partant du repos, la position varie…', 'mcq', '["Linéairement avec le temps","Comme le carré du temps","Comme la racine du temps","Pas du tout"]'::jsonb, 1, 'x(t) = ½ a t² : en doublant la durée, on quadruple la distance.', 8),
    ('405f0d3c-e63c-5044-8317-b62ef28063e6'::uuid, '45572fc7-5024-5ed0-9035-29b65e19fe61'::uuid, 'Une roue de rayon 0,3 m tourne à 10 rad/s. Quelle est la vitesse d’un point de sa périphérie ?', 'mcq', '["3 m/s","33 m/s","0,03 m/s","10,3 m/s"]'::jsonb, 0, 'v = ω × R = 10 × 0,3 = 3 m/s.', 9),
    ('eed32999-73b7-50ce-8ab9-54b119d83c8b'::uuid, '45572fc7-5024-5ed0-9035-29b65e19fe61'::uuid, 'Combien de radians correspondent à 5 tours complets ?', 'mcq', '["5 rad","5π rad","10π rad","360 rad"]'::jsonb, 2, 'Un tour vaut 2π rad, donc 5 tours valent 10π rad.', 10),
    ('4f027b1b-34bf-5d13-96ed-e964fc5022a9'::uuid, '45572fc7-5024-5ed0-9035-29b65e19fe61'::uuid, 'Pendant le palier d’un profil en trapèze, l’accélération est…', 'mcq', '["Maximale","Négative","Égale à la vitesse","Nulle"]'::jsonb, 3, 'La vitesse est constante : sa variation, donc l’accélération, est nulle.', 11),
    ('2846761c-ab9c-57da-ba06-a144be1411ab'::uuid, '45572fc7-5024-5ed0-9035-29b65e19fe61'::uuid, 'L’accélération angulaire s’exprime en rad/s².', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est la variation de ω (rad/s) par seconde.', 12),
    ('8a9e6964-a8ee-5df6-912d-eca527059cc3'::uuid, 'aafe1c5a-50cc-5978-aea7-aae50a396df8'::uuid, 'Comment s’écrit le principe fondamental de la dynamique en translation ?', 'mcq', '["Somme des forces = m × v","Somme des forces = m × a","Somme des forces = 0","Somme des forces = J × α"]'::jsonb, 1, 'La force produit une accélération, pas une vitesse.', 1),
    ('3ed28e89-c606-582d-afc4-c7b324d3efa8'::uuid, 'aafe1c5a-50cc-5978-aea7-aae50a396df8'::uuid, 'En rotation autour d’un axe fixe, la somme des moments vaut…', 'mcq', '["m × a","J × ω","J × α","m × g"]'::jsonb, 2, 'J est le moment d’inertie et α l’accélération angulaire.', 2),
    ('a505330f-deb1-5924-91da-cc7f006a9674'::uuid, 'aafe1c5a-50cc-5978-aea7-aae50a396df8'::uuid, 'Quand l’accélération est nulle, le principe fondamental de la dynamique devient…', 'mcq', '["Le principe fondamental de la statique","La loi d’Ohm","Le théorème de l’énergie cinétique","La loi des nœuds"]'::jsonb, 0, 'Avec a = 0, il reste « somme des forces = 0 » : c’est la statique.', 3),
    ('73c4fc58-f621-5e67-ad3f-6d5cb2f8874b'::uuid, 'aafe1c5a-50cc-5978-aea7-aae50a396df8'::uuid, 'Quelle est la première étape de la méthode ?', 'mcq', '["Projeter sur un axe","Calculer l’accélération","Choisir un moteur","Isoler le solide étudié"]'::jsonb, 3, 'Sans système isolé, on ne sait pas quelles actions sont extérieures.', 4),
    ('97ecfdba-f374-53df-9fa5-d791e5522a28'::uuid, 'aafe1c5a-50cc-5978-aea7-aae50a396df8'::uuid, 'Une masse de 50 kg accélère à 2 m/s² sur un sol sans frottement. Quelle force faut-il ?', 'mcq', '["25 N","100 N","52 N","490 N"]'::jsonb, 1, 'F = m × a = 50 × 2 = 100 N.', 5),
    ('501c7a72-f9e0-5cd5-bf3a-74927c0d0108'::uuid, 'aafe1c5a-50cc-5978-aea7-aae50a396df8'::uuid, 'Quelle phase du mouvement fixe le couple maximal que doit fournir le moteur ?', 'mcq', '["L’accélération","Le palier à vitesse constante","L’arrêt","La décélération"]'::jsonb, 0, 'Il faut vaincre le couple résistant ET accélérer l’inertie.', 6),
    ('226d50cd-3c26-5c82-a92f-fe78506e37bf'::uuid, 'aafe1c5a-50cc-5978-aea7-aae50a396df8'::uuid, 'À vitesse constante, le moteur ne fournit aucun couple.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il doit encore compenser le couple résistant (frottements, charge).', 7),
    ('3c7cec0b-4c83-5094-ae13-484a9a1ed753'::uuid, 'aafe1c5a-50cc-5978-aea7-aae50a396df8'::uuid, 'Une cabine de 1 000 kg monte avec a = 0,5 m/s² (g = 9,81 m/s²). La tension du câble vaut environ…', 'mcq', '["9 810 N","500 N","10 310 N","9 310 N"]'::jsonb, 2, 'T = m × (g + a) = 1 000 × 10,31 = 10 310 N.', 8),
    ('6d7be89d-e5b2-5d0a-92b9-0bfb8d1aa5b2'::uuid, 'aafe1c5a-50cc-5978-aea7-aae50a396df8'::uuid, 'Un volant d’inertie J = 2 kg·m² subit un couple net de 10 N·m. Son accélération angulaire vaut…', 'mcq', '["20 rad/s²","0,2 rad/s²","12 rad/s²","5 rad/s²"]'::jsonb, 3, 'α = C / J = 10 / 2 = 5 rad/s².', 9),
    ('4f820f71-36b9-5d57-b3fd-992a1f3d584a'::uuid, 'aafe1c5a-50cc-5978-aea7-aae50a396df8'::uuid, 'Quelle unité a le moment d’inertie ?', 'mcq', '["kg·m²","N·m","kg/m","rad/s²"]'::jsonb, 0, 'Il combine une masse et le carré d’une distance.', 10),
    ('e71f8900-da34-56d4-8d1e-4c76fb3f6fc7'::uuid, 'aafe1c5a-50cc-5978-aea7-aae50a396df8'::uuid, 'En décélération, le couple moteur nécessaire est…', 'mcq', '["Toujours supérieur au couple résistant","Inférieur au couple résistant, voire négatif","Égal à J × ω","Indépendant de l’inertie"]'::jsonb, 1, 'Le couple résistant aide à ralentir ; un freinage peut même être nécessaire.', 11),
    ('d2a35215-4bbb-58bf-b91e-eb90b5a4a6a8'::uuid, 'aafe1c5a-50cc-5978-aea7-aae50a396df8'::uuid, 'Le poids fait partie du bilan des actions extérieures d’une cabine isolée.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est l’action à distance de la Terre sur la cabine.', 12),
    ('e17efaaa-1543-5085-b49d-655105be8718'::uuid, '92c18105-7318-5acf-b68c-a59e7741068e'::uuid, 'De quoi dépend le moment d’inertie d’un solide ?', 'mcq', '["De sa masse seulement","De sa vitesse de rotation","De sa masse et de sa répartition autour de l’axe","De sa couleur et de sa forme extérieure"]'::jsonb, 2, 'J additionne des m × r² : la distance à l’axe compte au carré.', 1),
    ('258fb7a6-761b-569b-937f-6dcf6c712c5c'::uuid, '92c18105-7318-5acf-b68c-a59e7741068e'::uuid, 'Quel est le moment d’inertie d’un disque plein de masse m et de rayon R ?', 'mcq', '["m × R²","½ × m × R²","2 × m × R","m × R"]'::jsonb, 1, 'Sa matière est répartie entre l’axe et le bord, d’où le facteur ½.', 2),
    ('c3c6554b-21fc-5975-a57c-515baa0a8183'::uuid, '92c18105-7318-5acf-b68c-a59e7741068e'::uuid, 'Si l’on double le rayon d’un anneau de même masse, son inertie est…', 'mcq', '["Doublée","Inchangée","Divisée par deux","Multipliée par quatre"]'::jsonb, 3, 'J = m × R² : le rayon compte au carré.', 3),
    ('41721f68-65a2-5efc-a696-9b7c2ebeeb68'::uuid, '92c18105-7318-5acf-b68c-a59e7741068e'::uuid, 'Un anneau de 2 kg et de rayon 0,5 m a une inertie de…', 'mcq', '["0,5 kg·m²","1 kg·m²","0,25 kg·m²","2 kg·m²"]'::jsonb, 0, 'J = m × R² = 2 × 0,25 = 0,5 kg·m².', 4),
    ('d9e95b12-1eda-5e15-bac7-0d17c9164862'::uuid, '92c18105-7318-5acf-b68c-a59e7741068e'::uuid, 'Quelle formule donne l’inertie équivalente ramenée sur l’arbre moteur ?', 'mcq', '["J_eq = J_m + J_c × k²","J_eq = J_m + J_c / k","J_eq = J_m × J_c","J_eq = J_c × k"]'::jsonb, 0, 'Elle découle de l’égalité des énergies cinétiques, avec k = ω_c / ω_m.', 5),
    ('b54d514f-d391-5075-b7af-8468ee016e57'::uuid, '92c18105-7318-5acf-b68c-a59e7741068e'::uuid, 'Un réducteur de rapport 1/5 divise l’inertie de la charge ressentie par le moteur par…', 'mcq', '["5","10","25","2,5"]'::jsonb, 2, 'On multiplie par k² = 1/25.', 6),
    ('92a37654-d0c1-507b-8837-acf0b3ce1a5d'::uuid, '92c18105-7318-5acf-b68c-a59e7741068e'::uuid, 'Sur quel principe repose le calcul de l’inertie équivalente ?', 'mcq', '["L’égalité des forces","La conservation de la masse","La loi des mailles","L’égalité des énergies cinétiques"]'::jsonb, 3, 'Le moteur doit « voir » la même énergie à fournir que l’ensemble réel.', 7),
    ('aae36ed1-4296-5cf3-9148-d863f373f771'::uuid, '92c18105-7318-5acf-b68c-a59e7741068e'::uuid, 'Pour qu’une pièce accélère vite, on allège de préférence…', 'mcq', '["Sa périphérie","Son centre","Son axe","Peu importe l’endroit"]'::jsonb, 0, 'La matière loin de l’axe pèse beaucoup plus dans J.', 8),
    ('aa9d36fd-ce5a-58d2-9fcb-1071b79e1249'::uuid, '92c18105-7318-5acf-b68c-a59e7741068e'::uuid, 'L’inertie du rotor du moteur peut toujours être négligée.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Avec un fort rapport de réduction, elle peut dominer l’inertie ramenée de la charge.', 9),
    ('8bff82ef-a48d-5016-a323-1d0d63876f4d'::uuid, '92c18105-7318-5acf-b68c-a59e7741068e'::uuid, 'Une masse levée par un tambour de rayon R, monté directement sur l’arbre moteur, compte dans l’inertie pour…', 'mcq', '["m × R","m × R²","m / R²","½ × m"]'::jsonb, 1, 'Sa vitesse vaut v = ω × R, donc m × (v / ω)² = m × R².', 10),
    ('8a951a5d-4d1c-515a-8657-6215e5da3ba2'::uuid, '92c18105-7318-5acf-b68c-a59e7741068e'::uuid, 'L’inertie équivalente se mesure en kg·m², comme toute inertie.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est une inertie comme une autre, simplement ramenée à un arbre de référence.', 11),
    ('3256845b-fd4b-5f67-b6ee-d175334ad0db'::uuid, '92c18105-7318-5acf-b68c-a59e7741068e'::uuid, 'Pourquoi associe-t-on souvent un petit moteur rapide à un réducteur ?', 'mcq', '["Pour augmenter la vitesse de la charge","Pour supprimer les frottements","Parce que le réducteur divise l’inertie ressentie et multiplie le couple","Pour augmenter la tension d’alimentation"]'::jsonb, 2, 'Le réducteur adapte à la fois le couple et l’inertie à ce que le moteur sait faire.', 12),
    ('0ec982e7-adc0-52f9-b4be-e95fa92c5a3a'::uuid, '8b786440-8e92-5a9c-a977-67f89591d94b'::uuid, 'Quelle est l’énergie cinétique d’un solide en translation ?', 'mcq', '["m × v","½ × m × v²","m × g × h","½ × J × ω²"]'::jsonb, 1, 'La formule ½ J ω² est son équivalent en rotation.', 1),
    ('579ff576-696b-53ae-9a15-20a146252f93'::uuid, '8b786440-8e92-5a9c-a977-67f89591d94b'::uuid, 'Si la vitesse d’un véhicule double, son énergie cinétique…', 'mcq', '["Double","Reste identique","Est multipliée par quatre","Est divisée par deux"]'::jsonb, 2, 'Ec dépend du carré de la vitesse.', 2),
    ('c05efd31-fdcc-5a1b-83eb-881dcba82390'::uuid, '8b786440-8e92-5a9c-a977-67f89591d94b'::uuid, 'Un volant d’inertie J = 0,2 kg·m² tourne à 100 rad/s. Son énergie cinétique vaut…', 'mcq', '["1 000 J","20 J","2 000 J","10 J"]'::jsonb, 0, 'Ec = ½ × 0,2 × 100² = 1 000 J.', 3),
    ('215007ad-3071-5e4c-a4fc-0ebc83727127'::uuid, '8b786440-8e92-5a9c-a977-67f89591d94b'::uuid, 'Comment s’exprime la puissance mécanique en rotation ?', 'mcq', '["P = C / ω","P = C + ω","P = ½ × C × ω²","P = C × ω"]'::jsonb, 3, 'Couple en N·m, vitesse angulaire en rad/s, puissance en W.', 4),
    ('5cd97f6b-6d01-52a1-8021-6578d59af1d8'::uuid, '8b786440-8e92-5a9c-a977-67f89591d94b'::uuid, 'Un moteur fournit 5 N·m à 200 rad/s. Sa puissance mécanique vaut…', 'mcq', '["40 W","1 000 W","205 W","25 W"]'::jsonb, 1, 'P = C × ω = 5 × 200 = 1 000 W.', 5),
    ('b652ea58-8b05-54c2-a778-9def60507d31'::uuid, '8b786440-8e92-5a9c-a977-67f89591d94b'::uuid, 'Que dit le théorème de l’énergie cinétique ?', 'mcq', '["La variation d’Ec est égale au travail des actions appliquées","L’énergie cinétique est toujours constante","La puissance est égale à la masse","Le couple est égal à la vitesse"]'::jsonb, 0, 'Pour accélérer, il faut fournir un travail ; pour freiner, il faut en prélever.', 6),
    ('090e549e-d43e-5c8e-9e58-4d7acf63b80f'::uuid, '8b786440-8e92-5a9c-a977-67f89591d94b'::uuid, 'Pour choisir un moteur, on vérifie seulement la puissance moyenne.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il faut aussi le couple de pointe et la vitesse maximale : la moyenne cache le pire moment.', 7),
    ('f5c31356-965f-5970-83ac-20c7da9f73a7'::uuid, '8b786440-8e92-5a9c-a977-67f89591d94b'::uuid, 'Où part l’énergie cinétique lors d’un freinage récupératif ?', 'mcq', '["Dans l’air","Dans les pneus","Dans la batterie","Dans le moteur thermique"]'::jsonb, 2, 'La machine électrique fonctionne alors en génératrice.', 8),
    ('d016b057-7664-5efa-9d64-b2bcde7cd0c2'::uuid, '8b786440-8e92-5a9c-a977-67f89591d94b'::uuid, 'Un moteur dont la puissance nominale est inférieure à la puissance continue demandée…', 'mcq', '["Tourne plus vite","Consomme moins","Devient plus précis","Chauffe et vieillit prématurément"]'::jsonb, 3, 'La puissance nominale est ce qu’il supporte en continu sans surchauffe.', 9),
    ('0cd27710-2386-5fa5-a444-4e3191036293'::uuid, '8b786440-8e92-5a9c-a977-67f89591d94b'::uuid, 'Une masse de 100 kg roule à 3 m/s. Son énergie cinétique vaut…', 'mcq', '["150 J","300 J","450 J","900 J"]'::jsonb, 2, 'Ec = ½ × 100 × 9 = 450 J.', 10),
    ('ffa7dd08-00df-5883-a258-fa8c15bb1e70'::uuid, '8b786440-8e92-5a9c-a977-67f89591d94b'::uuid, 'La puissance instantanée en fin d’accélération peut dépasser nettement la puissance moyenne.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'À force motrice constante, P = F × v croît avec la vitesse.', 11),
    ('f8fcf3d9-0976-50b6-9054-72ee2492ec9a'::uuid, '8b786440-8e92-5a9c-a977-67f89591d94b'::uuid, 'Que représente la puissance ?', 'mcq', '["Une force","Un débit d’énergie","Une masse en mouvement","Une vitesse angulaire"]'::jsonb, 1, 'P = énergie / durée, en watts, c’est-à-dire en joules par seconde.', 12),
    ('7a89f3a7-a3d0-5938-b77d-973487236fc6'::uuid, '968603ea-5a17-5d55-9ab2-43d0bdf1f026'::uuid, 'Un pignon de 15 dents entraîne une roue de 45 dents. Le rapport ω_roue / ω_pignon vaut…', 'mcq', '["3","1/3","1/45","60"]'::jsonb, 1, 'ω2 / ω1 = Z1 / Z2 = 15 / 45 = 1/3.', 1),
    ('c00d8219-27e0-592a-906c-09aab53c341c'::uuid, '968603ea-5a17-5d55-9ab2-43d0bdf1f026'::uuid, 'Deux roues en contact extérieur tournent…', 'mcq', '["Dans le même sens","Toujours à la même vitesse","En sens inverses","Seulement si elles ont le même nombre de dents"]'::jsonb, 2, 'C’est pour cela qu’on ajoute parfois une roue intermédiaire pour retrouver le sens.', 2),
    ('7666810b-496e-510a-8889-a04dd7282db7'::uuid, '968603ea-5a17-5d55-9ab2-43d0bdf1f026'::uuid, 'Quel transmetteur transforme une rotation en translation ?', 'mcq', '["Le train d’engrenages","Le système poulies-courroie","Le réducteur à engrenages","Le pignon-crémaillère"]'::jsonb, 3, 'Sa loi est v = ω × R, avec R le rayon primitif du pignon.', 3),
    ('c63e3f16-32c0-55cf-a8cf-5c7365e6fbac'::uuid, '968603ea-5a17-5d55-9ab2-43d0bdf1f026'::uuid, 'Une vis de pas 5 mm tourne à 2 tours par seconde. L’écrou avance à…', 'mcq', '["10 mm/s","2,5 mm/s","5 mm/s","7 mm/s"]'::jsonb, 0, 'Chaque tour fait avancer d’un pas : 2 × 5 = 10 mm/s.', 4),
    ('b58437eb-7ef8-54cc-ad4a-985d23f85be4'::uuid, '968603ea-5a17-5d55-9ab2-43d0bdf1f026'::uuid, 'Un réducteur divise la vitesse par 4 avec un rendement de 1. Le couple de sortie est…', 'mcq', '["Divisé par 4","Multiplié par 4","Inchangé","Multiplié par 16"]'::jsonb, 1, 'La puissance C × ω se conserve : moins de vitesse, plus de couple.', 5),
    ('d0fc17b4-f09f-5677-93a5-f677a6191592'::uuid, '968603ea-5a17-5d55-9ab2-43d0bdf1f026'::uuid, 'Dans une chaîne de transmetteurs, le rendement global est…', 'mcq', '["La somme des rendements","Le plus faible des rendements","Le produit des rendements","La moyenne des rendements"]'::jsonb, 2, 'Chaque étage prélève sa part de pertes sur ce qu’il reçoit.', 6),
    ('c4090f86-c433-5fd8-a13b-21c37e3d484c'::uuid, '968603ea-5a17-5d55-9ab2-43d0bdf1f026'::uuid, 'Dans un système poulies-courroie, les deux poulies tournent dans le même sens.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec une courroie ouverte (non croisée), le sens est conservé.', 7),
    ('dfd4b778-2604-56f9-87c8-86455567c635'::uuid, '968603ea-5a17-5d55-9ab2-43d0bdf1f026'::uuid, 'Quel est l’intérêt d’une vis-écrou non réversible sur un cric ?', 'mcq', '["Augmenter la vitesse de levée","Améliorer le rendement","Réduire le bruit","Empêcher la charge de redescendre seule"]'::jsonb, 3, 'L’irréversibilité est ici une sécurité.', 8),
    ('209a7ac1-6e21-53b8-b8d9-05ae546356cc'::uuid, '968603ea-5a17-5d55-9ab2-43d0bdf1f026'::uuid, 'Un pignon de rayon primitif 20 mm tourne à 10 rad/s sur une crémaillère. Celle-ci avance à…', 'mcq', '["0,2 m/s","2 m/s","0,02 m/s","20 m/s"]'::jsonb, 0, 'v = ω × R = 10 × 0,02 = 0,2 m/s.', 9),
    ('7eef2350-95ff-5cff-8773-e49bfd8a74e5'::uuid, '968603ea-5a17-5d55-9ab2-43d0bdf1f026'::uuid, 'Trois étages de rendements 0,9, 0,8 et 0,5 donnent un rendement global de…', 'mcq', '["2,2","0,5","0,36","0,73"]'::jsonb, 2, '0,9 × 0,8 × 0,5 = 0,36.', 10),
    ('2fd8a9c6-7939-5d9e-ab79-183d8dcc18b1'::uuid, '968603ea-5a17-5d55-9ab2-43d0bdf1f026'::uuid, 'Un réducteur permet de gagner à la fois en vitesse et en couple.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'La puissance ne se crée pas : ce qu’on gagne en couple se perd en vitesse.', 11),
    ('fb177f7e-c51c-5bc1-b47e-d430bf94ff34'::uuid, '968603ea-5a17-5d55-9ab2-43d0bdf1f026'::uuid, 'Pour un moteur de 1 N·m et un réducteur de rapport 1/10 de rendement 0,8, le couple de sortie vaut…', 'mcq', '["0,08 N·m","10 N·m","12,5 N·m","8 N·m"]'::jsonb, 3, 'C_s = η × C_e / k = 0,8 × 1 × 10 = 8 N·m.', 12),
    ('aac22999-8324-5670-a878-519415f9ad0a'::uuid, '079e7ddb-0d18-5e01-8c3d-13665b866130'::uuid, 'Dans un moteur à courant continu, le couple électromagnétique est proportionnel…', 'mcq', '["À la tension","Au courant","À la vitesse","À la résistance"]'::jsonb, 1, 'C_em = k × I : le courant fait le couple.', 1),
    ('7ab865ca-1141-5c04-bdc8-ae8dcc1bd4e9'::uuid, '079e7ddb-0d18-5e01-8c3d-13665b866130'::uuid, 'La force contre-électromotrice E est proportionnelle…', 'mcq', '["Au courant","À la résistance","À la vitesse de rotation","Au couple résistant"]'::jsonb, 2, 'E = k × Ω : elle naît de la rotation du bobinage.', 2),
    ('030174c5-ba4a-5025-b714-b2549f79b133'::uuid, '079e7ddb-0d18-5e01-8c3d-13665b866130'::uuid, 'Quelle équation décrit l’induit en régime permanent ?', 'mcq', '["U = E + R × I","U = E − R × I","U = R / I","U = k × I"]'::jsonb, 0, 'La tension se partage entre E et la chute dans la résistance.', 3),
    ('6ff7e997-1f78-5a04-9527-591cce8566d4'::uuid, '079e7ddb-0d18-5e01-8c3d-13665b866130'::uuid, 'Pourquoi le courant est-il très élevé au démarrage ?', 'mcq', '["Parce que la résistance augmente","Parce que le couple est nul","Parce que la tension double","Parce que E est nulle à l’arrêt"]'::jsonb, 3, 'Sans vitesse, pas de force contre-électromotrice : I = U / R.', 4),
    ('cb2046a3-fa9a-5e4a-a301-39108b634220'::uuid, '079e7ddb-0d18-5e01-8c3d-13665b866130'::uuid, 'Pour augmenter la vitesse d’un moteur à courant continu, on augmente…', 'mcq', '["La tension d’alimentation","La résistance de l’induit","Le couple résistant","La constante k"]'::jsonb, 0, 'La tension fait la vitesse, à couple donné.', 5),
    ('3e468404-eb1a-50ed-8a28-e40d79527e65'::uuid, '079e7ddb-0d18-5e01-8c3d-13665b866130'::uuid, 'Les pertes Joule dans l’induit valent…', 'mcq', '["U × I","R × I²","E × I","k × Ω"]'::jsonb, 1, 'Elles chauffent le bobinage et croissent comme le carré du courant.', 6),
    ('74e5b21b-80a1-5a60-a875-0ac0ce8d17cc'::uuid, '079e7ddb-0d18-5e01-8c3d-13665b866130'::uuid, 'Un moteur de k = 0,1 N·m/A absorbe 3 A. Son couple électromagnétique vaut…', 'mcq', '["30 N·m","0,03 N·m","0,3 N·m","3,1 N·m"]'::jsonb, 2, 'C = k × I = 0,1 × 3 = 0,3 N·m.', 7),
    ('392c0cc7-1bdf-5466-b0f9-c37479bdf007'::uuid, '079e7ddb-0d18-5e01-8c3d-13665b866130'::uuid, 'Un moteur à courant continu peut fonctionner en génératrice.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Entraîné, il produit E = k × Ω : c’est la base du freinage récupératif.', 8),
    ('7408bf5d-cb7f-528a-9c9c-b723e092927e'::uuid, '079e7ddb-0d18-5e01-8c3d-13665b866130'::uuid, 'Sous 12 V, un moteur de R = 2 Ω absorbe 1 A. Sa force contre-électromotrice vaut…', 'mcq', '["14 V","12 V","6 V","10 V"]'::jsonb, 3, 'E = U − R × I = 12 − 2 = 10 V.', 9),
    ('cf1fceb1-0510-573f-94ed-045caf6c7fb6'::uuid, '079e7ddb-0d18-5e01-8c3d-13665b866130'::uuid, 'La puissance électromagnétique s’écrit E × I, ou encore…', 'mcq', '["R × I²","U × I","C_em × Ω","k × U"]'::jsonb, 2, 'C’est le point de passage entre le monde électrique et le monde mécanique.', 10),
    ('e5582046-acd4-5856-b785-dbbedb3fc887'::uuid, '079e7ddb-0d18-5e01-8c3d-13665b866130'::uuid, 'Quand le couple résistant augmente à tension constante, la vitesse du moteur…', 'mcq', '["Diminue un peu","Augmente","Reste rigoureusement constante","Devient nulle immédiatement"]'::jsonb, 0, 'Le courant monte, la chute R × I aussi, donc E et la vitesse baissent.', 11),
    ('365f7add-6ea1-5eac-8bc6-4eb115b5b356'::uuid, '079e7ddb-0d18-5e01-8c3d-13665b866130'::uuid, 'Le rendement d’un moteur peut dépasser 100 %.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il y a toujours des pertes : Joule, mécaniques, magnétiques.', 12),
    ('28f91a1a-7ea4-5b7b-9390-8538fbeaba66'::uuid, 'e6b3a79c-6764-5ce0-9298-bcdb90cee99b'::uuid, 'Que vaut la tension moyenne en sortie d’un hacheur série ?', 'mcq', '["U_alim / α","α × U_alim","U_alim − α","α² × U_alim"]'::jsonb, 1, 'On ne change que la durée de conduction, pas la hauteur du créneau.', 1),
    ('db40aabd-67d9-5619-87ea-a9f1b8a0f5e5'::uuid, 'e6b3a79c-6764-5ce0-9298-bcdb90cee99b'::uuid, 'Le rapport cyclique est défini par…', 'mcq', '["t_on / T","T / t_on","f × T","U_moy × T"]'::jsonb, 0, 'C’est la fraction de la période pendant laquelle l’interrupteur conduit.', 2),
    ('0b9d39fa-d2f7-5a24-a539-1b06e57123ef'::uuid, 'e6b3a79c-6764-5ce0-9298-bcdb90cee99b'::uuid, 'Sous 24 V, avec α = 0,25, la tension moyenne vaut…', 'mcq', '["24 V","12 V","3 V","6 V"]'::jsonb, 3, 'U_moy = 0,25 × 24 = 6 V.', 3),
    ('7883ec07-1c57-5c36-8bb6-87688d916755'::uuid, 'e6b3a79c-6764-5ce0-9298-bcdb90cee99b'::uuid, 'Pourquoi un hacheur a-t-il un bien meilleur rendement qu’une résistance série ?', 'mcq', '["Parce qu’il fonctionne en courant alternatif","Parce qu’il stocke l’énergie dans une pile","Parce que ses interrupteurs dissipent presque rien, ouverts ou fermés","Parce qu’il augmente la tension"]'::jsonb, 2, 'Ouvert, I ≈ 0 ; fermé, U ≈ 0 : le produit U × I reste proche de zéro.', 4),
    ('530ec7a0-4b55-52de-bfe7-1fffa76e33f5'::uuid, 'e6b3a79c-6764-5ce0-9298-bcdb90cee99b'::uuid, 'Quel est le rôle de la diode de roue libre ?', 'mcq', '["Laisser circuler le courant de l’inductance quand le transistor s’ouvre","Augmenter la tension","Mesurer la vitesse","Inverser le sens de rotation"]'::jsonb, 0, 'Sans elle, la coupure brutale du courant créerait une surtension destructrice.', 5),
    ('0c105749-b2fc-5817-9859-07f47a628d0e'::uuid, 'e6b3a79c-6764-5ce0-9298-bcdb90cee99b'::uuid, 'Que permet un pont en H ?', 'mcq', '["De doubler la tension","De supprimer le découpage","De mesurer le courant","D’inverser le sens de rotation du moteur"]'::jsonb, 3, 'Ses quatre interrupteurs inversent la polarité appliquée au moteur.', 6),
    ('20d0f72d-b96d-5f29-b78e-a82d5a2570bc'::uuid, 'e6b3a79c-6764-5ce0-9298-bcdb90cee99b'::uuid, 'La MLI change la hauteur des créneaux de tension.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle change leur largeur ; la hauteur reste la tension d’alimentation.', 7),
    ('92606ef8-8582-5564-8fe0-9520d1869988'::uuid, 'e6b3a79c-6764-5ce0-9298-bcdb90cee99b'::uuid, 'À 10 kHz, quelle est la période de découpage ?', 'mcq', '["10 ms","1 ms","100 µs","10 µs"]'::jsonb, 2, 'T = 1 / 10 000 = 0,0001 s = 100 µs.', 8),
    ('bcb811b1-761a-5286-b6d7-aadd447bb6e4'::uuid, 'e6b3a79c-6764-5ce0-9298-bcdb90cee99b'::uuid, 'Dans quel quadrant la machine freine-t-elle en marche avant ?', 'mcq', '["Vitesse positive, couple négatif","Vitesse positive, couple positif","Vitesse négative, couple négatif","Vitesse nulle, couple nul"]'::jsonb, 0, 'Le couple s’oppose au mouvement : la machine fonctionne en génératrice.', 9),
    ('a94130bd-d200-5a8f-8444-0c8498f46498'::uuid, 'e6b3a79c-6764-5ce0-9298-bcdb90cee99b'::uuid, 'Pourquoi découpe-t-on souvent au-dessus de 20 kHz ?', 'mcq', '["Pour augmenter la tension moyenne","Pour que le découpage ne s’entende pas","Pour inverser le sens","Pour réduire la vitesse"]'::jsonb, 1, 'Au-delà d’environ 20 kHz, l’oreille humaine ne perçoit plus le sifflement.', 10),
    ('2f0fe1f5-100c-524f-a67b-7a69a240a4a3'::uuid, 'e6b3a79c-6764-5ce0-9298-bcdb90cee99b'::uuid, 'L’inductance du moteur lisse le courant découpé.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Elle s’oppose aux variations brusques du courant.', 11),
    ('03218217-6ecd-5dea-8ffe-f588a27bae68'::uuid, 'e6b3a79c-6764-5ce0-9298-bcdb90cee99b'::uuid, 'Sur une sortie MLI réglable de 0 à 255, quelle consigne donne environ la moitié de la tension ?', 'mcq', '["64","255","0","128"]'::jsonb, 3, '128 / 255 ≈ 0,5.', 12),
    ('f973ae0b-9e76-5f8a-8c8a-73ec28301209'::uuid, '14e477ac-628d-5398-a780-5bc62ef61fca'::uuid, 'Quelle grandeur mesure l’énergie stockée dans une batterie ?', 'mcq', '["Le wattheure (Wh)","L’ampère-heure (Ah)","Le volt (V)","L’ohm (Ω)"]'::jsonb, 0, 'L’Ah est une quantité d’électricité ; il faut la multiplier par la tension.', 1),
    ('ec5c0f23-b472-5e61-8c97-57de28d96fae'::uuid, '14e477ac-628d-5398-a780-5bc62ef61fca'::uuid, 'Une batterie de 12 V et 5 Ah stocke…', 'mcq', '["17 Wh","2,4 Wh","60 Wh","600 Wh"]'::jsonb, 2, 'W = Q × U = 5 × 12 = 60 Wh.', 2),
    ('ff44ac5e-70b4-5f51-964f-c08903480c50'::uuid, '14e477ac-628d-5398-a780-5bc62ef61fca'::uuid, 'Des cellules associées en série…', 'mcq', '["Additionnent leurs capacités","Additionnent leurs tensions","Divisent leur tension","Ne changent rien"]'::jsonb, 1, 'Les capacités s’additionnent en parallèle, les tensions en série.', 3),
    ('e204976e-40db-57ab-aee0-d086b0f12f70'::uuid, '14e477ac-628d-5398-a780-5bc62ef61fca'::uuid, 'Pourquoi ne décharge-t-on pas une batterie à 100 % ?', 'mcq', '["Pour préserver sa durée de vie","Pour augmenter sa tension","Parce que c’est interdit","Pour gagner en masse"]'::jsonb, 0, 'Les décharges profondes usent plus vite les cellules.', 4),
    ('597e212b-44a2-5576-bdff-d2816c35bc67'::uuid, '14e477ac-628d-5398-a780-5bc62ef61fca'::uuid, 'Deux batteries de 10 Ah ont forcément la même autonomie.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il faut comparer l’énergie en Wh, qui dépend aussi de la tension.', 5),
    ('8da02f80-f410-5821-bc61-98fb160638ae'::uuid, '14e477ac-628d-5398-a780-5bc62ef61fca'::uuid, 'Une batterie de 200 Wh utiles alimente un robot de 50 W. Son autonomie vaut…', 'mcq', '["10 000 h","250 h","0,25 h","4 h"]'::jsonb, 3, 't = W / P = 200 / 50 = 4 h.', 6),
    ('2640f6e8-f668-59bb-a767-e50eb0f17020'::uuid, '14e477ac-628d-5398-a780-5bc62ef61fca'::uuid, 'Combien de cellules de 3,6 V faut-il en série pour obtenir 36 V ?', 'mcq', '["4","36","10","12"]'::jsonb, 2, '36 / 3,6 = 10 cellules.', 7),
    ('add422b0-3471-5f9d-b346-9149804535b3'::uuid, '14e477ac-628d-5398-a780-5bc62ef61fca'::uuid, 'Quel est le point fort d’un supercondensateur par rapport à une batterie ?', 'mcq', '["Il fournit de très fortes puissances et supporte énormément de cycles","Il stocke beaucoup plus d’énergie","Il ne s’use jamais","Il fonctionne sans tension"]'::jsonb, 0, 'Il stocke peu d’énergie, mais la rend très vite.', 8),
    ('fff5effe-1da3-59ea-8fa9-afb9c7dc2163'::uuid, '14e477ac-628d-5398-a780-5bc62ef61fca'::uuid, 'Que désigne un courant de décharge de 1 C ?', 'mcq', '["Un courant de 1 A","Un courant qui décharge la batterie en une heure environ","Un courant de charge nul","La tension de la cellule"]'::jsonb, 1, 'Pour une batterie de 2 Ah, 1 C correspond à 2 A.', 9),
    ('37838fca-a0d2-5955-813e-e0b48f54b278'::uuid, '14e477ac-628d-5398-a780-5bc62ef61fca'::uuid, 'Le froid peut réduire la capacité disponible d’une batterie.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Les réactions chimiques ralentissent : l’autonomie baisse en hiver.', 10),
    ('c2007dc8-4764-5193-969c-824d913900d2'::uuid, '14e477ac-628d-5398-a780-5bc62ef61fca'::uuid, 'Quelle expression donne l’énergie stockée dans un condensateur ?', 'mcq', '["C × U","Q × U²","½ × C × U²","U / C"]'::jsonb, 2, 'C est la capacité en farads, U la tension à ses bornes.', 11),
    ('c33da2ca-9ec1-5405-80e8-ed943c228a6f'::uuid, '14e477ac-628d-5398-a780-5bc62ef61fca'::uuid, 'Une batterie « 10S4P » comporte…', 'mcq', '["14 cellules","10 cellules","4 cellules","40 cellules"]'::jsonb, 3, '10 en série, et 4 branches de ce type en parallèle : 10 × 4 = 40.', 12),
    ('5dff846b-ae7c-501c-a518-63a9073348b2'::uuid, '682a3fa3-d6f9-571a-af30-34eb29381be6'::uuid, 'Comment calcule-t-on la contrainte normale dans une barre tendue ?', 'mcq', '["σ = N × S","σ = N / S","σ = S / N","σ = E × N"]'::jsonb, 1, 'C’est l’effort réparti sur la section qui le porte.', 1),
    ('7d7f649e-a6a9-5edc-95e9-dfd776132ece'::uuid, '682a3fa3-d6f9-571a-af30-34eb29381be6'::uuid, 'À quoi équivaut 1 MPa ?', 'mcq', '["1 N/m²","1 kN/m","1 N/mm²","1 kg/cm"]'::jsonb, 2, 'Un mégapascal vaut un newton par millimètre carré.', 2),
    ('a6c159da-c8a5-5268-a60b-89ef04de199e'::uuid, '682a3fa3-d6f9-571a-af30-34eb29381be6'::uuid, 'Que dit la loi de Hooke ?', 'mcq', '["σ = E × ε dans le domaine élastique","La contrainte est toujours nulle","σ = N × L","La déformation est permanente"]'::jsonb, 0, 'Dans le domaine élastique, contrainte et déformation sont proportionnelles.', 3),
    ('3966e79b-398b-51e6-83cc-763dc47cebdf'::uuid, '682a3fa3-d6f9-571a-af30-34eb29381be6'::uuid, 'Que représente le module d’Young ?', 'mcq', '["La contrainte de rupture","La masse volumique","La limite élastique","La raideur du matériau"]'::jsonb, 3, 'Plus E est grand, moins le matériau s’allonge pour une même contrainte.', 4),
    ('fe2d9742-c41d-5611-aef2-a8be5c1b1021'::uuid, '682a3fa3-d6f9-571a-af30-34eb29381be6'::uuid, 'Au-delà de la limite élastique, la déformation devient permanente.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'On entre dans le domaine plastique : la pièce ne revient plus à sa forme.', 5),
    ('29d84377-4e5e-5acf-b819-a9beb7bb9ed5'::uuid, '682a3fa3-d6f9-571a-af30-34eb29381be6'::uuid, 'Une barre de 100 mm² est tirée par 5 000 N. Sa contrainte vaut…', 'mcq', '["500 MPa","0,02 MPa","5 000 MPa","50 MPa"]'::jsonb, 3, 'σ = 5 000 / 100 = 50 MPa.', 6),
    ('c8b6fc90-775e-50cb-b7de-e6d43bd748fa'::uuid, '682a3fa3-d6f9-571a-af30-34eb29381be6'::uuid, 'Quel matériau est le plus raide ?', 'mcq', '["L’aluminium","L’acier","Le bois","Un polymère courant"]'::jsonb, 1, 'Son module d’Young, environ 210 000 MPa, est trois fois celui de l’aluminium.', 7),
    ('b526cd57-08b4-57aa-9e30-2bce0fc5aa69'::uuid, '682a3fa3-d6f9-571a-af30-34eb29381be6'::uuid, 'Que vaut l’allongement relatif ε ?', 'mcq', '["ΔL × L0","L0 / ΔL","ΔL / L0","ΔL − L0"]'::jsonb, 2, 'C’est un rapport de longueurs, sans unité.', 8),
    ('c42f6fa2-523d-5eb9-8c4e-2f024358d260'::uuid, '682a3fa3-d6f9-571a-af30-34eb29381be6'::uuid, 'À quoi sert le coefficient de sécurité ?', 'mcq', '["À garder une marge sous la limite élastique","À augmenter la contrainte admissible","À calculer la masse","À mesurer le module d’Young"]'::jsonb, 0, 'On impose σ ≤ Re / s pour absorber les incertitudes.', 9),
    ('364bdc58-238e-56ad-a552-bbe17f352f3f'::uuid, '682a3fa3-d6f9-571a-af30-34eb29381be6'::uuid, 'Doubler la section d’un tirant, à effort égal, divise sa contrainte par…', 'mcq', '["4","2","1","8"]'::jsonb, 1, 'σ = N / S : la section double, la contrainte est divisée par deux.', 10),
    ('6c32a332-9f45-5be2-8d6b-b2d12c211f60'::uuid, '682a3fa3-d6f9-571a-af30-34eb29381be6'::uuid, 'La résistance à la rupture Rm est inférieure à la limite élastique Re.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Rm est la contrainte maximale de la courbe : elle est au-dessus de Re.', 11),
    ('af25e5c7-13f7-5de9-9915-acbe35ebf3ce'::uuid, '682a3fa3-d6f9-571a-af30-34eb29381be6'::uuid, 'Un acier avec Re = 300 MPa et s = 2 admet une contrainte maximale de…', 'mcq', '["600 MPa","302 MPa","298 MPa","150 MPa"]'::jsonb, 3, 'σ admissible = Re / s = 300 / 2 = 150 MPa.', 12),
    ('c4b81b05-fc48-5411-bd47-b29dbc9da3d7'::uuid, '0c153e74-4246-5b56-9781-ae93102a5624'::uuid, 'Où la contrainte est-elle nulle dans une poutre fléchie ?', 'mcq', '["Sur les fibres du haut","Sur les fibres du bas","Sur la fibre neutre","Aux appuis seulement"]'::jsonb, 2, 'La fibre neutre n’est ni tendue ni comprimée.', 1),
    ('0633b58a-1750-5f76-9933-a90ad40e4830'::uuid, '0c153e74-4246-5b56-9781-ae93102a5624'::uuid, 'Pour une poutre sur deux appuis chargée vers le bas, les fibres du bas sont…', 'mcq', '["Tendues","Comprimées","Sans contrainte","Cisaillées uniquement"]'::jsonb, 0, 'Le bas s’allonge, le haut se raccourcit.', 2),
    ('d9a76183-a04b-5b7a-a331-712d4e9afec1'::uuid, '0c153e74-4246-5b56-9781-ae93102a5624'::uuid, 'Quel est le moment quadratique d’un rectangle de base b et de hauteur h ?', 'mcq', '["b × h / 12","b² × h / 12","b × h² / 6","b × h³ / 12"]'::jsonb, 3, 'La hauteur, dans le sens de la flexion, compte au cube.', 3),
    ('46054b93-58ff-5956-9158-84cf7a92cc6e'::uuid, '0c153e74-4246-5b56-9781-ae93102a5624'::uuid, 'Pourquoi une planche posée sur chant plie-t-elle moins qu’à plat ?', 'mcq', '["Parce qu’elle est plus lourde","Parce que son moment quadratique est bien plus grand","Parce que le matériau change","Parce que la charge diminue"]'::jsonb, 1, 'La hauteur passe dans le sens de la flexion, et elle compte au cube.', 4),
    ('c1c3bb73-f51f-5c62-acd9-660aa5ec56e4'::uuid, '0c153e74-4246-5b56-9781-ae93102a5624'::uuid, 'Doubler la portée d’une poutre sur deux appuis, à charge égale, multiplie sa flèche par…', 'mcq', '["2","4","8","16"]'::jsonb, 2, 'La flèche dépend du cube de la portée.', 5),
    ('b4d3c7d1-00ba-5214-8830-eebf62e06ee7'::uuid, '0c153e74-4246-5b56-9781-ae93102a5624'::uuid, 'Quelle est la flèche d’une poutre sur deux appuis chargée au milieu ?', 'mcq', '["F × L³ / (48 × E × I)","F × L / 4","F × L³ / (3 × E × I)","F / (E × I)"]'::jsonb, 0, 'La seconde formule en L³ concerne la console chargée en bout.', 6),
    ('87518f37-a5e1-53d7-9636-56a168a922d4'::uuid, '0c153e74-4246-5b56-9781-ae93102a5624'::uuid, 'Le moment fléchissant maximal d’une console de longueur L chargée en bout par F vaut…', 'mcq', '["F × L / 4","F / L","F × L²","F × L"]'::jsonb, 3, 'Il est maximal à l’encastrement.', 7),
    ('d6ead041-a07c-508e-83a4-52a123aa2b91'::uuid, '0c153e74-4246-5b56-9781-ae93102a5624'::uuid, 'Pourquoi les poutres en I sont-elles efficaces ?', 'mcq', '["Elles placent la matière loin de la fibre neutre","Elles sont plus lourdes","Elles suppriment la flexion","Elles sont en aluminium"]'::jsonb, 0, 'C’est là que la matière travaille le plus : on gagne en I sans alourdir.', 8),
    ('5c566491-1981-56df-9584-4936dc1f1835'::uuid, '0c153e74-4246-5b56-9781-ae93102a5624'::uuid, 'Une poutre peut résister sans rompre mais être refusée à cause de sa flèche.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le cahier des charges limite aussi la déformation, pas seulement la rupture.', 9),
    ('40f3145f-1a80-5997-bc97-ba9e8834ba34'::uuid, '0c153e74-4246-5b56-9781-ae93102a5624'::uuid, 'Comment s’écrit la contrainte maximale en flexion ?', 'mcq', '["σ = Mf × I / v","σ = Mf × v / I","σ = Mf / (v × I)","σ = I × v"]'::jsonb, 1, 'v est la distance de la fibre neutre à la fibre extrême.', 10),
    ('c687abb5-e106-51f1-b2fc-9e293bfb92ee'::uuid, '0c153e74-4246-5b56-9781-ae93102a5624'::uuid, 'Augmenter le module d’Young du matériau augmente la flèche.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'E est au dénominateur : un matériau plus raide fléchit moins.', 11),
    ('e790d23a-9be6-51d4-bce9-aa9d46d91636'::uuid, '0c153e74-4246-5b56-9781-ae93102a5624'::uuid, 'Une section 10 × 40 mm est fléchie dans le sens des 40 mm. Son moment quadratique vaut environ…', 'mcq', '["53 333 mm⁴","3 333 mm⁴","400 mm⁴","160 000 mm⁴"]'::jsonb, 0, 'I = 10 × 40³ / 12 = 640 000 / 12 ≈ 53 333 mm⁴.', 12),
    ('574835fe-1c57-547c-a086-05b6273a9797'::uuid, '8e30ee83-b9be-52bb-a3ef-412abcf4b551'::uuid, 'Que calcule le comparateur d’un schéma-bloc ?', 'mcq', '["La somme de la consigne et de la mesure","La différence consigne − mesure","Le produit des gains","La puissance du moteur"]'::jsonb, 1, 'Cette différence est l’erreur que le correcteur va traiter.', 1),
    ('8d30f548-04c6-5a05-8463-4ea2d472eee5'::uuid, '8e30ee83-b9be-52bb-a3ef-412abcf4b551'::uuid, 'Deux blocs en série de gains 4 et 5 équivalent à un bloc de gain…', 'mcq', '["9","1,25","20","0,8"]'::jsonb, 2, 'En série, les gains se multiplient.', 2),
    ('2d001c29-ff56-54f5-a510-3e0562d05751'::uuid, '8e30ee83-b9be-52bb-a3ef-412abcf4b551'::uuid, 'Quel est le gain d’une boucle fermée à retour unitaire de chaîne directe A ?', 'mcq', '["A / (1 + A)","A × (1 + A)","1 / A","A − 1"]'::jsonb, 0, 'C’est la formule de Black dans le cas d’un retour unitaire.', 3),
    ('c685d5c9-8e3b-5188-a01d-6968e6f5eac4'::uuid, '8e30ee83-b9be-52bb-a3ef-412abcf4b551'::uuid, 'Avec A = 9 et un retour unitaire, quelle part de la consigne atteint la sortie ?', 'mcq', '["50 %","99 %","9 %","90 %"]'::jsonb, 3, '9 / (1 + 9) = 0,9.', 4),
    ('80451d07-d3ea-5664-b6ed-806cb508a489'::uuid, '8e30ee83-b9be-52bb-a3ef-412abcf4b551'::uuid, 'Que vaut l’erreur relative restante pour A = 99 ?', 'mcq', '["10 %","1 %","0 %","99 %"]'::jsonb, 1, 'ε = 1 / (1 + 99) = 1 %.', 5),
    ('94f6fdc6-74c9-5512-9631-59b67b913afe'::uuid, '8e30ee83-b9be-52bb-a3ef-412abcf4b551'::uuid, 'Augmenter le gain proportionnel sans limite ne pose aucun problème.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Un gain trop fort fait osciller le système, voire le rend instable.', 6),
    ('8067f15b-d2d3-5b1a-a0af-70214d61f6e9'::uuid, '8e30ee83-b9be-52bb-a3ef-412abcf4b551'::uuid, 'Avec un retour de gain B, le gain de la boucle fermée vaut…', 'mcq', '["A / (1 + B)","A × B","A / (1 + A × B)","B / (1 + A)"]'::jsonb, 2, 'On retrouve A / (1 + A) quand B = 1.', 7),
    ('737cd086-696a-54a4-8630-a1a67c5534ef'::uuid, '8e30ee83-b9be-52bb-a3ef-412abcf4b551'::uuid, 'Un capteur qui surestime la mesure de 2 %…', 'mcq', '["Fausse la sortie de 2 %, quel que soit le gain","Est compensé par un gain élevé","N’a aucun effet","Rend la boucle instable"]'::jsonb, 0, 'La boucle rend la mesure égale à la consigne : si la mesure est fausse, la sortie l’est aussi.', 8),
    ('65013b9a-74eb-5f25-ac65-3d9c4e4ca95a'::uuid, '8e30ee83-b9be-52bb-a3ef-412abcf4b551'::uuid, 'Quelle action du correcteur annule l’erreur statique ?', 'mcq', '["L’action proportionnelle","L’action dérivée","Le point de prélèvement","L’action intégrale"]'::jsonb, 3, 'Elle accumule l’erreur tant qu’elle n’est pas nulle.', 9),
    ('d5010e8e-aaaa-5bfa-ab9b-3e3e3bccb27d'::uuid, '8e30ee83-b9be-52bb-a3ef-412abcf4b551'::uuid, 'Pour une erreur d’au plus 10 % avec un retour unitaire, il faut un gain de chaîne directe d’au moins…', 'mcq', '["9","10","1","90"]'::jsonb, 0, '1 / (1 + A) ≤ 0,1 donne A ≥ 9.', 10),
    ('80f0f60d-1831-5b69-876c-4db0165237e1'::uuid, '8e30ee83-b9be-52bb-a3ef-412abcf4b551'::uuid, 'L’effet d’une perturbation dans la boucle est réduit par la boucle fermée.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il est divisé par environ 1 + A.', 11),
    ('5bebedae-0c04-5575-9ff9-66b82b9c9dd0'::uuid, '8e30ee83-b9be-52bb-a3ef-412abcf4b551'::uuid, 'Que représente le gain statique d’un bloc ?', 'mcq', '["Sa vitesse de réponse","Le rapport sortie / entrée une fois stabilisé","Son coût","Son nombre d’entrées"]'::jsonb, 1, 'Il décrit le comportement en régime établi.', 12),
    ('a6837f86-b46e-55c4-a294-2f7c4ea1eb21'::uuid, '1770593b-cb48-5e15-8ab9-00267efd5441'::uuid, 'Quelle part de sa valeur finale un premier ordre atteint-il à t = τ ?', 'mcq', '["50 %","63 %","95 %","100 %"]'::jsonb, 1, 'C’est la définition pratique de la constante de temps.', 1),
    ('e4d0ad51-1406-5837-9d9a-f8c20b6f8f12'::uuid, '1770593b-cb48-5e15-8ab9-00267efd5441'::uuid, 'Le temps de réponse à 5 % d’un premier ordre vaut…', 'mcq', '["τ","2τ","3τ","5τ"]'::jsonb, 2, 'À 3τ, la sortie atteint 95 % de sa valeur finale.', 2),
    ('80e4a12e-d8a6-52d5-8adb-48593ea13ae3'::uuid, '1770593b-cb48-5e15-8ab9-00267efd5441'::uuid, 'Un premier ordre peut dépasser sa valeur finale.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Sa réponse indicielle monte sans jamais dépasser.', 3),
    ('49ecf6f7-8ad7-526b-b791-0caf26693ccd'::uuid, '1770593b-cb48-5e15-8ab9-00267efd5441'::uuid, 'Comment calcule-t-on le gain statique K ?', 'mcq', '["Δs / Δe en régime établi","τ × E0","La pente à l’origine","La valeur à t = τ"]'::jsonb, 0, 'C’est le rapport des variations une fois stabilisé.', 4),
    ('c80fdda2-075d-5d14-9971-675b07c48ac8'::uuid, '1770593b-cb48-5e15-8ab9-00267efd5441'::uuid, 'Où la tangente à l’origine coupe-t-elle la valeur finale ?', 'mcq', '["À t = 3τ","À t = 0","Jamais","À t = τ"]'::jsonb, 3, 'C’est la seconde méthode de lecture de τ.', 5),
    ('dcfbae93-eb7b-5b1f-b5e5-b42510df5e1c'::uuid, '1770593b-cb48-5e15-8ab9-00267efd5441'::uuid, 'Quelle est la constante de temps d’un circuit RC ?', 'mcq', '["R + C","R × C","R / C","1 / (R × C)"]'::jsonb, 1, 'Avec R en ohms et C en farads, τ est en secondes.', 6),
    ('6fb13173-cf80-50f1-b902-733ec6c1aabf'::uuid, '1770593b-cb48-5e15-8ab9-00267efd5441'::uuid, 'Un système se stabilise à 80 °C pour une puissance de 400 W, en partant de 20 °C. Son gain statique vaut…', 'mcq', '["0,2 °C/W","5 °C/W","0,15 °C/W","60 °C/W"]'::jsonb, 2, 'K = Δs / Δe = (80 − 20) / 400 = 0,15 °C/W.', 7),
    ('d21732b9-559b-5aad-a77b-2fe5fc60afa8'::uuid, '1770593b-cb48-5e15-8ab9-00267efd5441'::uuid, 'Une sortie qui atteint 95 % de sa valeur finale en 1,5 s a une constante de temps de…', 'mcq', '["0,5 s","1,5 s","4,5 s","3 s"]'::jsonb, 0, 't5% = 3τ, donc τ = 1,5 / 3 = 0,5 s.', 8),
    ('83616c3f-d667-54e7-a15b-c935cd938171'::uuid, '1770593b-cb48-5e15-8ab9-00267efd5441'::uuid, 'Si l’on double l’échelon d’entrée d’un premier ordre, sa constante de temps…', 'mcq', '["Double","Est divisée par deux","Quadruple","Ne change pas"]'::jsonb, 3, 'Seule la valeur finale double ; la rapidité reste la même.', 9),
    ('3b45a9ca-6ab3-505e-a24d-88719eea7697'::uuid, '1770593b-cb48-5e15-8ab9-00267efd5441'::uuid, 'Quelle allure trahit un modèle d’ordre au moins égal à deux ?', 'mcq', '["Une montée sans dépassement","Un dépassement suivi d’un retour","Une valeur finale nulle","Une pente initiale non nulle"]'::jsonb, 1, 'Un premier ordre ne dépasse jamais.', 10),
    ('a0ab2935-2d3d-599d-9e2b-4801b755f061'::uuid, '1770593b-cb48-5e15-8ab9-00267efd5441'::uuid, 'À t = 5τ, un premier ordre a pratiquement atteint sa valeur finale.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il en est à 99 %.', 11),
    ('7f703a65-4205-52ca-a58e-0985bdbd7ca1'::uuid, '1770593b-cb48-5e15-8ab9-00267efd5441'::uuid, 'Un moteur a K = 40 rad/s par volt. Sous 5 V, sa vitesse finale vaut…', 'mcq', '["8 rad/s","45 rad/s","200 rad/s","35 rad/s"]'::jsonb, 2, 's_final = K × E0 = 40 × 5 = 200 rad/s.', 12),
    ('6cddc818-f3af-54e7-a07d-6814162d50e0'::uuid, 'eb3b1141-68d2-574e-af23-0207b2484fcf'::uuid, 'Un capteur de fin de course est un capteur…', 'mcq', '["Analogique","Numérique à liaison série","Tout ou rien","De température"]'::jsonb, 2, 'Il ne délivre que deux états : atteint ou non atteint.', 1),
    ('88adeeb1-6300-544b-848e-099b29d7b507'::uuid, 'eb3b1141-68d2-574e-af23-0207b2484fcf'::uuid, 'Que vaut le quantum d’un CAN 8 bits de pleine échelle 5 V ?', 'mcq', '["Environ 19,5 mV","5 mV","0,625 V","40 mV"]'::jsonb, 0, 'q = 5 / 2^8 = 5 / 256 ≈ 19,5 mV.', 2),
    ('f69221c7-bf39-5ce2-80b7-be332d506d1a'::uuid, 'eb3b1141-68d2-574e-af23-0207b2484fcf'::uuid, 'Combien de niveaux distingue un CAN 12 bits ?', 'mcq', '["12","1 024","144","4 096"]'::jsonb, 3, '2^12 = 4 096 niveaux.', 3),
    ('0c82112d-bfde-5ed5-a0b6-49a3363db2d6'::uuid, 'eb3b1141-68d2-574e-af23-0207b2484fcf'::uuid, 'La résolution d’un capteur garantit sa précision.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On peut afficher beaucoup de chiffres et se tromper largement.', 4),
    ('003df13b-52ec-5ca2-afcd-1b1b9d0cb3c6'::uuid, 'eb3b1141-68d2-574e-af23-0207b2484fcf'::uuid, 'Que désigne la sensibilité d’un capteur ?', 'mcq', '["La variation de sa sortie pour une variation unitaire de la grandeur","Sa plage de mesure","Son prix","Sa durée de vie"]'::jsonb, 0, 'Par exemple 10 mV par degré Celsius.', 5),
    ('a1cda43a-714b-51e8-bb1a-47fcab0f4d8d'::uuid, 'eb3b1141-68d2-574e-af23-0207b2484fcf'::uuid, 'Pourquoi amplifie-t-on le signal d’un capteur avant le CAN ?', 'mcq', '["Pour réduire le bruit à zéro","Pour occuper toute la plage du convertisseur et gagner en résolution","Pour changer la grandeur mesurée","Pour alimenter le capteur"]'::jsonb, 1, 'Un signal qui n’utilise qu’une petite partie de la plage gaspille des niveaux.', 6),
    ('7607ccd2-fda1-511b-b2dc-64e6fd94f6d6'::uuid, 'eb3b1141-68d2-574e-af23-0207b2484fcf'::uuid, 'Un codeur de 1 000 impulsions par tour a une résolution angulaire de…', 'mcq', '["1°","0,1°","0,36°","3,6°"]'::jsonb, 2, '360 / 1 000 = 0,36°.', 7),
    ('4dc88dc0-edb5-5c97-bd66-6f00949d767e'::uuid, 'eb3b1141-68d2-574e-af23-0207b2484fcf'::uuid, 'À quoi servent les deux voies décalées d’un codeur incrémental ?', 'mcq', '["À doubler la tension","À mesurer la température","À réduire la consommation","À connaître le sens de rotation"]'::jsonb, 3, 'L’ordre dans lequel les voies changent d’état donne le sens.', 8),
    ('1e3c2b9b-d1b6-5649-ab1a-f06b4d0c5533'::uuid, 'eb3b1141-68d2-574e-af23-0207b2484fcf'::uuid, 'Que se passe-t-il si le signal dépasse la pleine échelle du CAN ?', 'mcq', '["Le convertisseur sature et renvoie toujours la valeur maximale","La résolution s’améliore","Le capteur s’éteint","Rien de particulier"]'::jsonb, 0, 'Au-delà de la pleine échelle, toutes les valeurs donnent le même nombre.', 9),
    ('1b82037d-1c0f-5490-9a91-dc26d14cfe9e'::uuid, 'eb3b1141-68d2-574e-af23-0207b2484fcf'::uuid, 'Quelle étape du conditionnement élimine les parasites ?', 'mcq', '["L’amplification","La conversion","Le filtrage","Le codage"]'::jsonb, 2, 'Un filtre atténue les variations rapides indésirables.', 10),
    ('ca478b5a-4248-5db5-a09e-3b7cd3adbaea'::uuid, 'eb3b1141-68d2-574e-af23-0207b2484fcf'::uuid, 'Une thermistance est un capteur analogique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Sa résistance varie continûment avec la température.', 11),
    ('7c4e65bf-d732-5ab7-b2fa-5eb7187dfdc1'::uuid, 'eb3b1141-68d2-574e-af23-0207b2484fcf'::uuid, 'Un CAN 10 bits de 5 V reçoit 2,5 V. Le nombre obtenu vaut environ…', 'mcq', '["250","512","1 023","2 500"]'::jsonb, 1, 'N = 2,5 / (5 / 1 024) = 512.', 12),
    ('450ec4f1-ec59-5218-ba8c-8fbce9dc73ab'::uuid, '151dd13f-51ac-545d-a3c2-51c86882a4d7'::uuid, 'Dans une liaison série, les bits sont envoyés…', 'mcq', '["Tous en même temps","L’un après l’autre sur un même fil","Sans aucun fil","Uniquement la nuit"]'::jsonb, 1, 'C’est ce qui permet de n’utiliser que quelques fils.', 1),
    ('899e7840-108f-508a-8617-bf98bb744c58'::uuid, '151dd13f-51ac-545d-a3c2-51c86882a4d7'::uuid, 'Quels fils utilise le bus I2C ?', 'mcq', '["SDA et SCL","TX et RX","MOSI et MISO","CS et SCK uniquement"]'::jsonb, 0, 'Données et horloge, partagés par tous les composants du bus.', 2),
    ('022b836a-c7f5-5448-904f-e7724bd44bb4'::uuid, '151dd13f-51ac-545d-a3c2-51c86882a4d7'::uuid, 'Comment un maître I2C désigne-t-il l’esclave avec lequel il veut parler ?', 'mcq', '["Par un fil de sélection dédié","Par la couleur du fil","Par son adresse","Par la tension d’alimentation"]'::jsonb, 2, 'Chaque esclave a une adresse unique sur le bus.', 3),
    ('4215c1e0-e776-5a00-b118-d3f0709838e1'::uuid, '151dd13f-51ac-545d-a3c2-51c86882a4d7'::uuid, 'Une liaison UART est…', 'mcq', '["Synchrone","Parallèle","Sans fil","Asynchrone"]'::jsonb, 3, 'Aucune horloge n’est transmise : les deux côtés conviennent du débit.', 4),
    ('7ccce18f-886f-5163-a4e4-88604f5d844e'::uuid, '151dd13f-51ac-545d-a3c2-51c86882a4d7'::uuid, 'Pour relier deux cartes en UART, on relie TX à TX et RX à RX.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On croise : le TX de l’une va sur le RX de l’autre.', 5),
    ('f0a05ff3-17ed-511f-b4dc-009880856d92'::uuid, '151dd13f-51ac-545d-a3c2-51c86882a4d7'::uuid, 'Combien de bits faut-il au minimum pour envoyer un octet en UART (8 bits, sans parité, 1 stop) ?', 'mcq', '["8","9","10","16"]'::jsonb, 2, 'Un bit de départ, huit de données, un bit d’arrêt.', 6),
    ('2f079fd3-4331-5d51-a864-0365646aa6f8'::uuid, '151dd13f-51ac-545d-a3c2-51c86882a4d7'::uuid, 'Quel bus est full duplex et utilise un fil de sélection par esclave ?', 'mcq', '["SPI","I2C","UART","Aucun"]'::jsonb, 0, 'MOSI et MISO circulent en même temps ; CS choisit l’esclave.', 7),
    ('b0cea328-7414-59fa-95cf-59b28af49457'::uuid, '151dd13f-51ac-545d-a3c2-51c86882a4d7'::uuid, 'Combien de temps faut-il pour envoyer 1 920 bits à 9 600 bauds ?', 'mcq', '["2 s","0,5 s","5 s","0,2 s"]'::jsonb, 3, '1 920 / 9 600 = 0,2 s.', 8),
    ('5862cf17-fff0-5c2a-abae-e699a4160ba5'::uuid, '151dd13f-51ac-545d-a3c2-51c86882a4d7'::uuid, 'À quoi sert le bit de parité ?', 'mcq', '["À détecter une erreur simple de transmission","À augmenter le débit","À choisir l’esclave","À cadencer l’horloge"]'::jsonb, 0, 'Il indique si le nombre de 1 transmis est pair ou impair.', 9),
    ('fc58116b-0409-5e24-a0bc-bb06a21f9ba2'::uuid, '151dd13f-51ac-545d-a3c2-51c86882a4d7'::uuid, 'Pourquoi choisir I2C plutôt que SPI ?', 'mcq', '["Parce qu’il est plus rapide","Parce qu’il n’utilise que deux fils pour tout le bus","Parce qu’il n’a pas besoin d’horloge","Parce qu’il est asynchrone"]'::jsonb, 1, 'Il économise les broches ; SPI économise le temps.', 10),
    ('bd341aff-07c8-563f-94bd-71233b08770e'::uuid, '151dd13f-51ac-545d-a3c2-51c86882a4d7'::uuid, 'Le débit utile d’une liaison est égal à son débit brut.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Les bits d’encadrement et d’adresse ne transportent pas de données.', 11),
    ('a3c47d39-b9f3-586c-83de-873e995c10f2'::uuid, '151dd13f-51ac-545d-a3c2-51c86882a4d7'::uuid, 'Dans une liaison synchrone, qu’est-ce qui cadence les bits ?', 'mcq', '["Le bit d’arrêt","La parité","Une horloge partagée","L’adresse de l’esclave"]'::jsonb, 2, 'SCL en I2C, SCK en SPI.', 12),
    ('3865cd40-7947-5463-bf57-3fe54920297e'::uuid, 'eba514e4-0244-52bd-8e57-19c0c787959b'::uuid, 'Que représente un état dans un diagramme d’états ?', 'mcq', '["Une action instantanée","Une situation stable du système","Un capteur","Un fil de communication"]'::jsonb, 1, 'Le système reste dans un état jusqu’à ce qu’une transition soit franchie.', 1),
    ('df6b02fc-4ad5-565e-9ae2-5561cc25260d'::uuid, 'eba514e4-0244-52bd-8e57-19c0c787959b'::uuid, 'Comment s’écrit une condition de garde ?', 'mcq', '["Entre crochets","Entre guillemets","Après une barre oblique","En majuscules"]'::jsonb, 0, 'Par exemple [obstacle = faux].', 2),
    ('011d70b2-be5c-5b61-8296-fa794dd920b4'::uuid, 'eba514e4-0244-52bd-8e57-19c0c787959b'::uuid, 'Dans « appui [porte fermée] / allumer voyant », que désigne « allumer voyant » ?', 'mcq', '["L’événement","La garde","L’état","L’effet de la transition"]'::jsonb, 3, 'L’effet suit la barre oblique.', 3),
    ('7b8b6c3e-207e-59ae-9e0d-331e4b8779d4'::uuid, 'eba514e4-0244-52bd-8e57-19c0c787959b'::uuid, 'Quelles sont les trois étapes d’un tour de boucle d’un programme embarqué ?', 'mcq', '["Lire, décider, commander","Dessiner, coder, vendre","Compiler, effacer, redémarrer","Mesurer, stocker, imprimer"]'::jsonb, 0, 'Lecture des entrées, choix de l’état, commande des sorties.', 4),
    ('dd730700-b29f-5408-a543-44bd8e61359a'::uuid, 'eba514e4-0244-52bd-8e57-19c0c787959b'::uuid, 'Quand utiliser une interruption plutôt que la scrutation ?', 'mcq', '["Pour lire un bouton une fois par jour","Pour afficher un message","Pour un événement bref ou urgent","Jamais"]'::jsonb, 2, 'L’interruption réagit même si la boucle est occupée ailleurs.', 5),
    ('43b92836-614e-5a75-a02f-a14e66b5a250'::uuid, 'eba514e4-0244-52bd-8e57-19c0c787959b'::uuid, 'Un bouton mécanique peut produire plusieurs impulsions pour un seul appui.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est le rebond ; on le traite par un anti-rebond.', 6),
    ('fc9e1348-076d-59d0-9c37-e4038d9183ae'::uuid, 'eba514e4-0244-52bd-8e57-19c0c787959b'::uuid, 'Dans le portail, quelle transition traduit une exigence de sécurité ?', 'mcq', '["Fermé vers Ouverture sur appui","Fermeture vers Ouverture si obstacle détecté","Ouvert vers Fermeture après 30 s","Ouverture vers Ouvert en fin de course"]'::jsonb, 1, 'Le portail doit se rouvrir au lieu d’écraser l’obstacle.', 7),
    ('6ace5360-e23d-579c-a598-cb5b5e16c5da'::uuid, 'eba514e4-0244-52bd-8e57-19c0c787959b'::uuid, 'Comment représente-t-on l’état initial ?', 'mcq', '["Par un carré vide","Par une flèche en pointillés","Par une étoile","Par un disque noir"]'::jsonb, 3, 'C’est de là que part la première transition.', 8),
    ('dde31600-6ce6-5606-b82d-2d67ca733b1f'::uuid, 'eba514e4-0244-52bd-8e57-19c0c787959b'::uuid, 'Un diagramme d’états se traduit facilement en structure de choix dans un programme.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Chaque état devient un cas, chaque transition un test.', 9),
    ('f1543163-8311-553a-87d2-860a0044f7f9'::uuid, 'eba514e4-0244-52bd-8e57-19c0c787959b'::uuid, 'Que se passe-t-il pour une transition sans événement ni garde ?', 'mcq', '["Elle ne se franchit jamais","Elle se franchit immédiatement","Elle bloque le programme","Elle efface l’état"]'::jsonb, 1, 'Rien ne la retient : elle est franchie dès que l’état est atteint.', 10),
    ('d5324449-1533-593f-b2d4-7da6fa49c11a'::uuid, 'eba514e4-0244-52bd-8e57-19c0c787959b'::uuid, 'Que signifie « entry » dans un état ?', 'mcq', '["L’action exécutée en sortant de l’état","Le nom du capteur","L’action exécutée en entrant dans l’état","La garde de la transition"]'::jsonb, 2, 'On trouve aussi « do » (pendant) et « exit » (à la sortie).', 11),
    ('d7f31c81-0642-5a25-b228-65b3710fe72a'::uuid, 'eba514e4-0244-52bd-8e57-19c0c787959b'::uuid, 'Pourquoi lire les impulsions d’un codeur rapide par interruption ?', 'mcq', '["Pour économiser de la mémoire","Pour changer de couleur","Parce que la scrutation est interdite","Pour ne manquer aucune impulsion"]'::jsonb, 3, 'Une impulsion brève peut passer entre deux lectures par scrutation.', 12),
    ('432e06b7-3b61-5508-8110-26c5acdda68e'::uuid, '5fa567b8-0094-5edc-8528-d0fc3b4ab369'::uuid, 'Quel est le rôle d’une passerelle dans une solution connectée ?', 'mcq', '["Mesurer la température","Relayer les messages radio vers Internet","Afficher les données","Recharger les objets"]'::jsonb, 1, 'Elle fait le lien entre le réseau radio local et le serveur.', 1),
    ('6de4938b-32b1-52f8-aa65-4ba2cb50de40'::uuid, '5fa567b8-0094-5edc-8528-d0fc3b4ab369'::uuid, 'Quelle technologie offre une portée de plusieurs kilomètres à très faible consommation ?', 'mcq', '["Le Wi-Fi","Le Bluetooth Low Energy","LoRa","L’USB"]'::jsonb, 2, 'En échange, son débit est très faible.', 2),
    ('60496af4-840a-5fa1-9925-1aae9e697cfa'::uuid, '5fa567b8-0094-5edc-8528-d0fc3b4ab369'::uuid, 'Longue portée et faible consommation se paient en…', 'mcq', '["Débit","Poids","Couleur","Tension"]'::jsonb, 0, 'On ne peut pas avoir à la fois portée, débit et sobriété.', 3),
    ('fe2db7e7-af22-53c3-a917-b9ebf083d60e'::uuid, '5fa567b8-0094-5edc-8528-d0fc3b4ab369'::uuid, 'Pourquoi un objet connecté passe-t-il l’essentiel de son temps en veille ?', 'mcq', '["Pour chauffer moins","Pour recevoir plus de messages","Pour augmenter sa portée","Pour économiser son énergie"]'::jsonb, 3, 'La consommation moyenne dépend surtout du temps passé éveillé.', 4),
    ('f3b1c5c3-aa38-5a56-a909-19a990afba9e'::uuid, '5fa567b8-0094-5edc-8528-d0fc3b4ab369'::uuid, 'Dans un protocole de publication / abonnement, l’objet doit connaître tous ses destinataires.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il publie sur un sujet auprès du courtier ; les abonnés reçoivent sans qu’il les connaisse.', 5),
    ('79f96b66-c244-5073-80a1-4637c23be60b'::uuid, '5fa567b8-0094-5edc-8528-d0fc3b4ab369'::uuid, 'Comment s’appelle l’intermédiaire qui reçoit et redistribue les messages publiés ?', 'mcq', '["Le courtier (broker)","Le capteur","Le quantum","Le pont en H"]'::jsonb, 0, 'Il fait circuler chaque message vers les abonnés du sujet.', 6),
    ('48d476ac-3e46-5950-9a10-6c787497cdbc'::uuid, '5fa567b8-0094-5edc-8528-d0fc3b4ab369'::uuid, 'Quelle parade protège contre l’interception des données ?', 'mcq', '["Un mot de passe par défaut","Une pile plus grosse","Le chiffrement des échanges","Une antenne plus longue"]'::jsonb, 2, 'Les données interceptées restent illisibles sans la clé.', 7),
    ('e5ce8bdd-99c9-517d-a540-7f4346244479'::uuid, '5fa567b8-0094-5edc-8528-d0fc3b4ab369'::uuid, 'Un objet consomme 10 mA pendant 6 s par minute, et rien le reste du temps. Sa consommation moyenne vaut…', 'mcq', '["10 mA","0,6 mA","6 mA","1 mA"]'::jsonb, 3, '10 × 6 / 60 = 1 mA.', 8),
    ('473b3e1e-b80f-5896-bcfb-f05cd0993c69'::uuid, '5fa567b8-0094-5edc-8528-d0fc3b4ab369'::uuid, 'Le Wi-Fi est la technologie la plus sobre pour un capteur sur pile.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Son débit est élevé, mais sa consommation aussi.', 9),
    ('0dd39e5b-c897-59c6-a421-9d26f5593a66'::uuid, '5fa567b8-0094-5edc-8528-d0fc3b4ab369'::uuid, 'Une pile de 1 000 mAh alimente un objet qui consomme en moyenne 0,1 mA. Son autonomie vaut…', 'mcq', '["10 000 h","100 h","1 000 h","100 000 h"]'::jsonb, 0, '1 000 / 0,1 = 10 000 h, soit plus d’un an.', 10),
    ('70ebc915-7eca-5d4d-b0fa-a57bb4130c9c'::uuid, '5fa567b8-0094-5edc-8528-d0fc3b4ab369'::uuid, 'Pourquoi prévoir des mises à jour à distance ?', 'mcq', '["Pour corriger une faille découverte après la vente","Pour augmenter la portée radio","Pour recharger la pile","Pour changer de sujet MQTT"]'::jsonb, 0, 'Un objet qu’on ne peut plus corriger reste vulnérable toute sa vie.', 11),
    ('e6eaa79c-dc15-53ee-9944-0831de96e20d'::uuid, '5fa567b8-0094-5edc-8528-d0fc3b4ab369'::uuid, 'La consommation en veille peut peser lourd dans la consommation moyenne.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’objet y passe presque tout son temps.', 12),
    ('c4d743d5-10fc-57c3-ac37-d1bd5087acac'::uuid, '58f2f634-d6e0-51fc-bcf0-7b727d150c8f'::uuid, 'Que fournit-on à un algorithme d’apprentissage supervisé ?', 'mcq', '["Des règles écrites à la main","Des exemples étiquetés","Uniquement des images floues","Un schéma électrique"]'::jsonb, 1, 'Chaque exemple est accompagné de la bonne réponse.', 1),
    ('04d78027-0f4e-52de-a181-0d3f9195ac0b'::uuid, '58f2f634-d6e0-51fc-bcf0-7b727d150c8f'::uuid, 'Pourquoi garde-t-on un jeu de test séparé ?', 'mcq', '["Pour évaluer le modèle sur des données qu’il n’a jamais vues","Pour entraîner plus vite","Pour réduire la taille du modèle","Pour supprimer les erreurs"]'::jsonb, 0, 'Sinon, le modèle se note sur ce qu’il a appris par cœur.', 2),
    ('da485f7f-3449-511d-b348-d72fc76c2198'::uuid, '58f2f634-d6e0-51fc-bcf0-7b727d150c8f'::uuid, 'Un modèle excellent à l’entraînement mais mauvais au test souffre de…', 'mcq', '["Biais de mesure","Sous-alimentation","Surapprentissage","Saturation du CAN"]'::jsonb, 2, 'Il a appris les exemples, bruit compris, au lieu de la règle générale.', 3),
    ('a291a63a-d1b5-5ac0-940e-32e3cca9b71d'::uuid, '58f2f634-d6e0-51fc-bcf0-7b727d150c8f'::uuid, 'Comment l’algorithme des k plus proches voisins classe-t-il un nouvel exemple ?', 'mcq', '["Au hasard","Selon le premier exemple de la liste","Selon la moyenne des étiquettes","Selon la classe majoritaire parmi ses k voisins les plus proches"]'::jsonb, 3, 'Il compare les distances aux exemples connus.', 4),
    ('9edeacff-1014-56bd-83be-97720dc2a2d2'::uuid, '58f2f634-d6e0-51fc-bcf0-7b727d150c8f'::uuid, 'Pourquoi choisit-on souvent k impair avec deux classes ?', 'mcq', '["Pour éviter les égalités de vote","Pour aller plus vite","Parce que c’est obligatoire","Pour réduire le biais"]'::jsonb, 0, 'Avec k pair, le vote peut se partager à égalité.', 5),
    ('0dc82bb5-5d96-58c5-ad78-e8c1d69eac8b'::uuid, '58f2f634-d6e0-51fc-bcf0-7b727d150c8f'::uuid, 'Un biais dans les données d’entraînement peut produire des erreurs systématiques.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Si certains cas manquent, le modèle se trompe précisément sur eux.', 6),
    ('40a88566-2c8c-50a4-8888-49fd54913ccb'::uuid, '58f2f634-d6e0-51fc-bcf0-7b727d150c8f'::uuid, 'Dans un tri de pièces, que désigne un faux négatif ?', 'mcq', '["Une pièce conforme déclarée défectueuse","Une pièce défectueuse déclarée conforme","Une pièce conforme déclarée conforme","Une pièce sans étiquette"]'::jsonb, 1, 'C’est la pièce défectueuse que le modèle a laissé passer.', 7),
    ('a2d22f19-1e10-5fa6-9f65-0ed45bd71c1a'::uuid, '58f2f634-d6e0-51fc-bcf0-7b727d150c8f'::uuid, 'Sur 200 pièces, un modèle en classe correctement 170. Son exactitude vaut…', 'mcq', '["17 %","30 %","70 %","85 %"]'::jsonb, 3, '170 / 200 = 0,85.', 8),
    ('ffbcd34f-54bb-5319-9514-7a6d340adc57'::uuid, '58f2f634-d6e0-51fc-bcf0-7b727d150c8f'::uuid, 'Quand l’apprentissage automatique est-il plus adapté qu’un programme classique ?', 'mcq', '["Quand la règle est simple et connue","Quand on n’a aucune donnée","Quand la règle est trop complexe à écrire","Jamais dans l’industrie"]'::jsonb, 2, 'On fait alors apprendre la règle à partir d’exemples.', 9),
    ('40628bf8-f70c-5eca-baec-fdd6a346746b'::uuid, '58f2f634-d6e0-51fc-bcf0-7b727d150c8f'::uuid, 'Un modèle évalué sur ses propres données d’entraînement donne une mesure fiable de ses performances.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il faut un jeu de test indépendant.', 10),
    ('d56d7453-1b27-58be-812d-2e367270a020'::uuid, '58f2f634-d6e0-51fc-bcf0-7b727d150c8f'::uuid, 'Regrouper des profils d’usage sans étiquette relève de l’apprentissage…', 'mcq', '["Supervisé","Par renforcement uniquement","Manuel","Non supervisé"]'::jsonb, 3, 'Aucune bonne réponse n’est fournie : le modèle cherche des ressemblances.', 11),
    ('1e10257f-a980-5b3b-a83c-a2fc41b4ed82'::uuid, '58f2f634-d6e0-51fc-bcf0-7b727d150c8f'::uuid, 'Pourquoi accepter parfois moins d’exactitude pour réduire les faux négatifs ?', 'mcq', '["Parce qu’un défaut livré au client coûte plus cher qu’une revérification","Parce que l’exactitude ne compte jamais","Pour accélérer l’entraînement","Pour réduire la taille des données"]'::jsonb, 0, 'Toutes les erreurs n’ont pas le même coût.', 12),
    ('74c91f59-cc99-51e4-a674-4091803cc698'::uuid, '05ed8a53-01fb-52bf-bd43-105984dbf243'::uuid, 'Combien de temps dure l’épreuve écrite de spécialité SI ?', 'mcq', '["2 heures","3 heures","4 heures","6 heures"]'::jsonb, 2, 'Environ 3 heures de SI et 1 heure de sciences physiques.', 1),
    ('8f388cdc-ee82-5742-801d-3d7842ae9379'::uuid, '05ed8a53-01fb-52bf-bd43-105984dbf243'::uuid, 'Quelle pondération reçoit la partie sciences de l’ingénieur ?', 'mcq', '["0,75","0,25","0,5","1"]'::jsonb, 0, 'La partie sciences physiques compte pour 0,25.', 2),
    ('0c25ac79-69d5-5d4b-9d6a-7ab403620651'::uuid, '05ed8a53-01fb-52bf-bd43-105984dbf243'::uuid, 'Quel est le coefficient de la spécialité SI au baccalauréat ?', 'mcq', '["6","10","12","16"]'::jsonb, 3, 'Comme toutes les spécialités évaluées en épreuve écrite terminale.', 3),
    ('85978922-957b-5067-b03c-8f7589738b5d'::uuid, '05ed8a53-01fb-52bf-bd43-105984dbf243'::uuid, 'Combien d’exercices comporte la partie sciences physiques ?', 'mcq', '["Un seul","Deux exercices indépendants","Quatre exercices liés","Aucun"]'::jsonb, 1, 'Deux exercices indépendants l’un de l’autre.', 4),
    ('9020a05f-a8c8-50be-b969-2020434116b1'::uuid, '05ed8a53-01fb-52bf-bd43-105984dbf243'::uuid, 'Que doit contenir une réponse à une question « Conclure » ?', 'mcq', '["Un chiffre seul","Un schéma sans légende","Une comparaison du résultat avec l’exigence du cahier des charges","La formule sans application numérique"]'::jsonb, 2, 'On compare, on tranche, et si possible on explique l’écart.', 5),
    ('f23fe954-7ab4-5cce-be54-ba5c0d5372b1'::uuid, '05ed8a53-01fb-52bf-bd43-105984dbf243'::uuid, 'Les parties de la partie SI sont souvent en grande partie indépendantes.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'On peut donc avancer même si une question bloque.', 6),
    ('0a102573-2dda-586a-b13a-c3d4cf0e9026'::uuid, '05ed8a53-01fb-52bf-bd43-105984dbf243'::uuid, 'Que faire dans les dix premières minutes ?', 'mcq', '["Commencer par la dernière question","Recopier le sujet","Remplir les documents réponses au hasard","Parcourir tout le sujet et repérer les documents réponses"]'::jsonb, 3, 'On organise son temps avant de s’y lancer.', 7),
    ('47868131-7114-50b4-9b19-9fabcd84720a'::uuid, '05ed8a53-01fb-52bf-bd43-105984dbf243'::uuid, 'Pourquoi écrire la formule littérale avant l’application numérique ?', 'mcq', '["Parce que le raisonnement est noté même si le calcul dérape","Pour occuper la copie","Parce que les nombres sont interdits","Pour éviter les unités"]'::jsonb, 0, 'Le correcteur voit ce que tu as compris.', 8),
    ('1e52bd74-0a9b-569e-a34b-b2bfeb106ad3'::uuid, '05ed8a53-01fb-52bf-bd43-105984dbf243'::uuid, 'Un document réponse rempli mais non rendu est tout de même corrigé.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il doit être joint à la copie, sinon ses points sont perdus.', 9),
    ('5cf94bdb-fea1-5d08-872f-34f42d9012d6'::uuid, '05ed8a53-01fb-52bf-bd43-105984dbf243'::uuid, 'Un élève obtient 12/20 en SI et 16/20 en physique. Sa note d’épreuve vaut…', 'mcq', '["14/20","13/20","12/20","15/20"]'::jsonb, 1, '0,75 × 12 + 0,25 × 16 = 9 + 4 = 13.', 10),
    ('4c9c6d7f-e389-515b-b3d4-dfc12d2d7966'::uuid, '05ed8a53-01fb-52bf-bd43-105984dbf243'::uuid, 'Avant un calcul, une vitesse lue en tr/min doit généralement être convertie en…', 'mcq', '["km/h","rad/s","tr/s²","m"]'::jsonb, 1, 'Les formules de puissance et d’énergie utilisent les rad/s.', 11),
    ('e4802a8b-1961-5b34-b8a5-b6e1a015027a'::uuid, '05ed8a53-01fb-52bf-bd43-105984dbf243'::uuid, 'Sur quoi porte la partie SI du sujet ?', 'mcq', '["Un produit réel qui répond à un besoin","Une question de cours isolée","Un texte philosophique","Un programme à écrire de A à Z"]'::jsonb, 0, 'On l’analyse, on le modélise et on conclut sur ses performances.', 12),
    ('52782ec1-0ecd-5f29-8feb-c4874fc9794a'::uuid, '8dd5211e-f659-5a2d-bc45-a3563ebb257b'::uuid, 'Quelle durée le programme prévoit-il pour le projet de Terminale ?', 'mcq', '["12 heures","24 heures","48 heures","100 heures"]'::jsonb, 2, 'En Première, le projet est plus court.', 1),
    ('dffc6785-b468-5a50-947a-e379b5454d1b'::uuid, '8dd5211e-f659-5a2d-bc45-a3563ebb257b'::uuid, 'Combien de questions l’élève prépare-t-il pour le Grand oral ?', 'mcq', '["Une","Deux","Trois","Cinq"]'::jsonb, 1, 'Le jury en choisit une des deux.', 2),
    ('fee35f03-958a-5999-bba4-9ebe9c8ff2a7'::uuid, '8dd5211e-f659-5a2d-bc45-a3563ebb257b'::uuid, 'Combien de temps dure la présentation initiale du Grand oral ?', 'mcq', '["5 minutes","10 minutes","20 minutes","2 minutes"]'::jsonb, 0, 'Elle se fait debout et sans notes.', 3),
    ('fb52f816-79a0-52c0-bb51-7d6c5a7cb443'::uuid, '8dd5211e-f659-5a2d-bc45-a3563ebb257b'::uuid, 'Combien de temps dure l’échange avec le jury qui suit la présentation ?', 'mcq', '["5 minutes","20 minutes","15 minutes","10 minutes"]'::jsonb, 3, 'Puis viennent 5 minutes sur le projet d’orientation.', 4),
    ('8232a4fd-b5df-5786-8a94-a56a47fd99ed'::uuid, '8dd5211e-f659-5a2d-bc45-a3563ebb257b'::uuid, 'Quel est le coefficient du Grand oral dans la voie générale ?', 'mcq', '["2","6","10","16"]'::jsonb, 2, 'C’est l’une des épreuves les plus lourdes du baccalauréat.', 5),
    ('93dd81e8-f730-592b-a13d-99e6796a626b'::uuid, '8dd5211e-f659-5a2d-bc45-a3563ebb257b'::uuid, 'Le support préparé pendant les 20 minutes de préparation est évalué.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il peut aider, mais il n’est pas noté.', 6),
    ('9c643e19-5eb6-5a5a-9586-27cfe37cf35c'::uuid, '8dd5211e-f659-5a2d-bc45-a3563ebb257b'::uuid, 'Qu’est-ce qu’une bonne question de Grand oral ?', 'mcq', '["Une question qui pose un problème et appelle une réponse argumentée","Une définition à réciter","Le titre du rapport de projet","Une question sans lien avec les spécialités"]'::jsonb, 0, 'Elle s’appuie sur le programme et se traite en cinq minutes.', 7),
    ('59f61dbf-3200-5b52-9598-5ea929041fac'::uuid, '8dd5211e-f659-5a2d-bc45-a3563ebb257b'::uuid, 'À quoi servent les revues de projet ?', 'mcq', '["À noter le cahier des charges","À remplacer les essais","À choisir le jury","À faire le point sur l’avancement, les écarts et la suite"]'::jsonb, 3, 'Chacun y présente sa part et ce qui reste à faire.', 8),
    ('3ec73e75-0960-5696-bd13-8e0d97bf3223'::uuid, '8dd5211e-f659-5a2d-bc45-a3563ebb257b'::uuid, 'Que doit pouvoir expliquer chaque membre de l’équipe ?', 'mcq', '["Uniquement le travail des autres","Sa propre part et son articulation avec le reste du projet","Le prix du prototype","Rien, seul le chef de projet parle"]'::jsonb, 1, 'C’est ce qu’on attend en revue comme à l’oral.', 9),
    ('76a223e6-16c9-5787-9f87-6585833e0241'::uuid, '8dd5211e-f659-5a2d-bc45-a3563ebb257b'::uuid, 'Au Grand oral, il est conseillé de réciter le rapport de projet.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Le jury évalue le raisonnement et la parole, pas une récitation.', 10),
    ('800ba462-b20d-5ec1-b125-1a54e391abad'::uuid, '8dd5211e-f659-5a2d-bc45-a3563ebb257b'::uuid, 'Sur quoi portent les 5 dernières minutes du Grand oral ?', 'mcq', '["Le projet d’orientation","Une question de physique","La correction de l’écrit","Le règlement du lycée"]'::jsonb, 0, 'Tu y expliques comment ta question s’inscrit dans ton parcours.', 11),
    ('bdd9f99e-7924-5a35-b313-b0fec5574809'::uuid, '8dd5211e-f659-5a2d-bc45-a3563ebb257b'::uuid, 'Le projet mêle réalisations numériques et matérielles.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Modèles et simulations d’un côté, prototype de l’autre.', 12),
    ('a0cc6c57-1fbf-5558-839a-0c1bdc3c0d5c'::uuid, '5ff15611-a3c9-5e7d-8fdc-9b4ef4d343d7'::uuid, 'Combien de champs d’apprentissage compte le programme d’EPS du lycée ?', 'mcq', '["Trois","Quatre","Cinq","Six"]'::jsonb, 2, 'Le cinquième, orienté vers l’entretien de soi, est propre au lycée.', 1),
    ('35535720-3ef9-5278-aa1e-334838d6e5b2'::uuid, '5ff15611-a3c9-5e7d-8fdc-9b4ef4d343d7'::uuid, 'La course d’orientation relève du champ…', 'mcq', '["CA2 : adapter son déplacement à des environnements variés ou incertains","CA1 : performance maximale","CA3 : prestation vue et appréciée","CA4 : affrontement"]'::jsonb, 0, 'On y lit un milieu qu’on ne connaît pas d’avance.', 2),
    ('cb3d2774-eeee-5d6b-a144-5ab3af11a96e'::uuid, '5ff15611-a3c9-5e7d-8fdc-9b4ef4d343d7'::uuid, 'Quel champ regroupe la danse et l’acrosport ?', 'mcq', '["CA1","CA4","CA5","CA3"]'::jsonb, 3, 'La prestation y est destinée à être vue et appréciée.', 3),
    ('32ad00ce-317d-5a70-8a36-9bd9f4f28c7f'::uuid, '5ff15611-a3c9-5e7d-8fdc-9b4ef4d343d7'::uuid, 'Le badminton relève du champ CA4.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est un affrontement individuel, où l’on cherche à gagner le rapport de force.', 4),
    ('15b17666-969c-5997-8291-a24e23fa0379'::uuid, '5ff15611-a3c9-5e7d-8fdc-9b4ef4d343d7'::uuid, 'Que vise le champ CA5 ?', 'mcq', '["Battre un adversaire","Développer ses ressources et s’entretenir selon un objectif choisi","Réaliser un spectacle","Parcourir un milieu inconnu"]'::jsonb, 1, 'On s’y transforme soi-même, sans chercher à battre quelqu’un.', 5),
    ('42c89ae9-e354-515a-a093-0e947c9f158a'::uuid, '5ff15611-a3c9-5e7d-8fdc-9b4ef4d343d7'::uuid, 'Combien d’attendus de fin de lycée (AFL) le programme fixe-t-il par champ ?', 'mcq', '["Un","Deux","Quatre","Trois"]'::jsonb, 3, 'AFL1, AFL2 et AFL3.', 6),
    ('bc801a98-cae9-57bb-b144-7311e83d244c'::uuid, '5ff15611-a3c9-5e7d-8fdc-9b4ef4d343d7'::uuid, 'Sur quoi porte principalement l’AFL1 ?', 'mcq', '["La motricité et l’efficacité dans l’action","Les rôles sociaux","L’alimentation","Le règlement intérieur"]'::jsonb, 0, 'C’est l’attendu « agir » : la performance, la technique, la tactique.', 7),
    ('032d9751-d86a-5d43-825d-116e6d66ca71'::uuid, '5ff15611-a3c9-5e7d-8fdc-9b4ef4d343d7'::uuid, 'Que vise l’AFL3 ?', 'mcq', '["La vitesse maximale","La souplesse","Les rôles et la vie avec les autres","Le choix de la tenue"]'::jsonb, 2, 'Juger, arbitrer, observer, être partenaire.', 8),
    ('fb1642c1-2381-5dc4-bbbd-b6a47cca90da'::uuid, '5ff15611-a3c9-5e7d-8fdc-9b4ef4d343d7'::uuid, 'Lequel de ces objectifs figure parmi les cinq objectifs généraux du programme ?', 'mcq', '["Gagner une médaille","Construire durablement sa santé","Devenir professionnel","Pratiquer un seul sport"]'::jsonb, 1, 'Les autres : motricité, entraînement, responsabilité, patrimoine culturel.', 9),
    ('dcaa9c52-c6ad-5af9-b6bd-133520c60478'::uuid, '5ff15611-a3c9-5e7d-8fdc-9b4ef4d343d7'::uuid, 'Le sprint et le lancer de javelot appartiennent au CA1.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'On y cherche une performance maximale mesurée.', 10),
    ('ad68e607-5d7d-5b4f-8967-412de75a7ff8'::uuid, '5ff15611-a3c9-5e7d-8fdc-9b4ef4d343d7'::uuid, 'Pourquoi le programme regroupe-t-il les activités en champs ?', 'mcq', '["Parce que les activités d’un même champ font apprendre la même chose","Pour réduire le nombre de terrains","Pour des raisons de coût","Parce que chaque champ correspond à une fédération"]'::jsonb, 0, 'Basket et badminton apprennent tous deux à conduire un affrontement.', 11),
    ('49b5f423-a478-5700-b39f-6592d61615e3'::uuid, '5ff15611-a3c9-5e7d-8fdc-9b4ef4d343d7'::uuid, 'La musculation pratiquée pour se développer selon un objectif personnel relève du…', 'mcq', '["CA1","CA3","CA4","CA5"]'::jsonb, 3, 'On y oriente son activité pour développer ses ressources.', 12),
    ('17a1daac-e9fa-599c-89e2-d2324119561a'::uuid, '8f409a8c-0ba8-5f56-84e8-7827b72cb8bf'::uuid, 'Qu’appelle-t-on la vitesse utile ?', 'mcq', '["La vitesse maximale absolue","La vitesse la plus élevée que l’on maîtrise sans dégrader son geste","La vitesse moyenne d’une classe","La vitesse de récupération"]'::jsonb, 1, 'Au-delà, la vitesse désorganise la coordination.', 1),
    ('805c2800-a3c6-546b-ad6c-9c5be4c66894'::uuid, '8f409a8c-0ba8-5f56-84e8-7827b72cb8bf'::uuid, 'Sur combien de points est noté l’AFL1 d’une épreuve de bac ?', 'mcq', '["12","8","20","6"]'::jsonb, 0, 'Les 8 autres points vont à l’AFL2 et à l’AFL3.', 2),
    ('a842555d-c43d-5175-9585-aabcfcd76aa6'::uuid, '8f409a8c-0ba8-5f56-84e8-7827b72cb8bf'::uuid, 'En CA1, l’AFL1 croise la performance avec…', 'mcq', '["La tenue vestimentaire","Le nombre de spectateurs","L’efficacité technique mesurée par un indice","La note de l’an passé"]'::jsonb, 2, 'Deux éléments, 6 points chacun.', 3),
    ('69996c51-eb41-5a0a-b5d7-d46b7787f303'::uuid, '8f409a8c-0ba8-5f56-84e8-7827b72cb8bf'::uuid, 'Quelle filière domine lors d’un effort de moins de 10 secondes ?', 'mcq', '["Aérobie","Anaérobie lactique","Aucune","Anaérobie alactique"]'::jsonb, 3, 'Elle fournit une énergie immédiate mais très brève.', 4),
    ('f1e1d1b7-7f0e-5a15-834a-f310c8b38e59'::uuid, '8f409a8c-0ba8-5f56-84e8-7827b72cb8bf'::uuid, 'Aller le plus vite possible garantit toujours la meilleure performance.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Trop de vitesse dégrade le geste : on cherche un compromis vitesse-précision.', 5),
    ('9551beec-bb6e-59da-9a4d-b86869dc135b'::uuid, '8f409a8c-0ba8-5f56-84e8-7827b72cb8bf'::uuid, 'Quel exemple est un indicateur d’indice technique ?', 'mcq', '["L’écart entre le temps sur le plat et le temps sur les haies","La couleur des pointes","La taille de l’élève","Le nombre de spectateurs"]'::jsonb, 0, 'Il révèle ce que le franchissement coûte en vitesse.', 6),
    ('2cc794dc-7844-5056-bb9e-f47db7c4d349'::uuid, '8f409a8c-0ba8-5f56-84e8-7827b72cb8bf'::uuid, 'Pourquoi récupérer plusieurs minutes entre deux essais de saut ?', 'mcq', '["Pour refroidir les muscles","Pour reconstituer l’énergie de la filière alactique","Pour allonger l’épreuve","Ce n’est pas utile"]'::jsonb, 1, 'Sans récupération, l’essai suivant sera moins explosif.', 7),
    ('5ee27f9e-e26e-52b3-9629-89a1f77182b3'::uuid, '8f409a8c-0ba8-5f56-84e8-7827b72cb8bf'::uuid, 'Sur un 400 m, que faut-il surtout gérer ?', 'mcq', '["Le départ uniquement","La répartition de l’effort","La couleur du couloir","Rien, il suffit de sprinter"]'::jsonb, 1, 'La filière lactique s’épuise : partir trop vite fait s’effondrer à la fin.', 8),
    ('67155a95-4114-5452-981f-474511cd822c'::uuid, '8f409a8c-0ba8-5f56-84e8-7827b72cb8bf'::uuid, 'Un écart plat-haies qui passe de 1,2 s à 0,9 s signifie que…', 'mcq', '["Le temps sur le plat a baissé","L’élève a fait une faute","L’efficacité technique a progressé","La performance a baissé"]'::jsonb, 2, 'Le franchissement coûte moins de vitesse.', 9),
    ('057bf103-defa-5d53-8745-2b850456441a'::uuid, '8f409a8c-0ba8-5f56-84e8-7827b72cb8bf'::uuid, 'En CA1, l’élève peut faire certains choix, comme le type de départ ou d’élan.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le référentiel prévoit des choix possibles pour l’AFL1.', 10),
    ('456dc4dd-e680-5766-af6d-4347289aac4e'::uuid, '8f409a8c-0ba8-5f56-84e8-7827b72cb8bf'::uuid, 'Quelle stratégie d’essais est conseillée ?', 'mcq', '["Tout miser sur un essai très risqué dès le début","Faire un seul essai","Ne pas s’échauffer pour garder de l’énergie","Assurer d’abord un essai sûr, puis tenter plus"]'::jsonb, 3, 'Une première marque sûre libère pour la suite.', 11),
    ('d45cb4bc-bbe6-57c5-9b1b-addb4d7a071d'::uuid, '8f409a8c-0ba8-5f56-84e8-7827b72cb8bf'::uuid, 'Comment est fixé le barème de la performance maximale ?', 'mcq', '["Par l’élève lui-même","Par l’établissement, autour d’un seuil médian national","Par tirage au sort","Par la fédération sportive"]'::jsonb, 1, 'Le seuil médian (3 points sur 6) est national, le reste du barème est construit par l’établissement.', 12),
    ('7957f56c-e8ae-5cdd-8291-fb4f4cfaa470'::uuid, '0b1e7f81-fe55-5291-bbd9-0c9e92a80f3a'::uuid, 'Quel nœud utilise-t-on pour s’encorder en escalade ?', 'mcq', '["Le nœud plat","Le nœud de chaise simple","Le nœud en huit tressé","Le nœud de cravate"]'::jsonb, 2, 'Il est suivi d’un nœud d’arrêt, et vérifié avant chaque départ.', 1),
    ('57cd03b7-9b13-5d44-aa98-f4e7e75a0c73'::uuid, '0b1e7f81-fe55-5291-bbd9-0c9e92a80f3a'::uuid, 'Que doit faire l’assureur en permanence ?', 'mcq', '["Garder une main sur le brin libre de la corde","Regarder les autres cordées","Lâcher la corde quand le grimpeur est haut","Tirer très fort sur la corde"]'::jsonb, 0, 'C’est le brin libre qui permet de bloquer une chute.', 2),
    ('4c3e57be-ee5c-5db8-87a6-51e09ebb8f1f'::uuid, '0b1e7f81-fe55-5291-bbd9-0c9e92a80f3a'::uuid, 'La vérification mutuelle avant de grimper peut être supprimée si l’on est pressé.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle est non négociable : la plupart des accidents viennent d’un oubli.', 3),
    ('148acf03-7396-5e90-acb9-11ef58826b64'::uuid, '0b1e7f81-fe55-5291-bbd9-0c9e92a80f3a'::uuid, 'Que signifie orienter sa carte ?', 'mcq', '["La plier correctement","Écrire son nom dessus","La colorier","Faire coïncider le nord de la carte et le nord réel"]'::jsonb, 3, 'On lit alors le terrain dans le même sens que la carte.', 4),
    ('25a99b29-6477-53f6-b5aa-244f2a642103'::uuid, '0b1e7f81-fe55-5291-bbd9-0c9e92a80f3a'::uuid, 'Sur une carte de course d’orientation, le bleu représente…', 'mcq', '["La forêt dense","L’eau","Le relief","Les routes"]'::jsonb, 1, 'Le vert indique la végétation dense, le marron le relief.', 5),
    ('4ca5ca61-c77c-57be-9029-413183da9d99'::uuid, '0b1e7f81-fe55-5291-bbd9-0c9e92a80f3a'::uuid, 'Qu’est-ce qu’une ligne directrice ?', 'mcq', '["Un élément linéaire facile à suivre : chemin, clôture, ruisseau","Le trait d’arrivée","La consigne du professeur","Une zone interdite"]'::jsonb, 0, 'Elle permet d’avancer vite sans se perdre.', 6),
    ('b6689283-5b39-5be3-9e20-4e982810ef49'::uuid, '0b1e7f81-fe55-5291-bbd9-0c9e92a80f3a'::uuid, 'Pourquoi un détour par un chemin peut-il être plus rapide qu’un trajet direct en forêt dense ?', 'mcq', '["Parce que le chemin est toujours plus court","Parce qu’il est interdit de traverser la forêt","Parce qu’on avance plus vite et qu’on se perd moins","Parce que les balises sont sur les chemins"]'::jsonb, 2, 'La distance ne fait pas tout : la vitesse de progression compte.', 7),
    ('18db4cdf-c308-592b-a859-5d99732d89b1'::uuid, '0b1e7f81-fe55-5291-bbd9-0c9e92a80f3a'::uuid, 'Que fait le contre-assureur ?', 'mcq', '["Il grimpe à côté","Il chronomètre","Il juge la voie","Il tient le brin libre derrière l’assureur"]'::jsonb, 3, 'Il ajoute une sécurité, surtout quand l’assureur débute.', 8),
    ('ac0d7ace-e4bf-5cac-b448-d276739d208d'::uuid, '0b1e7f81-fe55-5291-bbd9-0c9e92a80f3a'::uuid, 'En CA2, savoir renoncer fait partie de la compétence.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Choisir un défi à sa mesure inclut de savoir s’arrêter.', 9),
    ('f18f1290-2a0d-58f4-b035-9d24dc0f9e53'::uuid, '0b1e7f81-fe55-5291-bbd9-0c9e92a80f3a'::uuid, 'Qu’est-ce qu’un point d’attaque ?', 'mcq', '["Le départ de la course","Un élément facile à trouver près du poste, d’où l’on termine avec précision","Le poste le plus difficile","Un raccourci interdit"]'::jsonb, 1, 'On y arrive vite, puis on termine lentement et précisément.', 10),
    ('4e153bb7-e79d-5bf1-8b19-b222932d7b0c'::uuid, '0b1e7f81-fe55-5291-bbd9-0c9e92a80f3a'::uuid, 'Qu’est-ce qui caractérise le CA2 ?', 'mcq', '["Un adversaire direct","Un public qui juge","Un milieu variable ou incertain à lire","Une performance au chronomètre sur piste"]'::jsonb, 2, 'Le milieu change : il faut prélever des informations et s’adapter.', 11),
    ('86b4ee12-8e88-541a-b698-21451199c624'::uuid, '0b1e7f81-fe55-5291-bbd9-0c9e92a80f3a'::uuid, 'Que dit un grimpeur qui veut que l’assureur retienne la corde tendue ?', 'mcq', '["« Vas-y »","« Sec »","« Prêt »","« Du mou »"]'::jsonb, 1, 'On convient des consignes avant de partir.', 12),
    ('55a471f3-696d-5373-b771-fb60b19e4027'::uuid, 'b30e64dd-7d13-52f2-aabc-975a81658c3b'::uuid, 'Que désigne le canon en composition ?', 'mcq', '["Tous font le même geste en même temps","Le même geste réalisé avec un décalage d’un pratiquant à l’autre","Un geste très puissant","Un arrêt de la musique"]'::jsonb, 1, 'L’unisson, lui, fait tout faire en même temps.', 1),
    ('0bf519c7-0270-5128-b849-6148e7a39e57'::uuid, 'b30e64dd-7d13-52f2-aabc-975a81658c3b'::uuid, 'Quel critère évalue l’amplitude et la maîtrise d’un élément ?', 'mcq', '["La difficulté","La composition","L’exécution","L’originalité"]'::jsonb, 2, 'La difficulté mesure la valeur de l’élément, l’exécution sa qualité.', 2),
    ('ae72fb1d-bd25-536f-9cd6-b7ca4b514bb9'::uuid, 'b30e64dd-7d13-52f2-aabc-975a81658c3b'::uuid, 'Mieux vaut un élément simple parfaitement maîtrisé qu’un élément difficile raté.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Une chute ou un déséquilibre coûte souvent plus que la difficulté ne rapporte.', 3),
    ('bc45b3d5-028b-5adb-b8ef-c1b0e8805335'::uuid, 'b30e64dd-7d13-52f2-aabc-975a81658c3b'::uuid, 'En acrosport, sur quelles parties du porteur le voltigeur prend-il appui ?', 'mcq', '["Le milieu du dos","Les reins","La nuque","Le bassin et les épaules"]'::jsonb, 3, 'Ce sont des appuis solides, au-dessus des os.', 4),
    ('576b0d9a-87bd-54d5-b73c-26df3d0ea0a1'::uuid, 'b30e64dd-7d13-52f2-aabc-975a81658c3b'::uuid, 'Quel est le rôle du pareur ?', 'mcq', '["Accompagner ou retenir le pratiquant dans la zone de risque","Noter la prestation","Choisir la musique","Chronométrer"]'::jsonb, 0, 'Il est prêt à intervenir sans gêner l’exécution.', 5),
    ('a65f8754-d0c1-5c05-833e-e066a0ae791c'::uuid, 'b30e64dd-7d13-52f2-aabc-975a81658c3b'::uuid, 'Que produit l’accumulation ?', 'mcq', '["Un arrêt total","Une phrase qui s’enrichit d’un geste à chaque reprise","Un geste unique","Un décalage temporel"]'::jsonb, 1, 'Elle rend la construction visible au spectateur.', 6),
    ('903337c7-5bd8-549c-890c-422014499ce7'::uuid, 'b30e64dd-7d13-52f2-aabc-975a81658c3b'::uuid, 'Le CA3 se caractérise par…', 'mcq', '["Un adversaire direct","Une performance mesurée au mètre","Un milieu incertain","Une prestation destinée à être vue et appréciée"]'::jsonb, 3, 'Elle est jugée sur des critères connus d’avance.', 7),
    ('14c0261a-6c83-5592-b333-577aeb0c50af'::uuid, 'b30e64dd-7d13-52f2-aabc-975a81658c3b'::uuid, 'Le voltigeur peut sauter depuis le haut d’une pyramide pour en descendre.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'On descend par des appuis sûrs, jamais en sautant d’une position haute.', 8),
    ('5ef74c1c-3ed7-5093-acd0-3cbc206516c0'::uuid, 'b30e64dd-7d13-52f2-aabc-975a81658c3b'::uuid, 'Opposer lenteur et vitesse dans une chorégraphie relève du procédé de…', 'mcq', '["Contraste","Canon","Unisson","Répétition"]'::jsonb, 0, 'Le contraste rend chaque partie plus lisible.', 9),
    ('e08214d7-10e4-5af8-bbe0-fd57605b73ae'::uuid, 'b30e64dd-7d13-52f2-aabc-975a81658c3b'::uuid, 'Qu’apporte un observateur pendant les répétitions ?', 'mcq', '["Il remplace le juge le jour de l’épreuve","Il décide de la musique","Il rend compte de ce qui se voit réellement","Il porte le voltigeur"]'::jsonb, 2, 'Ce que l’on croit montrer n’est pas toujours ce qui se voit.', 10),
    ('b7531f89-c19c-5f2d-a963-262e0eac40a1'::uuid, 'b30e64dd-7d13-52f2-aabc-975a81658c3b'::uuid, 'Dans les activités artistiques, quel critère pèse particulièrement ?', 'mcq', '["La vitesse maximale","L’intention et l’interprétation","Le nombre de points marqués","La distance parcourue"]'::jsonb, 1, 'On y juge ce que la prestation transmet.', 11),
    ('f8eb3339-eac2-5d98-9506-01b15b2dc1c0'::uuid, 'b30e64dd-7d13-52f2-aabc-975a81658c3b'::uuid, 'Quelle première étape pour composer une prestation ?', 'mcq', '["Choisir la tenue","Tenter l’élément le plus difficile","Apprendre le règlement d’un autre sport","Choisir une intention ou un fil conducteur"]'::jsonb, 3, 'Tout le reste s’organise autour d’elle.', 12),
    ('0899c6cb-a521-58c1-b1fd-94aef792e87d'::uuid, '34a422f9-1d0f-5f96-b7a4-bb3471ba95aa'::uuid, 'Quelle est la différence entre stratégie et tactique ?', 'mcq', '["Aucune, ce sont deux synonymes","La stratégie se prépare avant ; la tactique se décide pendant le jeu","La tactique concerne seulement les sports collectifs","La stratégie est décidée par l’arbitre"]'::jsonb, 1, 'Le plan d’abord, la décision de l’instant ensuite.', 1),
    ('95e7e0ef-9436-5a84-852d-6cb042620455'::uuid, '34a422f9-1d0f-5f96-b7a4-bb3471ba95aa'::uuid, 'En attaque, que cherche-t-on à créer ?', 'mcq', '["Un déséquilibre en sa faveur","Un équilibre parfait","Une pause","Un contact avec l’arbitre"]'::jsonb, 0, 'Espace libre, surnombre, adversaire déplacé.', 2),
    ('285941d2-5dd8-5b66-811b-f8ead52d33e8'::uuid, '34a422f9-1d0f-5f96-b7a4-bb3471ba95aa'::uuid, '« Je vais jouer sur son revers, qu’il maîtrise mal » relève de…', 'mcq', '["La tactique","L’arbitrage","La stratégie","L’échauffement"]'::jsonb, 2, 'C’est un plan établi à partir des faiblesses de l’adversaire.', 3),
    ('7dc17504-951e-5abd-8295-ba8f9894564b'::uuid, '34a422f9-1d0f-5f96-b7a4-bb3471ba95aa'::uuid, 'Que faut-il faire au moment où l’on perd la balle ?', 'mcq', '["S’arrêter et protester","Attendre que le jeu se calme","Regarder le tableau d’affichage","Changer de rôle plus vite que l’adversaire"]'::jsonb, 3, 'Le passage de l’attaque à la défense est un moment décisif.', 4),
    ('d4935ed6-eb6b-59e1-b83b-69da3811d2a5'::uuid, '34a422f9-1d0f-5f96-b7a4-bb3471ba95aa'::uuid, 'Jouer toujours la même trajectoire rend un joueur difficile à lire.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est l’inverse : varier rend le jeu imprévisible.', 5),
    ('ca440462-e4a0-55c5-aa41-4904d2e7e59f'::uuid, '34a422f9-1d0f-5f96-b7a4-bb3471ba95aa'::uuid, 'Que signifie « jouer dans l’espace libre » ?', 'mcq', '["Viser là où l’adversaire n’est pas","Jouer sans filet","Jouer seul","Viser le centre du terrain"]'::jsonb, 0, 'C’est le principe commun à tous les affrontements.', 6),
    ('5719ba76-be51-5f4c-bb8e-6132ba448482'::uuid, '34a422f9-1d0f-5f96-b7a4-bb3471ba95aa'::uuid, 'En CA4, l’AFL1 s’évalue…', 'mcq', '["Par un écrit sur le règlement","Par une performance au chronomètre","En situation de match","Par une chorégraphie"]'::jsonb, 2, 'On croise le gain des rencontres et l’efficacité des choix.', 7),
    ('854338c5-0133-5496-b169-79d42bf8c4f3'::uuid, '34a422f9-1d0f-5f96-b7a4-bb3471ba95aa'::uuid, 'Quel relevé d’un observateur est utile à la stratégie ?', 'mcq', '["La couleur des maillots","Le nombre de spectateurs","La météo","Les points perdus selon la zone du terrain"]'::jsonb, 3, 'Il montre où l’adversaire fait mal.', 8),
    ('f9aeeb7a-6924-5583-9351-ba90e03e328f'::uuid, '34a422f9-1d0f-5f96-b7a4-bb3471ba95aa'::uuid, 'Un joueur qui perd de peu contre plus fort peut montrer de grandes qualités.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’évaluation regarde aussi l’efficacité des choix, pas seulement le score.', 9),
    ('7a3affc8-cdec-5f75-b384-8ac7bd47132d'::uuid, '34a422f9-1d0f-5f96-b7a4-bb3471ba95aa'::uuid, 'Que doit faire un défenseur pour rétablir l’équilibre ?', 'mcq', '["Rester immobile","Se replacer et fermer l’espace","Quitter le terrain","Attaquer seul"]'::jsonb, 1, 'Retrouver l’équilibre, c’est d’abord se replacer.', 10),
    ('26d3fe9a-994d-5eac-9e21-ef73a5d0bf80'::uuid, '34a422f9-1d0f-5f96-b7a4-bb3471ba95aa'::uuid, 'Pourquoi prélever des informations avant de recevoir la balle ?', 'mcq', '["Pour gagner du temps et choisir la meilleure option","Pour ralentir le jeu","Pour parler à l’arbitre","Ce n’est pas utile"]'::jsonb, 0, 'Celui qui sait déjà où jouer agit plus vite.', 11),
    ('98a317b2-e1aa-528a-9a74-23474d2340c9'::uuid, '34a422f9-1d0f-5f96-b7a4-bb3471ba95aa'::uuid, 'Au tennis de table, 7 points sur 10 sont perdus sur des balles longues dans le revers. Quelle stratégie en tirer ?', 'mcq', '["Ne rien changer","Jouer uniquement en revers","Se décaler pour attaquer davantage en coup droit","Abandonner le set"]'::jsonb, 2, 'On protège la zone faible repérée par l’observateur.', 12),
    ('a349630c-7e9f-5259-9a6a-2f38d245fd36'::uuid, 'f1c04ad3-3bbb-5385-82b8-761735d9c01e'::uuid, 'Qu’appelle-t-on le mobile en CA5 ?', 'mcq', '["Le téléphone utilisé pour chronométrer","La raison pour laquelle on s’entraîne","Le lieu d’entraînement","Le partenaire de séance"]'::jsonb, 1, 'Il oriente le choix des exercices et des intensités.', 1),
    ('9765a62f-821d-5ee4-b45b-65eaa49bfd1d'::uuid, 'f1c04ad3-3bbb-5385-82b8-761735d9c01e'::uuid, 'Comment calcule-t-on une FC cible par la méthode de Karvonen ?', 'mcq', '["FC repos + % × (FC max − FC repos)","FC max × 2","220 + âge","FC repos − FC max"]'::jsonb, 0, 'Elle tient compte de la fréquence cardiaque de repos de chacun.', 2),
    ('972001cf-898d-51d5-bbe1-dbb9be5f2b74'::uuid, 'f1c04ad3-3bbb-5385-82b8-761735d9c01e'::uuid, 'FC repos 70 bpm, FC max 190 bpm : quelle est la FC cible à 50 % de la réserve ?', 'mcq', '["95 bpm","120 bpm","130 bpm","140 bpm"]'::jsonb, 2, '70 + 0,5 × 120 = 130 bpm.', 3),
    ('3e31e006-4d0d-50ff-97ee-4d0f0a15bbbf'::uuid, 'f1c04ad3-3bbb-5385-82b8-761735d9c01e'::uuid, 'Pour développer la force maximale en musculation, on travaille…', 'mcq', '["Des charges légères et beaucoup de répétitions","Sans récupération","Uniquement en étirement","Des charges lourdes et peu de répétitions, avec une longue récupération"]'::jsonb, 3, 'L’endurance musculaire, elle, se travaille avec des charges légères et de nombreuses répétitions.', 4),
    ('bd711c7e-0ed3-5a40-96e1-a2e9cc287dfa'::uuid, 'f1c04ad3-3bbb-5385-82b8-761735d9c01e'::uuid, 'Si tu peux encore parler en courant, tu es probablement dans une zone d’endurance.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est le test de la parole, simple et utile sur le terrain.', 5),
    ('925751ec-9ff2-5ab4-9b36-73972270a455'::uuid, 'f1c04ad3-3bbb-5385-82b8-761735d9c01e'::uuid, 'Que doit contenir un bon carnet d’entraînement ?', 'mcq', '["Uniquement la durée de la séance","Le prévu, le réalisé, le ressenti et ce qu’on change","Les résultats des autres élèves","Une liste de courses"]'::jsonb, 1, 'Il sert à ajuster, et à montrer ses choix pour l’AFL2.', 6),
    ('62f59bc5-e86e-5324-843c-1f0df94ef73b'::uuid, 'f1c04ad3-3bbb-5385-82b8-761735d9c01e'::uuid, 'En musculation, la charge passe avant la qualité du geste.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Une charge qui déforme le mouvement expose à la blessure.', 7),
    ('f7e1a884-74cf-5795-802f-467f01acd7b9'::uuid, 'f1c04ad3-3bbb-5385-82b8-761735d9c01e'::uuid, 'Sur une échelle de ressenti de 0 à 10, que signifie 10 ?', 'mcq', '["Le repos complet","Un échauffement léger","Une allure de conversation","L’épuisement"]'::jsonb, 3, 'Cette échelle est un repère simple et fiable pour régler l’intensité.', 8),
    ('0b2b54cf-7740-5128-8b45-9ec14f9bb2c5'::uuid, 'f1c04ad3-3bbb-5385-82b8-761735d9c01e'::uuid, 'Quelle formule donne une estimation rapide de la FC maximale ?', 'mcq', '["220 − âge","180 + âge","Poids × 2","FC repos × 3"]'::jsonb, 0, 'Un test à l’effort donne une valeur plus juste.', 9),
    ('fead5c4b-847a-5cf9-a756-b181bda091d2'::uuid, 'f1c04ad3-3bbb-5385-82b8-761735d9c01e'::uuid, 'Quel mobile correspond au travail de 15 répétitions et plus avec une charge légère ?', 'mcq', '["La force maximale","La puissance explosive","L’endurance musculaire","La souplesse"]'::jsonb, 2, 'Beaucoup de répétitions, peu de charge, récupération courte.', 10),
    ('c0e0714e-e533-5312-9461-29f7e41858e4'::uuid, 'f1c04ad3-3bbb-5385-82b8-761735d9c01e'::uuid, 'Qui fixe le mobile en CA5 ?', 'mcq', '["L’arbitre","L’élève lui-même","Le club sportif","Personne"]'::jsonb, 1, 'C’est la spécificité de ce champ : on s’entraîne pour soi.', 11),
    ('8ec2237c-c4ad-501d-85ac-b4d589f1afbb'::uuid, 'f1c04ad3-3bbb-5385-82b8-761735d9c01e'::uuid, 'Après une séance ressentie à 9/10, que conclure dans le carnet ?', 'mcq', '["Augmenter aussitôt la charge","Supprimer toute récupération","Ne rien noter","Maintenir ou alléger la séance suivante"]'::jsonb, 3, 'Un effort très dur annonce une charge à stabiliser avant de progresser.', 12),
    ('4f79284b-042c-5791-8342-2aaa5c947477'::uuid, 'fd1d0de6-904e-5cec-ad56-92c08f146973'::uuid, 'Quel est l’ordre logique d’un échauffement ?', 'mcq', '["Spécifique, puis général, puis articulaire","Général, articulaire, puis spécifique","Uniquement des étirements","Articulaire seulement"]'::jsonb, 1, 'On part d’un effort modéré global vers les gestes de l’activité.', 1),
    ('65346cb1-1489-5ad0-927f-035db5f65fb8'::uuid, 'fd1d0de6-904e-5cec-ad56-92c08f146973'::uuid, 'Quel effet a l’échauffement sur les muscles ?', 'mcq', '["Il augmente leur température et leur souplesse","Il les refroidit","Il les fatigue définitivement","Aucun"]'::jsonb, 0, 'Un muscle chaud est plus souple et plus rapide.', 2),
    ('11e930bc-8f43-5d07-a42f-5ed0bd74e816'::uuid, 'fd1d0de6-904e-5cec-ad56-92c08f146973'::uuid, 'Avant un sprint, les étirements longs et statiques sont…', 'mcq', '["Indispensables","Obligatoires au bac","Déconseillés, car ils peuvent réduire temporairement la force et la vitesse","Sans aucun effet"]'::jsonb, 2, 'On leur préfère des mouvements dynamiques.', 3),
    ('28a0c8cc-11be-5a78-9c8b-d9f8eea1bc0b'::uuid, 'fd1d0de6-904e-5cec-ad56-92c08f146973'::uuid, 'Pourquoi ne pas s’arrêter brutalement après un effort intense ?', 'mcq', '["Pour gagner des points","Pour prolonger la séance","Parce que c’est le règlement","Pour aider le cœur à ralentir progressivement et récupérer"]'::jsonb, 3, 'Quelques minutes d’activité légère favorisent la récupération.', 4),
    ('6a0577dd-004b-5590-b335-becd5da4ab05'::uuid, 'fd1d0de6-904e-5cec-ad56-92c08f146973'::uuid, 'Un échauffement doit être adapté à l’activité pratiquée.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'On ne se prépare pas pour un sprint comme pour une séance de yoga.', 5),
    ('75628a95-e7a5-5401-930f-d9cc04409e30'::uuid, 'fd1d0de6-904e-5cec-ad56-92c08f146973'::uuid, 'Quand l’organisme répare-t-il et se renforce-t-il surtout ?', 'mcq', '["Pendant l’échauffement","Pendant le sommeil","Pendant l’effort maximal","Pendant le trajet"]'::jsonb, 1, 'Le sommeil est un temps fort de la récupération.', 6),
    ('f258de4e-1486-53a7-a1bb-cc949a51f50f'::uuid, 'fd1d0de6-904e-5cec-ad56-92c08f146973'::uuid, 'Qu’est-ce que la récupération active ?', 'mcq', '["Une activité très légère après l’effort","Un deuxième match","Un sprint final","Un jeûne"]'::jsonb, 0, 'Elle entretient la circulation sanguine.', 7),
    ('ae81b96e-5f68-551f-a4b9-7c4d2cde997d'::uuid, 'fd1d0de6-904e-5cec-ad56-92c08f146973'::uuid, 'Que doit contenir la partie spécifique de l’échauffement ?', 'mcq', '["Des jeux de société","Une sieste","Les gestes de l’activité, de plus en plus intenses","Uniquement de la marche"]'::jsonb, 2, 'On rapproche peu à peu l’intensité de celle de l’épreuve.', 8),
    ('93ee2346-6a84-5e0f-9f1a-2e7113bff608'::uuid, 'fd1d0de6-904e-5cec-ad56-92c08f146973'::uuid, 'Après un sprint maximal, la récupération entre deux répétitions doit être…', 'mcq', '["Nulle","De quelques secondes","De plusieurs heures","De quelques minutes"]'::jsonb, 3, 'La filière alactique a besoin de temps pour se reconstituer.', 9),
    ('4b0b0f3f-d176-5279-a5b5-1b82b4e7a7d5'::uuid, 'fd1d0de6-904e-5cec-ad56-92c08f146973'::uuid, 'L’échauffement n’a aucun effet sur la concentration.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il prépare aussi mentalement à l’activité.', 10),
    ('5e1f0e09-f666-56d9-8550-273447e89a95'::uuid, 'fd1d0de6-904e-5cec-ad56-92c08f146973'::uuid, 'À quoi sert l’hydratation après l’effort ?', 'mcq', '["À compenser l’eau perdue par la sueur","À refroidir le terrain","À augmenter le poids","À rien"]'::jsonb, 0, 'On boit avant, pendant et après l’effort.', 11),
    ('056ddc87-4516-5fa0-a8cf-cd7113f84ee8'::uuid, 'fd1d0de6-904e-5cec-ad56-92c08f146973'::uuid, 'Quand placer des étirements doux et prolongés ?', 'mcq', '["Juste avant un sprint","Pendant un match","À distance de l’effort","Jamais"]'::jsonb, 2, 'Ils entretiennent l’amplitude sans gêner la performance.', 12),
    ('88bda8d2-129b-597a-9c41-bcc9618fff1f'::uuid, 'deebdf5e-9cc6-5182-93eb-0a79a7e870fb'::uuid, 'Lequel de ces éléments relève de la sécurité passive ?', 'mcq', '["Le respect des consignes","La parade","Le tapis de réception","L’échauffement"]'::jsonb, 2, 'La sécurité passive, c’est le matériel et l’aménagement.', 1),
    ('0943fe38-ec3b-5eac-a640-7cf9add1e4a6'::uuid, 'deebdf5e-9cc6-5182-93eb-0a79a7e870fb'::uuid, 'Que faire en cas de choc à la tête avec vertiges ou maux de tête ?', 'mcq', '["Arrêter immédiatement et ne pas reprendre le jour même","Continuer si la douleur est supportable","Boire une boisson énergisante","Faire des étirements"]'::jsonb, 0, 'Une commotion cérébrale peut passer inaperçue et s’aggraver.', 2),
    ('f58c0a1e-a22d-522d-ae7e-f1705de4340c'::uuid, 'deebdf5e-9cc6-5182-93eb-0a79a7e870fb'::uuid, 'Quel est le premier réflexe après une entorse de cheville ?', 'mcq', '["Courir pour la chauffer","Masser vigoureusement","Appliquer de la chaleur","Arrêter, appliquer du froid et surélever"]'::jsonb, 3, 'Puis faire examiner si la douleur ou le gonflement persistent.', 3),
    ('c0dcd360-e223-5290-aafd-5195f0e36c80'::uuid, 'deebdf5e-9cc6-5182-93eb-0a79a7e870fb'::uuid, 'Les accidents surviennent souvent en fin de séance, à cause de la fatigue.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'La fatigue dégrade la vigilance et la qualité du geste.', 4),
    ('f2df3e79-2184-5275-9ed4-7edb9619e7be'::uuid, 'deebdf5e-9cc6-5182-93eb-0a79a7e870fb'::uuid, 'Qu’est-ce qu’une entorse ?', 'mcq', '["Une fracture de l’os","Un étirement ou une déchirure de ligament","Une crampe","Une inflammation de la peau"]'::jsonb, 1, 'Elle touche souvent la cheville.', 5),
    ('10d2a3d6-5395-5f57-b69e-955d69220cbe'::uuid, 'deebdf5e-9cc6-5182-93eb-0a79a7e870fb'::uuid, 'Quelle est la bonne réaction face à une crampe ?', 'mcq', '["Étirer doucement le muscle et s’hydrater","Frapper le muscle","Continuer au même rythme","Appliquer de la chaleur intense"]'::jsonb, 0, 'La crampe est une contraction involontaire.', 6),
    ('931eb0f5-c0ca-506f-9219-cfce589c88f0'::uuid, 'deebdf5e-9cc6-5182-93eb-0a79a7e870fb'::uuid, 'Dans quel ordre agir face à un accident ?', 'mcq', '["Secourir, alerter, protéger","Alerter, protéger, secourir","Protéger, alerter, secourir","Attendre, puis alerter"]'::jsonb, 2, 'On sécurise d’abord pour éviter un sur-accident.', 7),
    ('59e36274-c114-5863-9085-a1c4cb1b90a4'::uuid, 'deebdf5e-9cc6-5182-93eb-0a79a7e870fb'::uuid, 'Faut-il déplacer une personne qui pourrait être blessée à la nuque ?', 'mcq', '["Oui, pour la mettre à l’ombre","Oui, pour qu’elle se relève","Oui, pour libérer le terrain","Non, sauf danger immédiat"]'::jsonb, 3, 'Un déplacement peut aggraver une lésion de la colonne.', 8),
    ('664638fa-2ea3-56fd-bf96-4e5d7a1d9f99'::uuid, 'deebdf5e-9cc6-5182-93eb-0a79a7e870fb'::uuid, 'Signaler une douleur au professeur, c’est se plaindre inutilement.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Cela lui permet d’adapter la séance et d’éviter une blessure.', 9),
    ('bbdffd8a-fafb-5829-ab54-ecf6b2347629'::uuid, 'deebdf5e-9cc6-5182-93eb-0a79a7e870fb'::uuid, 'Qu’est-ce qu’une tendinite ?', 'mcq', '["Une inflammation du tendon souvent liée au surmenage","Une entorse","Une crampe passagère","Un choc à la tête"]'::jsonb, 0, 'Elle impose un repos relatif et un avis médical.', 10),
    ('bdf9dd63-7ac7-50d7-88cb-00eb3f490e4d'::uuid, 'deebdf5e-9cc6-5182-93eb-0a79a7e870fb'::uuid, 'Quel numéro d’urgence européen peut-on composer ?', 'mcq', '["17","112","3919","36 15"]'::jsonb, 1, 'Le 15 (SAMU) et le 18 (pompiers) fonctionnent aussi en France.', 11),
    ('5933557c-c53e-5659-a179-41f5681b1066'::uuid, 'deebdf5e-9cc6-5182-93eb-0a79a7e870fb'::uuid, 'Une inaptitude partielle…', 'mcq', '["Dispense forcément de toute activité","N’a aucune conséquence","Permet souvent une pratique adaptée","Interdit de venir en cours"]'::jsonb, 2, 'L’enseignant adapte la pratique à ce que l’élève peut faire.', 12),
    ('2c721fc3-fe37-548b-b12d-b9817ccfe49b'::uuid, '462a694f-f248-5303-af12-c11d2057d40b'::uuid, 'Dans combien de rôles au moins l’élève est-il évalué pour l’AFL3 ?', 'mcq', '["Aucun","Un","Trois","Tous les rôles possibles"]'::jsonb, 1, 'Un rôle choisi parmi au moins deux proposés par l’équipe EPS.', 1),
    ('7341bed3-3aec-5caa-9c16-bb6004865d66'::uuid, '462a694f-f248-5303-af12-c11d2057d40b'::uuid, 'Quel degré correspond à un élève qui applique le règlement, le fait respecter et aide les autres dans leurs rôles ?', 'mcq', '["Engagement subi","Engagement aléatoire","Engagement fonctionnel","Engagement solidaire"]'::jsonb, 3, 'C’est le degré 4, le plus abouti.', 2),
    ('d41b35ed-01b3-5ef3-9e94-f6879174b481'::uuid, '462a694f-f248-5303-af12-c11d2057d40b'::uuid, 'Un élève connaît et applique le règlement mais ne le fait pas respecter. Son engagement est…', 'mcq', '["Aléatoire","Solidaire","Fonctionnel","Subi"]'::jsonb, 0, 'C’est le degré 2.', 3),
    ('b9c70b8c-b9ab-55ab-841b-7e7ef3433b69'::uuid, '462a694f-f248-5303-af12-c11d2057d40b'::uuid, 'Quel rôle garantit la sécurité d’un grimpeur ?', 'mcq', '["Le juge","Le chronométreur","L’assureur","Le starter"]'::jsonb, 2, 'On le trouve surtout dans le CA2.', 4),
    ('e7f3e96f-d83b-5162-bc24-78d6eea94f30'::uuid, '462a694f-f248-5303-af12-c11d2057d40b'::uuid, 'Comment se répartissent les 8 points des AFL2 et AFL3 au bac ?', 'mcq', '["Toujours 4 et 4","Au choix de l’élève : 4/4, 6/2 ou 2/6","Au choix du professeur uniquement","Tout sur l’AFL3"]'::jsonb, 1, 'L’élève choisit la répartition parmi ces trois possibilités.', 5),
    ('de0d394e-b14b-5bdc-83b3-61dd210cd707'::uuid, '462a694f-f248-5303-af12-c11d2057d40b'::uuid, 'Un bon arbitre doit rester impartial, même avec ses amis.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'L’impartialité fait la légitimité de ses décisions.', 6),
    ('096f4085-35bf-5526-8ebc-b9b4c0bb45dc'::uuid, '462a694f-f248-5303-af12-c11d2057d40b'::uuid, 'Que fait un observateur ?', 'mcq', '["Il relève des informations fiables et les transmet","Il joue à la place d’un partenaire","Il fixe la note finale","Il choisit la musique"]'::jsonb, 0, 'Ses relevés nourrissent l’analyse du pratiquant.', 7),
    ('213e3850-c9ca-59cf-88ee-0dec03ce92e2'::uuid, '462a694f-f248-5303-af12-c11d2057d40b'::uuid, 'Où se place un arbitre pour bien décider ?', 'mcq', '["Le plus loin possible","Dans les tribunes","Là où il voit le mieux l’action","Derrière le banc"]'::jsonb, 2, 'Une bonne décision commence par un bon placement.', 8),
    ('988f5520-8ab2-55fc-ac96-1b5e8eb3a468'::uuid, '462a694f-f248-5303-af12-c11d2057d40b'::uuid, 'Quelle remarque d’observateur est la plus utile ?', 'mcq', '["« Tu joues mal »","« Fais mieux »","« C’est nul »","« 5 attaques sur 7 sont allées au centre : vise les côtés »"]'::jsonb, 3, 'Une donnée précise et un conseil concret font progresser.', 9),
    ('55630e6c-c791-52d8-864e-c4c491d46707'::uuid, '462a694f-f248-5303-af12-c11d2057d40b'::uuid, 'Le juge apprécie une prestation selon des critères connus d’avance.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est le rôle typique du CA3.', 10),
    ('a282c640-261d-55d2-9c3c-68183d73ca35'::uuid, '462a694f-f248-5303-af12-c11d2057d40b'::uuid, 'Que demande l’engagement fonctionnel ?', 'mcq', '["Connaître le règlement seulement en partie","Connaître, appliquer et faire respecter le règlement dans son rôle","Ne rien transmettre","Jouer à la place des autres"]'::jsonb, 1, 'C’est le degré 3 : les informations sont prélevées et transmises.', 11),
    ('8e83da5f-341a-58ac-800f-75adcd8f3b4d'::uuid, '462a694f-f248-5303-af12-c11d2057d40b'::uuid, 'Quel rôle trouve-t-on surtout dans le CA1 ?', 'mcq', '["Le pareur en acrosport","L’arbitre de match","Le coach de danse","Le chronométreur"]'::jsonb, 3, 'La performance y est mesurée au temps ou à la distance.', 12),
    ('6370d58d-cd23-5b4d-b9cc-c6d22dd8e8e1'::uuid, '9057ede4-dac5-5ab6-a7cd-45d6f0d170e7'::uuid, 'Combien d’épreuves compte le contrôle en cours de formation d’EPS au bac ?', 'mcq', '["Une","Deux","Trois","Cinq"]'::jsonb, 2, 'Trois épreuves, sur trois activités distinctes.', 1),
    ('6736ccca-9900-5ad6-9442-51d76a23ae88'::uuid, '9057ede4-dac5-5ab6-a7cd-45d6f0d170e7'::uuid, 'Les trois épreuves doivent relever…', 'mcq', '["Du même champ d’apprentissage","De trois champs d’apprentissage différents","Uniquement des sports collectifs","De deux champs au choix"]'::jsonb, 1, 'C’est une obligation fixée par la note de service.', 2),
    ('a7a1626e-5516-5c3e-bc5c-d192eb3779c7'::uuid, '9057ede4-dac5-5ab6-a7cd-45d6f0d170e7'::uuid, 'Sur combien de points est noté l’AFL1 dans chaque épreuve ?', 'mcq', '["12","8","6","20"]'::jsonb, 0, 'Les AFL2 et AFL3 se partagent les 8 points restants.', 3),
    ('466bd2a6-e190-539b-bb49-317649fcac40'::uuid, '9057ede4-dac5-5ab6-a7cd-45d6f0d170e7'::uuid, 'Laquelle de ces répartitions AFL2 / AFL3 est possible ?', 'mcq', '["8 / 0","5 / 3","0 / 8","6 / 2"]'::jsonb, 3, 'Les trois choix sont 4/4, 6/2 et 2/6.', 4),
    ('7c10cf3d-c4b0-5d1a-97a2-68fcf41b024f'::uuid, '9057ede4-dac5-5ab6-a7cd-45d6f0d170e7'::uuid, 'Quel est le coefficient de l’EPS au baccalauréat ?', 'mcq', '["2","6","10","16"]'::jsonb, 1, 'L’EPS pèse autant qu’une matière importante du tronc commun.', 5),
    ('3cb9523f-b689-5b61-852d-f677d35115a8'::uuid, '9057ede4-dac5-5ab6-a7cd-45d6f0d170e7'::uuid, 'Une absence non justifiée à une épreuve entraîne…', 'mcq', '["Un 0 à cette épreuve, non éliminatoire","L’élimination du bac","Une simple remarque","Le report automatique de l’épreuve"]'::jsonb, 0, 'Elle fait chuter la moyenne des trois épreuves.', 6),
    ('23b6d3b1-623d-534a-9d97-062672e3ea06'::uuid, '9057ede4-dac5-5ab6-a7cd-45d6f0d170e7'::uuid, 'Combien d’activités au moins doivent venir de la liste nationale ?', 'mcq', '["Aucune","Une","Deux","Trois"]'::jsonb, 2, 'La troisième peut venir de la liste académique ou de l’établissement.', 7),
    ('57ef2399-245b-5d17-84f7-78594cf28f4f'::uuid, '9057ede4-dac5-5ab6-a7cd-45d6f0d170e7'::uuid, 'L’AFL2 et l’AFL3 s’évaluent uniquement le jour de l’épreuve.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Ils s’évaluent au fil de la séquence et sont finalisés le jour de l’épreuve.', 8),
    ('2cca0130-cacf-5065-8178-1499dce03f26'::uuid, '9057ede4-dac5-5ab6-a7cd-45d6f0d170e7'::uuid, 'Qui évalue les épreuves du CCF ?', 'mcq', '["Un jury extérieur uniquement","L’élève lui-même","Le chef d’établissement seul","Deux enseignants d’EPS, dont celui de la classe"]'::jsonb, 3, 'C’est le principe de la co-évaluation.', 9),
    ('6dc57ef3-38d6-525d-8dbd-ab2baabd9be5'::uuid, '9057ede4-dac5-5ab6-a7cd-45d6f0d170e7'::uuid, 'Un élève obtient 15, 13 et 11. Sa note finale d’EPS vaut…', 'mcq', '["11/20","13/20","15/20","39/20"]'::jsonb, 1, '(15 + 13 + 11) / 3 = 13.', 10),
    ('116a86d3-32f0-517a-bfb7-b7c87ca6fce6'::uuid, '9057ede4-dac5-5ab6-a7cd-45d6f0d170e7'::uuid, 'Un candidat individuel passe l’EPS en examen ponctuel sur deux activités.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le CCF concerne les élèves scolarisés en lycée public ou privé sous contrat.', 11),
    ('1fbd6cb7-6559-54c7-a68d-ab1d33e95cb4'::uuid, '9057ede4-dac5-5ab6-a7cd-45d6f0d170e7'::uuid, 'En cas de blessure temporaire attestée, que prévoit l’établissement ?', 'mcq', '["Un 0 automatique","Une dispense définitive de l’EPS","Une épreuve adaptée ou différée","Rien du tout"]'::jsonb, 2, 'La blessure doit être authentifiée par l’autorité médicale scolaire.', 12)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('grec', 'latin', 'llcer-anglais', 'musique', 'si', 'sport');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('grec', 'latin', 'llcer-anglais', 'musique', 'si', 'sport')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 387 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 387 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
